import type { Chapter } from '../types'

export const PART: Chapter[] = [{"n":12,"title":"创业与做生意：别把家底赔进去","intro":"本节口径是金钱与法律责任：开一家店、办一家公司，哪一步会让你的个人财产、家庭财产和配偶财产跟着担责，法律怎么规定、能不能提前隔开，不换算成寿命。排序按「最容易把家底赔进去、最省事就能避免」从高到低，签字类的放最前，需要做事的方法条目靠后，经验条目标 C 级。","entries":[{"id":"12.1","sec":12,"n":1,"title":"只拿亏得起的钱创业，不动家底、不借钱开张","cost":"0 元；动手前给自己定一个数，全亏掉也不影响还房贷、养孩子、看病，超过这个数就不投；家里人的钱和借来的钱不算在这个数里","human":"个体户欠的钱要拿个人财产还，分不清是家庭经营的就拿全家财产还；夫妻一起签字、或者借来的钱用于两人共同经营的，两个人的家产一起还。公司还不上到期债务时，认缴了还没到期的出资也会被要求提前拿出来。所以投进去的额度按「全亏光也照样还房贷、看病」来定。","gain":"亏了不只是钱没了：个体工商户的债务，个人经营的以个人财产承担，家庭经营或分不清的以家庭财产承担；夫妻共同签字或事后追认的债务是共同债务，一方以个人名义借的钱只要债权人能证明用于夫妻共同生产经营，也按共同债务算；公司还不上到期债务时，认缴了还没到期的出资债权人可以要求提前缴（全国）","grade":"B","src":"全国人大 (2020). 民法典（第五十六、一千零六十四条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；全国人大常委会 (2023). 公司法（2023 年修订，第四十七、五十四条）. <https://www.gov.cn/yaowen/liebiao/202312/content_6923395.htm>","note":"企业存活率、平均寿命一类的官方统计本次未能在国家统计局、市场监管总局官网找到可核实的原文，故不写数字，只写法律后果，定 B 级。「亏得起」的意思是全亏掉也不用卖房、不用找亲戚借钱补窟窿。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"12.2","sec":12,"n":2,"title":"不给公司贷款签个人担保，配偶更不要跟着签","cost":"0 元；银行、供应商、房东要求「股东个人连带担保」「配偶签字」时，把那一页当作放弃有限责任来看，能不签就不签，要签也只签一般保证并写明担保金额上限","human":"签了「连带责任保证」，公司还不上钱，债权人可以跳过公司直接找你要；写「一般保证」才是先告公司、执行完公司财产还差才轮到你。配偶跟着签字，就变成两个人的家产一起还——这一页签下去，有限公司的「有限」对你个人就不作数了。","gain":"保证合同就是约定债务人不还时由你来还；写「连带责任保证」的，债权人可以不找公司直接找你；写「一般保证」的，要先起诉或仲裁并强制执行公司财产仍还不上，才轮到你。夫妻共同签字或事后追认的债务是夫妻共同债务，配偶签了字就是两个人的家产一起还（全国，2021 年起）","grade":"A","src":"全国人大 (2020). 民法典（第六百八十一、六百八十七、六百八十八、一千零六十四条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>","note":"小微企业贷款实务中银行几乎都要股东个人连带担保，这条的意思不是「别贷款」，而是签之前知道签掉的是什么，把担保额限定在第 1 条那个「亏得起」的数以内。借条和担保书的一般规则见第 8 节第 16 条。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"12.3","sec":12,"n":3,"title":"开张前选对主体：个体户和合伙人赔到底，有限公司才「有限」","cost":"登记在当地政务服务网办，主要成本是有限公司之后每月记账报税的时间或代理记账费（各地不同）；一次性数小时","human":"个体户和普通合伙人赔到底，有限公司股东只赔认缴的那个数。但认缴多少 5 年内就要真掏出来，注册资本填 100 万就是 100 万的潜在债务；抽走的出资要还回来，公司账和自家账混着用、一人公司说不清两笔钱是分开的，「有限」照样失效。","gain":"个体工商户债务以个人或家庭财产承担；普通合伙企业的合伙人对合伙企业债务承担无限连带责任，有限合伙里只有有限合伙人以认缴出资为限；有限责任公司股东以认缴出资额为限对公司承担责任。但「有限」会在三种情况下失效：认缴出资要在公司成立起 5 年内缴足，公司还不上到期债务时债权人可要求提前缴；抽逃出资要返还；滥用公司独立地位逃债的、一人公司股东证明不了公司财产和自己财产分开的，对公司债务承担连带责任（全国，2024 年 7 月起）","grade":"A","src":"全国人大 (2020). 民法典（第五十六条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；全国人大常委会 (2006). 合伙企业法（2006 年修订，第二条）. <http://www.gov.cn/gongbao/content/2006/content_413955.htm>；全国人大常委会 (2023). 公司法（2023 年修订，第四、二十三、四十七、五十三、五十四条）. <https://www.gov.cn/yaowen/liebiao/202312/content_6923395.htm>","note":"「有限」的前提是公私分明：公司账户和个人账户不混用、不用公司的钱付家用、账目留全。注册资本别为了好看填大数，认缴多少 5 年内就要真拿出多少，填 100 万就是 100 万的潜在债务。","money":"少","time":"中","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"12.4","sec":12,"n":4,"title":"不当挂名股东，不替人代持股权","cost":"0 元；拒绝「借你身份证挂个股东」「股份先放你名下」的请求","human":"名字登记在册就是法律上的股东：认缴的出资要按期缴足，缴不上除了补缴还要赔公司损失；公司设立时别的股东没实缴的，你在缺口范围内跟着担责。生意是别人做的，债记在你名下。","gain":"登记在册的股东就是法律上的股东：要按章程按期足额缴纳认缴出资，没按期缴的除了补缴还要赔公司损失；公司设立时有股东没实缴的，设立时的其他股东在出资不足范围内连带；公司还不上到期债务时，债权人可以要求没到期的认缴出资提前缴。实际经营的人不在登记上，债却记在你名下（全国，2024 年 7 月起）","grade":"B","src":"全国人大常委会 (2023). 公司法（2023 年修订，第四十七、四十九、五十、五十四条）. <https://www.gov.cn/yaowen/liebiao/202312/content_6923395.htm>","note":"名义股东与实际出资人之间代持协议的效力和责任分配规定在最高法关于适用公司法若干问题的规定（三）里，TODO（待核实：法释文号及第二十四、二十五条原文，本次未能打开最高法官网原文页），故定 B 级。挂名法定代表人的风险见第 8 节第 26 条。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":true,"ratio":"极高"},{"id":"12.5","sec":12,"n":5,"title":"加盟前先查商务部备案，拿到书面披露，把「冷静期」写进合同","cost":"0 元；到商务部商业特许经营信息管理系统查品牌方备案，要求对方在签约前给书面信息披露和合同文本，几小时能做完","human":"按规定品牌方得有 2 个直营店、开满 1 年，签约后 15 日内到商务部门备案，不备案罚 1 万到 5 万、逾期不备案 5 万到 10 万还要公告。签约前它必须书面给你加盟费和保证金退还条件、现有门店经营状况、近两年审计摘要、近五年诉讼等 12 项。查不到备案、不肯给披露文件、要先交钱才让看合同的，直接走。","gain":"法规要求特许人至少有 2 个直营店且经营超过 1 年，首次签加盟合同起 15 日内向商务主管部门备案，不备案罚 1 万到 5 万元、逾期不备案罚 5 万到 10 万元并公告；签约前须书面披露加盟费种类和金额、保证金退还条件、现有加盟店数量和经营状况、近 2 年审计报告摘要、近 5 年诉讼仲裁情况等 12 项；合同必须约定加盟商在签约后一定期限内可以单方解除；隐瞒有关信息或提供虚假信息的，加盟商可以解除合同（全国，2007 年 5 月起）","grade":"A","src":"国务院 (2007). 商业特许经营管理条例（国务院令第 485 号，第七、八、十二、二十二、二十三、二十五条）. <https://www.gov.cn/zhengce/zhengceku/2008-03/28/content_4179.htm>；商务部 (2012). 商业特许经营信息披露管理办法（商务部令 2012 年第 2 号，第五、九条）. <http://www.gov.cn/gongbao/content/2012/content_2177025.htm>；商务部. 商业特许经营信息管理系统. <https://txjy.syggs.mofcom.gov.cn/>","note":"查不到备案、不肯给披露文件、要先交钱再看合同的，直接走。「冷静期」具体多少天由合同约定，条例只说「一定期限」，签约时要求写明天数。披露里的「现有加盟店平均销售量、毛利、纯利」要追问数据来源，办法要求特许人说明来源。","money":"0","time":"中","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"12.6","sec":12,"n":6,"title":"注册前把名称、经营场所、经营范围和注册资本定下来，材料齐了当场就能领执照","cost":"企业注册登记费和个体工商户注册登记费自 2015 年 1 月 1 日起停征，登记本身不花钱；自己在当地政务服务网或大厅办，一次性数小时。刻章、代理记账、地址托管是市场化支出，不是行政收费","human":"登记本身不花钱，注册费 2015 年起就停征了；要交的材料就法定那五项，齐了当场发照，当场发不了的 3 个工作日内办完。名称自己申报，注册资本自己认缴，被收的那笔多半是代办跑腿费。","gain":"条例把要交的材料写死为五项：「（一）申请书；（二）申请人资格文件、自然人身份证明；（三）住所或者主要经营场所相关文件；（四）公司、非公司企业法人、农民专业合作社（联合社）章程或者合伙企业合伙协议；（五）法律、行政法规和国务院市场监督管理部门规定提交的其他材料」，公司还要交法定代表人、董事、监事和高级管理人员的任职文件和身份证明，个体户不用章程；名称「由申请人依法自主申报」，注册资本「实行认缴登记制」，经营范围按登记机关公布的分类标准选；材料齐全、符合法定形式的「予以确认并当场登记」，不能当场的「3 个工作日内」办完，情形复杂的再延 3 个工作日；「营业执照签发日期为市场主体的成立日期」（全国，2022 年 3 月起）","grade":"A","src":"国务院 (2021). 市场主体登记管理条例（国务院令第 746 号，第十、十三、十四、十六、十九、二十一条）. <https://www.gov.cn/gongbao/content/2021/content_5636139.htm> ; 市场监管总局 (2022). 市场主体登记管理条例实施细则（市场监管总局令第 52 号，第十二、二十五、二十六条）. <https://www.gov.cn/zhengce/zhengceku/2022-03/02/content_5676403.htm> ; 财政部、国家发展改革委 (2014). 关于取消、停征和免征一批行政事业性收费的通知（财税〔2014〕101 号，附件 1）. <https://www.gov.cn/zhengce/2014-12/23/content_5023513.htm>","note":"登记不收费，被收的那笔多半是代办费。刻章价格由市场形成，国务院办公厅明令「严禁指定公章制作单位制作公章」，不必接受「必须在指定地方刻章」的说法。注册资本填多少不影响门面，只决定你的责任上限，5 年内要缴足，见本节第 3 条（开张前选对主体）；经营范围里带许可项目的，证没下来不能开张，见本节第 7 条","money":"0","time":"中","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"12.7","sec":12,"n":7,"title":"要许可证的行当，证没下来不开张","cost":"0 元；开张前查清自己的经营项目要不要许可（餐饮和食品销售要食品经营许可，只卖预包装食品改为备案），证下来再营业","human":"没证就开张，轻的是责令停业、没收违法所得、罚 1 万以下；碰上专营专卖物品，或者证券、期货、保险、资金支付结算这几类，情节严重就是非法经营罪，5 年以下起步、罚金是违法所得的 1 到 5 倍。先装修后办证、证下来前先试营业，是常见的一脚。","gain":"未取得许可从事经营活动的，由法律法规规定的部门查处；无照经营法律没有明确罚则的，责令停止、没收违法所得、并处 1 万元以下罚款。未经许可经营法律法规规定的专营、专卖或限制买卖的物品，未经批准经营证券、期货、保险或资金支付结算业务，情节严重构成非法经营罪，处 5 年以下有期徒刑或拘役并处违法所得 1 到 5 倍罚金，情节特别严重 5 年以上（全国）","grade":"A","src":"国务院 (2017). 无证无照经营查处办法（国务院令第 684 号，第五、六、十三条）. <https://www.gov.cn/zhengce/zhengceku/2017-08/23/content_5219861.htm>；市场监管总局 (2023). 食品经营许可和备案管理办法（市场监管总局令第 78 号，第四条）. <https://www.gov.cn/gongbao/2023/issue_10606/202307/content_6894763.html>；全国人大 (1997). 刑法（第二百二十五条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>","note":"金融、医疗、教培类的许可条件各有专门法律，本条只核实了通用查处规则和刑法条款。奶茶店、小吃店属于餐饮服务，要食品经营许可；先装修后办证、证下来前试营业是常见踩坑点。","money":"0","time":"中","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"12.8","sec":12,"n":8,"title":"领了执照就开始有申报义务，没有收入也要按期零申报","cost":"0 元；自己在电子税务局按月或按季申报，几分钟一次；请人代记账是另一笔市场化开支。用人的还要自成立之日起 30 日内办社保登记","human":"领了执照就开始有申报义务，一分钱没赚也要按期做零申报。不报先罚 2000 元以下，情节严重罚 2000 到 1 万；因为不报少缴了税，补税加每天万分之五的滞纳金，还要罚少缴税款的 0.5 到 5 倍。连着三个月所有税种都不报，系统自动认成非正常户，发票停用。用了人还要在成立后 30 天内办社保登记。","gain":"「纳税人在纳税期内没有应纳税款的，也应当按照规定办理纳税申报」；不按期申报的「由税务机关责令限期改正，可以处二千元以下的罚款；情节严重的，可以处二千元以上一万元以下的罚款」；不申报又少缴税款的，追缴税款和滞纳金并处少缴税款「百分之五十以上五倍以下的罚款」，滞纳金按日加收万分之五；「连续三个月所有税种均未进行纳税申报的，税收征管系统自动将其认定为非正常户，并停止其发票领用簿和发票的使用」，补申报并接受处罚后自动解除；用人单位「应当自成立之日起三十日内……向当地社会保险经办机构申请办理社会保险登记」（全国）","grade":"A","src":"国务院 (2002). 税收征收管理法实施细则（国务院令第 362 号，第三十二、七十五条）. <https://fgk.chinatax.gov.cn/zcfgk/c100010/c5195082/content.html> ; 全国人大常委会 (2015). 税收征收管理法（2015 年修正，第二十五、三十二、六十二、六十四条）. <https://fgk.chinatax.gov.cn/zcfgk/c100009/c5195081/content.html> ; 国家税务总局 (2019). 关于税收征管若干事项的公告（国家税务总局公告 2019 年第 48 号，第三条）. <https://fgk.chinatax.gov.cn/zcfgk/c100012/c5195194/content.html> ; 全国人大常委会 (2018). 个人所得税法（2018 年修正，第十二条）. <https://fgk.chinatax.gov.cn/zcfgk/c100009/c5193028/content.html> ; 全国人大常委会 (2018). 社会保险法（2018 年修正，第五十七条）. <http://www.npc.gov.cn/zgrdw/npc/xinwen/2019-01/07/content_2070267.htm>","note":"「多证合一」之后不再单独办税务登记，拿营业执照上的统一社会信用代码登录电子税务局做登记信息确认和税费种认定即可。个体工商户和个人独资企业交的是经营所得个税，「在月度或者季度终了后十五日内」预缴，「在取得所得的次年三月三十一日前办理汇算清缴」。没开张也要报，零申报同样是申报；放着不管三个月就成非正常户，发票停用，注销也走不了简易程序，见本节第 19 条","money":"0","time":"中","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"12.9","sec":12,"n":9,"title":"发票只按真实交易开，小规模纳税人用足免税额","cost":"0 元；不买发票、不卖发票、不替别人「走账开票」，按真实业务开票报税","human":"小规模纳税人月销售额 10 万、季度 30 万以内免增值税，同期 3% 征收率的减按 1% 收，这是白给的额度。反过来「找人开票抵成本」就是虚开：为别人开、让别人给自己开、介绍别人开都算，起步判 3 年以下并罚 2 万到 20 万，数额巨大能到 10 年以上或者无期。","gain":"小规模纳税人「销售额未达到起征点的，免征增值税」，起征点自 2026 年 1 月 1 日至 2027 年 12 月 31 日为月销售额 10 万元、季度销售额 30 万元、按次（日）销售额 1000 元；同期除销售或出租不动产、转让土地使用权外，适用 3% 征收率的减按 1% 征收；反过来，虚开增值税专用发票或其他可抵扣发票（为他人开、为自己开、让他人为自己开、介绍他人开都算）处 3 年以下有期徒刑或拘役并处 2 万到 20 万元罚金，税额较大处 3 到 10 年，数额巨大处 10 年以上或无期（全国）","grade":"A","src":"全国人大常委会 (2024). 增值税法（2026 年 1 月 1 日施行，第二十三条）. <https://fgk.chinatax.gov.cn/zcfgk/c100009/c5237365/content.html>；财政部、税务总局 (2026). 关于增值税法施行后增值税优惠政策衔接事项的公告（财政部 税务总局公告 2026 年第 10 号，第一、二、六条）. <https://fgk.chinatax.gov.cn/zcfgk/c102416/c5247434/content.html>；全国人大 (1997). 刑法（第二百零五条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>","note":"2026 年 1 月 1 日增值税法施行，原来的小规模纳税人减免公告（2023 年第 19 号、2023 年第 1 号）随之停止执行或废止，金额门槛没变但依据换了，本条已按新文件更新。刑法原文页为 1997 年版，第二百零五条后经修正案调整过刑档，本条只写核实到且未变动的刑档。免的是增值税，所得税另算；「找人开票抵成本」就是虚开，不是节税。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"12.10","sec":12,"n":10,"title":"自称税务局催你交钱报税的都是骗子，办税只走电子税务局和 12366","cost":"0 元；接到「税务抽查」「账户异常」「不报税就罚款」的电话、短信或加好友，先挂断，再用 12366 或主管税务机关的固定电话回拨核实","human":"税务部门不会打电话要你的银行卡密码、支付密码或短信验证码，也不会给你一个指定账号让你把税打过去；真查账上门要出示检查通知书和检查证。接到「不报税就罚款」的电话先挂断，用 12366 或税务局固定电话回拨。冒充国家机关工作人员的，拘留 10 到 15 天起步。已经转了钱立刻打 110 或 96110 止付。","gain":"税务总局的提示原文：「税务部门不会通过微信小程序、电话、短信等方式索要银行卡密码、支付密码、账户余额及与银行卡收付款项相关的短信验证码」，「一些不法分子冒充税务干部以提供『帮办纳税申报』『税收优惠代办』『政策辅导』等为名接触纳税人」，核实渠道是「12366 纳税缴费服务热线或主管税务机关固定电话」；真稽查「必须出示检查通知书和检查证」，「税款只能通过电子税务局或者在办税大厅缴纳，税务部门不会提供指定账号」；涉税专业服务机构「以税务机关和税务人员的名义敲诈纳税人、扣缴义务人的」，按情节罚款；冒充国家机关工作人员招摇撞骗的，处 10 日以上 15 日以下拘留可并处 1000 元以下罚款，构成犯罪同时构成诈骗罪和招摇撞骗罪的「依照处罚较重的规定定罪处罚」（全国）","grade":"A","src":"国家税务总局 (2025). 税务部门提醒广大纳税人——增强防范意识 警惕互联网涉税诈骗. <https://www.chinatax.gov.cn/chinatax/n810219/n810724/c5243181/content.html> ; 国家税务总局扬州市税务局 (2023). 扬州防范涉税诈骗宣传篇. <https://jiangsu.chinatax.gov.cn/art/2023/8/28/art_23038_432322.html> ; 国家税务总局 (2025). 涉税专业服务管理办法（试行）（国家税务总局令第 58 号，第三十二条第七项、第三十三条）. <https://fgk.chinatax.gov.cn/zcfgk/c100011/c5239044/content.html> ; 全国人大常委会 (2025). 治安管理处罚法（2025 年修订，2026 年 1 月 1 日施行，第六十二条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml> ; 最高人民法院、最高人民检察院、公安部 (2016). 关于办理电信网络诈骗等刑事案件适用法律若干问题的意见（法发〔2016〕32 号）. <https://www.spp.gov.cn/zdgz/201612/t20161221_176278.shtml>","note":"这类骗局专挑刚注册的个体户和小公司，话术是「系统显示你没报税，今天不处理就罚款」，然后把你导到他们自己的公众号或小程序，一次收几百元代办本来免费、自己几分钟就能做完的申报。找市场化机构代记账不违法，但它不是政府部门，也不会用税务局的名义催你。已经付钱或转账的，按第 8 节第 2 条立刻打 110 或 96110 要求止付","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"12.11","sec":12,"n":11,"title":"收钱写「定金」不写「订金」，违约金写明数，账期当放贷来审","cost":"0 元；合同里用「定金」二字，金额不超过合同标的额 20%，先收款再发货，给账期前先查对方","human":"写「定金」两个字才有双倍规则：你违约定金要不回来，对方违约要双倍退你，超过合同金额 20% 的部分不算数。民法典只给「定金」写了双倍规则，写「订金」没有对应条文。违约金写明数额，高得离谱或者低得离谱法院都能调；给账期等于把自己的钱无息借给对方，对方倒了就是坏账。","gain":"定金合同自实际交付时成立；付定金一方违约无权要回，收定金一方违约要双倍返还；超过主合同标的额 20% 的部分没有定金效力；约定的违约金过分高于或低于损失，法院可以按当事人请求调整；既约定违约金又约定定金的，违约时只能二选一（全国，2021 年起）","grade":"A","src":"全国人大 (2020). 民法典（第五百八十五、五百八十六、五百八十七、五百八十八条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>","note":"「订金」在民法典里没有定金规则，通常只当预付款处理，这一点是实务通说，本节未核实判例。账期是把自己的钱无息借给对方，对方倒了就是坏账，给账期前看对方在国家企业信用信息公示系统的记录和涉诉情况。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"12.12","sec":12,"n":12,"title":"用人第一个月内签书面合同，30 日内办社保登记","cost":"社保单位缴费部分是长期支出（各地费率不同）；签合同本身 0 元，用当地人社部门的合同范本","human":"用工满一个月还没签书面合同，从第二个月起每月要付双倍工资，一直算到满一年。社保要在用工 30 天内登记，不办罚应缴社保费的 1 到 3 倍、经手人罚 500 到 3000 元；欠缴的按日加收万分之五滞纳金。法律上没有「员工自愿放弃社保」这一项。","gain":"用工满一个月不满一年没签书面合同的，要每月付双倍工资；应自用工之日起 30 日内为职工办社保登记，不办的责令改正，逾期处应缴社保费 1 到 3 倍罚款，直接责任人罚 500 到 3000 元；未按时足额缴社保的，从欠缴之日起按日加收万分之五滞纳金，逾期不缴再罚欠缴额 1 到 3 倍；单位应自行申报、按时足额缴纳，只有不可抗力等法定事由才能缓缴减免，没有「员工自愿放弃」这一项（全国）","grade":"A","src":"全国人大常委会 (2007). 劳动合同法（第十、八十二条）. <https://www.gov.cn/gongbao/content/2007/content_711013.htm>；全国人大常委会 (2010). 社会保险法（2018 年修正，第五十八、六十、八十四、八十六条）. <https://www.mohrss.gov.cn/xxgk2020/fdzdgknr/zcfg/fl/202011/t20201102_394629.html>","note":"双倍工资从第二个月算到满一年，越拖越贵。没签合同、没缴社保的员工一旦工伤或离职仲裁，补缴加罚款加赔偿往往比省下的那点钱多得多。","money":"多","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"12.13","sec":12,"n":13,"title":"工资按合同和法律给，加薪、借款、奖金都走书面","cost":"0 元；合同里把劳动报酬写清，加薪、奖金、垫付、借款一律签字留纸，不口头承诺，不从自己口袋掏钱替公司发工资","human":"工资按合同和法律按时足额发，欠了员工可以直接找法院开支付令。加薪、奖金、垫付口头说说没凭据，真吵起来拿不出证据的一方吃亏。私人借钱给员工要写书面借条，写清数额、利息、期限和还法；私人的钱和公司账混着走，公司亏了坏账落在你自己头上。","gain":"劳动合同必备条款包括劳动报酬和社会保险；单位要按合同约定和国家规定及时足额付工资，拖欠的员工可以直接向法院申请支付令。老板私人借钱给员工是借款合同，除自然人之间另有约定外应当采用书面形式，写明数额、利率、期限、还款方式；口头许的奖金没有书面凭据，争议时拿不出证据的一方吃亏（全国）","grade":"C","src":"全国人大常委会 (2007). 劳动合同法（第十七、三十条）. <https://www.gov.cn/gongbao/content/2007/content_711013.htm>；全国人大 (2020). 民法典（第四百六十九、六百六十八条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>","note":"这是读者说的「管理公司不要过度同情」的中性版本：不是不帮人，而是帮人走制度。制度之外的恩惠一旦成了惯例，停掉就是纠纷；私人借款和公司账混在一起，公司亏了就是你自己的坏账。法条部分已核实，建议本身是经验，故 C 级。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"12.14","sec":12,"n":14,"title":"先卖再造：用预售和小订单验证有人买，再投钱生产","cost":"几十到几百元做样品或页面，找几十个真实客户预付或下小单；比直接开工慢几周","human":"跟踪 116 家意大利初创企业约一年发现：受训按「先提假设、再拿市场反馈严格检验」做决定的创业者业绩更好，也更愿意及时换方向，而且并没有更早放弃。落到操作上就一句：没人肯预付、没人肯下小单，就别信「做出来自然有人买」。","gain":"一项对 116 家意大利初创企业跟踪约一年的随机对照试验：受训按「先提假设、再用市场反馈严格检验」做决策的创业者，业绩更好、更可能及时转向别的方案，早期放弃率并不更高；作者的解释是这种做法减少了在假阳性项目上继续砸钱的概率（意大利，2020 年发表）","grade":"B","src":"Camuffo A, Cordova A, Gambardella A, Spina C (2020). A Scientific Approach to Entrepreneurial Decision Making: Evidence from a Randomized Control Trial. Management Science 66(2):564-586. <https://doi.org/10.1287/mnsc.2018.3249>","note":"单一研究、样本小、发生在意大利，故 B 级；题录和摘要经 Crossref 与 Semantic Scholar 核对，全文效应量本节未核实。落到操作上：没人肯预付、没人肯下小单，就别相信「做出来就有人买」。","money":"少","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"12.15","sec":12,"n":15,"title":"样品做出来先过一遍量产清单，再谈开工","cost":"几百元做小批量试产，几个小时把下面几项算清：良率（100 件里能卖几件）、供应商起订量和账期、库存占多少钱、包装和物流、认证和许可、商标","human":"一件样品和一千件的差别是钱压在哪：良率决定真实成本，起订量和账期决定要先垫多少，库存决定钱什么时候回来。另外产品在强制性认证目录里的，没认证、没标注认证标志就不能出厂和销售，卖了要按规定处罚。","gain":"一件样品和一千件的差别是钱压在哪：良率决定真实成本，起订量和账期决定要先垫多少钱，库存决定钱什么时候回来；列入强制性产品认证目录的产品必须经认证并标注认证标志后才能出厂、销售，未经认证擅自出厂销售的按认证认可条例处罚；餐饮和食品销售要食品经营许可（全国）","grade":"C","src":"质检总局 (2009). 强制性产品认证管理规定（质检总局令第 117 号，第二、四十九条）. <http://www.gov.cn/gongbao/content/2010/content_1533513.htm>；市场监管总局 (2023). 食品经营许可和备案管理办法（市场监管总局令第 78 号，第四条）. <https://www.gov.cn/gongbao/2023/issue_10606/202307/content_6894763.html>","note":"清单本身是经验方法，法条部分已核实原文。商标在投产前先到国家知识产权局商标查询系统查有没有近似注册再申请；用别人的商标和图案的红线见第 16、17 条（进货留票据、图案要自己做或买授权）。强制认证目录以市场监管总局最新公布为准。","money":"少","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"12.16","sec":12,"n":16,"title":"进货一批留一批票据和上家信息，进货价明显低于市场价的不进：员工进的假货，老板是被判的那个","cost":"0 元；每批货留采购合同、发票、付款记录、上家营业执照和授权文件；定一条内部规矩，谁进的货谁签字，价格明显低于市场价的一律不进","human":"卖假货，违法所得 3 万或者销售金额 5 万就到刑事门槛，判 3 年以下并处罚金，达到十倍标准的判 3 到 10 年，货压在仓库没卖出去也算。「我不知道是假的」不由你说了算：进货价明显低于市场价又说不出正当理由、授权文件是伪造涂改的、被查后转移销毁货和账本，都会被推定为知情，除非你拿得出确实不知道的证据。留住采购合同、发票、付款记录和上家信息，才有「合法取得、能说出上家」这条免赔的路。","gain":"销售明知是假冒注册商标的商品，违法所得 3 万元以上，或者销售金额 5 万元以上，就到刑事门槛，判 3 年以下并处或者单处罚金；达到该标准十倍的判 3 到 10 年并处罚金；货还没卖出去也算，货值达到销售金额标准三倍以上同样入罪。「明知」不用你承认：两高 2025 年司法解释列了五种可以直接认定为明知的情形（有证据证明确实不知道的除外）——知道商品上的注册商标被涂改、调换或者覆盖；伪造、涂改商标注册人授权文件或者知道该文件被伪造、涂改；因销售假冒商品受过刑事或行政处罚又销售同一种的；无正当理由以明显低于市场价格进货或者销售的；被行政执法机关、司法机关发现后转移、销毁侵权商品、会计凭证等证据或者提供虚假证明的。公司犯这一条的，「对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员」按同一条处罚，所以货是员工进的，挨罚挨判的是拍板的人。反过来商标法留了一条出路：销售不知道是侵犯注册商标专用权的商品，「能证明该商品是自己合法取得并说明提供者的，不承担赔偿责任」——这条抗辩的全部内容就是票据和上家信息，没留就用不上（全国，司法解释 2025 年 4 月 26 日起施行）","grade":"A","src":"全国人大常委会 (2020). 刑法修正案（十一）（第十七、二十四项，即刑法第二百一十四、二百二十条）. <https://www.spp.gov.cn/zdgz/202012/t20201227_503682.shtml>；最高人民法院、最高人民检察院 (2025). 关于办理侵犯知识产权刑事案件适用法律若干问题的解释（法释〔2025〕5 号，2025 年 4 月 26 日起施行）. <https://www.spp.gov.cn/xwfbh/wsfbt/202504/t20250424_693977.shtml>；全国人大常委会 (2019). 商标法（2019 年修正，第五十七、六十四条；2026 年 6 月 26 日修订后为第七十二、七十八条，自 2027 年 1 月 1 日起施行）. <https://www.cnipa.gov.cn/art/2019/7/30/art_95_28179.html>、<https://www.cnipa.gov.cn/art/2026/6/26/art_95_206942.html>","note":"化妆品、酒水、母婴、数码、服装是这类案子的高发品类，共同点是同款货有巨大的价差空间，「渠道货」「尾单」「海外免税」这些说法都不能替代票据。行政层面另有一道：认定侵权成立的没收侵权商品和工具，违法经营额 5 万元以上可以并处 5 倍以下罚款。已经进了发现不对，立刻停售封存、联系品牌方或市场监管部门，别继续卖，更别把货和账销毁——销毁证据恰好是推定明知的第五种情形。用别人的图案见下一条。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"12.17","sec":12,"n":17,"title":"商品、包装、吊牌和宣传图上的图案要么自己做要么买授权，改个颜色、加个图标不算「改过了」","cost":"正版图库授权从几十元一张起，找人原创设计几百到几千元；每张用在商品上的图留一份授权凭证和购买记录","human":"在别人的图上改个颜色、换个底色、加个自己的图标，仍然是没经许可用别人的作品。为赚钱复制别人的美术作品，违法所得 3 万、非法经营额 5 万或者印够 500 张，就是侵犯著作权罪，判 3 年以下，十倍标准 3 到 10 年；只是卖别人印的侵权货，违法所得 5 万或销售额 10 万按销售侵权复制品罪判 5 年以下。商标那边「近似到容易混淆」本身就写在侵权情形里。","gain":"著作权法把「未经著作权人许可，以改编、翻译、注释等方式使用作品」和直接复制并列为侵权行为，所以在原图上改颜色、换底色、加个自己的图标，仍然是未经许可使用别人的作品；刑事门槛在这里：以营利为目的，未经著作权人许可复制发行美术作品，违法所得 3 万元以上，或者非法经营数额 5 万元以上，或者复制件数量合计 500 份（张）以上，就构成侵犯著作权罪，判 3 年以下并处或者单处罚金，达到十倍标准的判 3 到 10 年；只是卖别人印的侵权货，违法所得 5 万元以上或者销售金额 10 万元以上，按销售侵权复制品罪判 5 年以下。商标那一侧同理：在同一种商品上使用与注册商标近似的商标，或者在类似商品上使用相同或者近似的商标，「容易导致混淆的」本身就在侵权范围内——「近似」就是法条明写的侵权情形，改一改改不出安全区（全国，司法解释 2025 年 4 月 26 日起施行）","grade":"A","src":"全国人大常委会 (2020). 著作权法（2020 年修正，第五十二条第六项、第五十三条）. <http://www.npc.gov.cn/npc/c2/c30834/202011/t20201119_308796.html>；全国人大常委会 (2020). 刑法修正案（十一）（第二十、二十一项，即刑法第二百一十七、二百一十八条）. <https://www.spp.gov.cn/zdgz/202012/t20201227_503682.shtml>；最高人民法院、最高人民检察院 (2025). 关于办理侵犯知识产权刑事案件适用法律若干问题的解释（法释〔2025〕5 号）. <https://www.spp.gov.cn/xwfbh/wsfbt/202504/t20250424_693977.shtml>；全国人大常委会 (2019). 商标法（2019 年修正，第五十七条第二项；2026 年修订后为第七十二条第二项）. <https://www.cnipa.gov.cn/art/2019/7/30/art_95_28179.html>","note":"常踩的三处：网上搜来的卡通形象和明星图印在衣服、杯子、手机壳上；字体——商用字体多数要单独授权，免费预览不等于免费商用；给客户做的设计稿里夹了没授权的素材，责任仍在卖货的人身上。要省事就用有商用授权的图库并保存授权页，或者让设计方在合同里写明素材来源与授权范围、出事由其负责。刑事之外还有民事赔偿和行政罚款，损害公共利益的可以没收违法所得并按违法经营额 1 到 5 倍罚款。投产前查商标见第 15 条（样品先过一遍量产清单），自己的图被别人用同样按这套规则维权。","money":"少","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"12.18","sec":12,"n":18,"title":"在岗位上按规程办事，规程之外的好意先想清楚责任归谁","cost":"0 元；职务行为按制度、按医嘱、按流程走，不在自己权限之外替人做决定；想帮忙先问一句「出了事谁负责」","human":"岗位上的事按规程、按医嘱走，规程写明了哪些事必须报给上级、哪些能自己先处置。反过来法律也没让人见死不救：自愿实施紧急救助造成受助人损害的，救助人不承担民事责任。","gain":"以护士为例，法规写明的职务边界是：发现病情危急立即通知医师，紧急情况下为抢救垂危患者先行实施必要的紧急救护；发现医嘱违法违规或违反诊疗技术规范的要向医师提出、必要时向科室负责人报告。另一面也要写清：民法典规定因自愿实施紧急救助行为造成受助人损害的，救助人不承担民事责任，法律保护的是善意救助，不是「帮人就要赔」（全国）","grade":"B","src":"国务院 (2008). 护士条例（国务院令第 517 号，第十七条）. <http://www.gov.cn/zhengce/zhengceku/2008-03/28/content_6169.htm>；全国人大 (2020). 民法典（第一百八十四条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>","note":"这是读者说的「不要多管闲事」的中性版本：岗位内按规程，紧急救人受法律保护，其余的事先分清是谁的权限和谁的责任，别用私人好意替代制度决定。护士条例引 2008 年原文，TODO（待核实：2020 年修订后第十七条是否改动）；医师法关于按诊疗规范执业的条款本次未能打开官方原文，未引用。","money":"0","time":"少","will":"些","level":"中","lens":"自由","dispute":false,"todo":true,"ratio":"一般"},{"id":"12.19","sec":12,"n":19,"title":"亏了就按程序退场：能简易注销就注销，资不抵债走破产，别放着不管","cost":"简易注销在国家企业信用信息公示系统公示 20 日，自己就能办；有债务的要先清算，破产要向法院申请，耗时数月","human":"没债或者债已还清、不欠薪不欠税不欠社保、全体投资人书面承诺的，公示 20 天没人提异议就能简易注销，个体户不用公示、10 天无异议直接注销；资不抵债又还不上到期债务的，向法院申请破产。放着不管的代价：不报年报进经营异常名录，满 3 年进严重违法名单，法定代表人 3 年内不能再当别家企业的法定代表人，而且进了异常名录连简易注销都走不成。","gain":"没有债权债务或已清偿完毕、没有欠薪欠社保欠税、全体投资人书面承诺的，公示 20 日无异议后可以简易注销，个体户不用公示，有关部门 10 日内无异议直接注销；公司不能清偿到期债务且资不抵债的，可以向法院申请重整、和解或破产清算，已解散未清算且资不抵债的，负有清算责任的人应当申请破产清算。放着不管：不按期公示年报列入经营异常名录，满 3 年不履行公示义务列入严重违法企业名单，法定代表人、负责人 3 年内不得担任其他企业的法定代表人、负责人；列入经营异常名录的不能走简易注销（全国）","grade":"A","src":"国务院 (2021). 市场主体登记管理条例（国务院令第 746 号，第三十一、三十二、三十三条）. <https://www.gov.cn/zhengce/zhengceku/2021-08/24/content_5632964.htm>；市场监管总局等六部门 (2025). 企业注销指引（2025 年修订）（2025 年第 52 号公告）. <https://www.gov.cn/zhengce/zhengceku/202512/content_7053238.htm>；全国人大常委会 (2006). 企业破产法（第二、七条）. <http://www.gov.cn/gongbao/content/2006/content_413952.htm>；国务院 (2014). 企业信息公示暂行条例（国务院令第 654 号，第十七条）. <https://www.gov.cn/zhengce/zhengceku/2014-08/23/content_9038.htm>","note":"企业信息公示暂行条例引 2014 年原文，2024 年国务院令第 777 号只把该条例里的「工商行政管理部门」改为「市场监督管理部门」且未列第十七条，TODO（待核实：是否另有 2024 年单独修订）。个人（含个体户）破产制度目前只有个别地区试点，本节未核实原文，不写。","money":"0","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":true,"ratio":"高"}]},{"n":13,"title":"紧急情况：先做什么","intro":"本节只回答一件事：突发状况下先做什么、再做什么、什么不要做。急救与荒野条目的口径是特定死因和存活率，威胁与骗局条目的口径是金钱和人身自由，两类数字不互相换算；排序按「最常见 × 做对做错的生死差别」从高到低。按全书的受益人口径，急救条目的主线是你自己和配偶、直系亲属——心脏骤停有 79.2% 发生在家里，你最可能救的就是家里人；对朋友同事次之；对陌生人不是零收益，但档次最低、还带被讹和被卷进案子的一面，所以这类条目把自保动作和免责条款写在前面。","entries":[{"id":"13.1","sec":13,"n":1,"title":"有人倒地没呼吸，立刻用力按压胸口，让旁人打 120 并找 AED","cost":"0 元；红十字会或医院的心肺复苏课半天到一天，学一次够用多年；没学过也能做：双手叠放在两乳头连线中点，每秒约 2 次用力下压，不要停","human":"你最可能按的是自家人——38,227 例里 79.2% 的心脏骤停发生在家里。有人按压，出院时活下来的比例从 3.9% 升到 16.1%，差四倍多。倒地叫不应、没呼吸就直接按：两乳头连线中点，双手叠起来用力压，每秒 2 次，不停。让第二个人打 120 和拿 AED，你的手别停。","gain":"79 项研究 142,740 人的荟萃分析：院外心脏骤停总体出院存活率 7.6%，有旁观者做心肺复苏的存活率从 3.9% 升到 16.1%，而 53% 的骤停有人目击、只有 32% 得到旁观者按压；中国 BASIC-OHCA 登记 38,227 例急救接诊病例，其中 30,282 例（79.2%）的心脏骤停发生在家中，旁观者按压率 20.3%，出院存活率 1.2%。先按压，再让第二个人打电话和拿 AED，机器开机后照语音做","grade":"A","src":"Sasson C 等 (2010). Predictors of survival from out-of-hospital cardiac arrest: a systematic review and meta-analysis. Circulation: Cardiovascular Quality and Outcomes. <https://doi.org/10.1161/CIRCOUTCOMES.109.889576> ; Zheng J 等 (2023). Incidence, process of care, and outcomes of out-of-hospital cardiac arrest in China: a prospective study of the BASIC-OHCA registry. The Lancet Public Health. <https://doi.org/10.1016/S2468-2667(23)00173-1> ; 全国人大 (2020). 民法典（第一百八十四条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>","note":"不要先掐人中、先找家属、先拍视频；不要因为怕按断肋骨而不敢用力。民法典第一百八十四条：自愿实施紧急救助造成受助人损害的，救助人不承担民事责任。","money":"0","time":"中","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.2","sec":13,"n":2,"title":"老人摔倒、有人倒地，先蹲下喊他、打 120，别急着把人扶起来；陌生人这档走开也合法，停下来就别上手搬","cost":"0 元；蹲下去问一句、打个电话，几分钟；对陌生人还要算上打 120 会留下你的号码、可能被回电或者问一次话；真被家属盯上，应诉是几个月起步的事，而且律师费不在「败诉方负担」的范围里","human":"这条的主线是自家老人和身边熟人。先看有没有呼吸，没有就直接按第 1 条压胸。有呼吸也别抱起来：跌倒是 65 岁以上老人受伤死亡的头号原因，而且人可能是先中风、先晕厥才摔的。蹲下叫他，问记不记得自己怎么倒的——想不起来就可能是晕厥或者脑血管意外；再问有没有剧烈头痛、嘴歪、说话不清、手脚没劲，有就更不能扶，硬扶可能加重脑出血或脑缺血；腰背疼、大小便失禁、看着像骨折的，没有专业知识一律不搬。这几种都是原地打 120。他自己想起身，就扶着慢慢起来坐下，看一会儿确认没事再走。怕被讹分两件事：救的过程中弄伤了他，民法典写明救助人不承担民事责任，最高法的典型案例里救人把肋骨压断了、被索赔九千多，法院判不用赔；反过来说是你撞的，那是谁主张谁举证，拿不出证据的一方自己承担不利后果。","gain":"卫生部《老年人跌倒干预技术指南》：「跌倒是我国 65 岁以上老年人伤害死亡的首位原因」，「发现老年人跌倒，不要急于扶起，要分情况进行处理」。意识不清的立即拨打急救电话，有呕吐将头偏向一侧并清理口鼻、呼吸心跳停止立即胸外按压，「如需搬动，应保证平稳，尽量平卧」；意识清楚的先问对跌倒过程有无记忆，「如不能记起，可能为晕厥或脑血管意外」，有剧烈头痛或口角歪斜、言语不利、手脚无力的，「立即扶起老年人可能加重脑出血或脑缺血，使病情加重」，有骨折迹象或腰背疼痛、大小便失禁的，「如无相关专业知识，不要随便搬动」，以上均应立即拨打急救电话；老人试图自行站起可协助缓慢起立，「坐、卧休息并观察，确认无碍后方可离开」。《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第九十条：「当事人对自己提出的诉讼请求所依据的事实……应当提供证据加以证明」，「在作出判决前，当事人未能提供证据或者证据不足以证明其事实主张的，由负有举证证明责任的当事人承担不利的后果」。民法典第一千一百九十八条：「宾馆、商场、银行、车站、机场、体育场馆、娱乐场所等经营场所、公共场所的经营者、管理者或者群众性活动的组织者，未尽到安全保障义务，造成他人损害的，应当承担侵权责任。」民法典第一百八十四条：「因自愿实施紧急救助行为造成受助人损害的，救助人不承担民事责任」；最高人民法院典型案例中，药店经营者对心脏骤停者做心肺复苏致其肋骨骨折、住院 18 天，受助人索赔 9 千余元，法院判决救助人不承担民事责任","grade":"B","src":"卫生部 (2011). 老年人跌倒干预技术指南（「老年人跌倒后的处理」）. 全文 PDF 见广东省疾病预防控制中心 <http://cdcp.gd.gov.cn/gcdcdfiles/editor/uploadfile/20111027094832117.pdf>，现场处理部分全文见贵南县人民政府转载 <https://www.guinan.gov.cn/lnb/zc1__zwgk/zc/aztfl/qt/content_27609778>；全国人大 (2020). 民法典（第一百八十三、一百八十四条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；最高人民法院 (2023). 人民法院抓实公正与效率践行社会主义核心价值观典型案例（案例十三，齐某某诉孙某某健康权纠纷案，辽宁省康平县人民法院）. <https://www.court.gov.cn/zixun/xiangqing/408162.html>；最高人民法院 (2022 年第二次修正，2022 年 4 月 10 日施行). 关于适用《中华人民共和国民事诉讼法》的解释（第九十条）. <https://www.court.gov.cn/zixun/xiangqing/353651.html>；民法典第一千一百九十八条同上最高检转载全文；全国人大常委会 (2023 年修正，2024 年 1 月 1 日施行). 民事诉讼法（第一百五十二、一百六十四条）. 上海市发展和改革委员会转载全文 <https://fgw.sh.gov.cn/ys-syjf-zc-2.4.1-h5/20240408/073febdb2b04464390546232d4089f51.html>；国务院 (2006). 诉讼费用交纳办法（国务院令第 481 号，第六、二十九条）. <https://www.gov.cn/ziliao/flfg/2006-12/29/content_483682.htm>；全国人大常委会 (2025). 治安管理处罚法（2025 年修订，2026 年 1 月 1 日起施行，第二十六条第一项、第五十条第五项）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>","note":"B 级原因是指南给的是处置口径，没有「照做能少死多少人」的效应量。第一百八十四条免的是救助过程中造成的损害，前提是自愿、紧急；它不替你兜「自作主张把人塞进私家车送医」这类操作，等 120 更稳妥。打完 120 别挂电话，按调度员说的做。按受益人口径，这套判断首先是给自家老人和熟人用的；换成路上不认识的人，走开不违法也最省事——你没有救助义务，停下来要付的是时间、留号码、被家属找上、被列为被告、闹到单位、被拍被传上网这一串账，逐层算见 [docs/遇到陌生人出事该不该停.md](../docs/遇到陌生人出事该不该停.md)。真决定停下，唯一没有第二种答案的动作是**别上手搬**，理由是医学的不是法律的：硬扶可能加重脑出血或者脊柱损伤。一个例外要记住：你若是这个场所的经营者、管理者或者活动组织者，走开就不再免费，民法典第一千一百九十八条给了你安全保障义务。防跌倒本身见第 1 节第 13 条（练平衡和腿部力量），老人磕过头之后的迟发症状见本节第 9 条，救人受伤之后的钱见本节第 40 条，被网暴怎么留证报警见第 8 节第 14 条。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.3","sec":13,"n":3,"title":"突然嘴歪、一侧胳膊没劲、说话说不清，立刻打 120，不要等、不要自己开车去","cost":"0 元；记住三个动作：让他笑一下、双手平举、说一句完整的话","human":"3 小时内溶栓，恢复到生活基本能自理的概率大约是不溶栓的 1.75 倍；拖到 3 到 4.5 小时降到 1.26 倍；超过 4.5 小时就看不出差别了。嘴歪、一侧胳膊抬不起、说话说不清，立刻打 120，记下症状开始的准确时间，别喂水喂药，别自己开车。","gain":"16 项静脉溶栓随机试验、6756 名患者的个体数据荟萃分析：发病 3 小时内用阿替普酶溶栓，获得良好结局（改良 Rankin 评分 0–1）的比值比 1.75（95% CI 1.35–2.27）；3 到 4.5 小时 1.26（1.05–1.51）；超过 4.5 小时 1.15（0.95–1.40），不再显著","grade":"A","src":"Emberson J, Lees KR, Lyden P, et al. (2014). Effect of treatment delay, age, and stroke severity on the effects of intravenous thrombolysis with alteplase for acute ischaemic stroke: a meta-analysis of individual patient data from randomised trials. Lancet, 384(9958), 1929-1935. <https://doi.org/10.1016/S0140-6736(14)60584-5>","note":"越早越有效，超过 4.5 小时窗口就基本没有溶栓获益了。打 120 而不是自己开车，是因为救护车会直接送到有卒中中心的医院并提前通知。记下症状开始的准确时间，医生要用它决定能不能溶栓。别喂水喂药，别等「休息一下看看」","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"13.4","sec":13,"n":4,"title":"突然天旋地转站不稳、看东西成双、一只眼发黑，或者手指点不到自己鼻尖，也按卒中打 120","cost":"0 元；在上一条三个动作之外再加两个：让他站直闭眼看晃不晃，问他看东西有没有重影或缺一块；自己怀疑就伸手指点鼻尖，闭上眼再点一次","human":"736 例卒中里有 14.1% 一开始既不歪嘴也不瘫手，只看那三条就漏了；把「站不稳、看东西重影或缺一块」也算进去，漏掉的降到 4.4%。突然天旋地转站不住、看东西成双、手指点不到自己鼻尖，一样打 120，一样记时间。","gain":"美国肯塔基大学卒中中心 2014 年 736 例急性缺血性卒中的回顾：14.1% 的病人发病时完全没有 FAST 那三个症状（脸歪、胳膊无力、说话不清）；把「走路不稳、腿没劲、视觉症状」也算进筛查，漏掉的比例从 14.1% 降到 4.4%","grade":"B","src":"Aroor S, Singh R, Goldstein LB (2017). BE-FAST (Balance, Eyes, Face, Arm, Speech, Time): Reducing the Proportion of Strokes Missed Using the FAST Mnemonic. Stroke, 48(2), 479-481. <https://doi.org/10.1161/STROKEAHA.116.015169>","note":"小脑和脑干（后循环）的梗死常常不歪嘴、不瘫手，只表现为眩晕、走路偏斜、复视、吞咽呛咳，最容易被当成颈椎病、低血糖、耳石症耽误。指鼻不准、闭眼站不住是小脑受累的体征，但没有哪一个动作能反过来排除卒中：突然出现、持续不缓解就打 120，并记下发作的准确时间。该研究是单中心回顾性分析，作者自己写明需要前瞻验证","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"13.5","sec":13,"n":5,"title":"一只眼睛突然像拉下窗帘一样黑掉，哪怕几分钟就自己好了，也当天按卒中去急诊","cost":"0 元；占掉半天到一天做急诊评估和血管检查","human":"一只眼突然像拉下窗帘一样黑掉，是眼底血管堵了，堵得越久能救回的视网膜越少；它还是脑缺血的一种，接下来几天正是中风高发窗口。同类病人改成当天评估、当天开始治，90 天内再中风的比例从 10.3% 降到 2.1%。当天去有卒中中心的急诊，不等第二天挂眼科。","gain":"美国心脏协会 2021 年视网膜中央动脉阻塞科学声明：「急性视网膜中央动脉阻塞是急症」，救治体系应当把它按急诊来识别和分诊，缺血时间越长、还能救回来的视网膜组织越少；牛津 EXPRESS 研究：短暂性脑缺血发作和小卒中的病人改为当天评估、当天开始治疗之后，90 天内再发卒中的比例从 10.3%（32/310）降到 2.1%（6/281）","grade":"B","src":"Mac Grory B, Schrag M, Biousse V, et al. (2021). Management of Central Retinal Artery Occlusion: A Scientific Statement From the American Heart Association. Stroke, 52(6), e282-e294. <https://doi.org/10.1161/STR.0000000000000366> ; Rothwell PM, Giles MF, Chandratheva A, et al. (2007). Effect of urgent treatment of transient ischaemic attack and minor stroke on early recurrent stroke (EXPRESS study): a prospective population-based sequential comparison. Lancet, 370(9596), 1432-1442. <https://doi.org/10.1016/S0140-6736(07)61448-2>","note":"定 B 是因为 EXPRESS 不是随机试验，是同一人群前后两期的序贯比较，效应量里有时间趋势的成分。眼前一黑几分钟又自己恢复，最容易被当成「累的」「低血糖」放过去；它是短暂性脑缺血发作的一种，接下来几天正是卒中高发窗口。不疼、不红、不流泪的单眼视力丧失尤其要当回事，别等第二天挂眼科门诊，直接去有卒中中心的医院急诊。","money":"0","time":"中","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.6","sec":13,"n":6,"title":"胸口压着疼、闷、发紧超过 15 分钟不缓解，打 120，不要自己扛也不要自己开车","cost":"0 元","human":"胸口压着疼、闷、发紧超过 15 分钟不缓解，打 120。到院后 55 分钟内做上球囊扩张的，30 天内死亡 2.8%，超过 55 分钟的 9.7%，耽误的每一段都在多坏死一块心肌。别自己开车，路上失去意识就是第二场事故。","gain":"以色列全国急性冠脉综合征调查中 ST 段抬高心肌梗死患者的分析：入院到球囊扩张时间 ≤55 分钟者 30 天死亡 5/178（2.8%），>55 分钟者 15/155（9.7%）","grade":"B","src":"Karkabi B, Meir G, Zafrir B, et al. (2021). Door-to-balloon time and mortality in patients with ST-elevation myocardial infarction. European Heart Journal - Quality of Care and Clinical Outcomes. <https://doi.org/10.1093/ehjqcco/qcaa037>","note":"该研究比的是到院后的院内延误，不是发病到到院的时间，但方向一致：每一段耽误都算在心肌坏死上。疼痛可能表现为上腹痛、后背痛、下巴痛、左臂发麻，糖尿病人和老年人可能不痛只喘。不要自己开车，路上失去意识就是二次事故","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"13.7","sec":13,"n":7,"title":"突然像被撕开一样的剧痛，从胸口往后背、往腰一路挪，打 120 并说清「疼在移动」","cost":"0 元","human":"撕裂样的剧痛从胸口往后背、往腰一路挪，打 120 时直接说「像撕开一样、疼在往下走」。这病不手术、光用药的死亡率 58%，而且处理和心梗正相反——医生想到它才会去做增强 CT，而不是给你抗凝溶栓。两条胳膊血压差很多、一侧摸不到脉，也一起说出来。","gain":"国际急性主动脉夹层登记（IRAD）12 家中心 464 例：突发的剧烈锐痛是最常见的首发主诉；总住院死亡率 27.4%，A 型夹层没做手术、只用药物治疗的死亡率 58%","grade":"B","src":"Hagan PG, Nienaber CA, Isselbacher EM, et al. (2000). The International Registry of Acute Aortic Dissection (IRAD): new insights into an old disease. JAMA, 283(7), 897-903. <https://doi.org/10.1001/jama.283.7.897>","note":"夹层和心梗的处理正好相反——心梗要抗凝、溶栓，夹层用上去等于给撕口放血，所以到医院要主动说「撕裂样、疼在往下走」，让医生想到查增强 CT。两条胳膊血压差很多、一侧脉搏摸不到，是提示。高血压控制不好、马凡综合征、有主动脉瘤或夹层家族史的人风险高。同样不要自己开车，不要忍到第二天","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"13.8","sec":13,"n":8,"title":"突然一记「这辈子最疼的头痛」，一小时内就到最疼，立刻去急诊做头颅 CT","cost":"0 元；急诊头颅 CT 几百元","human":"关键不是多疼，是多快到最疼：一小时内到顶的剧烈头痛，2131 人里有 6.2% 是蛛网膜下腔出血。40 岁以上、脖子痛或发硬、有人看到你晕过去、活动中起病、瞬间炸开、脖子前屈受限，中任何一条就去急诊做头颅 CT。查的人绝大多数没事，漏一次再出血就是死亡。别吃片止痛药接着睡。","gain":"加拿大 10 家急诊 2131 例「一小时内达到最痛的剧烈头痛」前瞻队列：132 例（6.2%）是蛛网膜下腔出血。渥太华 SAH 规则（40 岁及以上、颈痛或颈部僵硬、有人看到晕过去、活动中起病、霹雳样起病、查体颈部前屈受限，六条中任一条阳性就要查）识别出血的敏感性 100%（95% CI 97.2%–100.0%），特异性 15.3%","grade":"A","src":"Perry JJ, Stiell IG, Sivilotti MLA, et al. (2013). Clinical decision rules to rule out subarachnoid hemorrhage for acute headache. JAMA, 310(12), 1248-1255. <https://doi.org/10.1001/jama.2013.278018>","note":"关键不是「有多疼」而是「多快到最疼」：几秒到一分钟内炸开的头痛才是危险信号，慢慢加重的偏头痛不是。伴呕吐、脖子发硬、怕光、短暂晕厥更要当回事。特异性只有 15.3%，意味着按这条去查的人绝大多数查完没事，但漏掉一次再出血就是死亡，值得查。不要吃片止痛药压下去接着睡","money":"少","time":"中","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.9","sec":13,"n":9,"title":"老人磕过头之后两三周到几个月变得走路不稳、迟钝、嗜睡或者一侧没劲，去做头颅 CT","cost":"头颅 CT 两三百元","human":"老人磕头之后，血通常到第三周才积起来，撞的当时可以完全没事，人自己都想不起磕过。这病术后复发率能到 33%、病死率能到 32%，最容易被当成老年痴呆或者上次中风的后遗症耽误。发现老人突然糊涂、走路发飘、总想睡、一只手没劲，先倒回去问这两三个月摔没摔过头，再去做 CT。","gain":"中华医学会神经外科学分会等《慢性硬膜下血肿药物治疗中国专家共识》：慢性硬膜下血肿是蛛网膜与硬脑膜之间积血形成的慢性占位，「通常在颅脑外伤后第三周形成」，多见于老年人，术后复发率可达 33%、病死率可达 32%，90 岁以上总体预后良好率 24%；系统综述：全球发病率 3.39 到 39.1/10 万/年，随年龄升高，80 岁以上可达三倍，最常见病因是外伤和跌倒，其次是长期酗酒、抗凝和暴力伤害；老年医学综述：临床表现「典型包括意识模糊、认知下降、步态障碍或嗜睡，可能与其他老年综合征相似」","grade":"B","src":"Zhang J 等 (2021). Expert consensus on drug treatment of chronic subdural hematoma. Chinese Neurosurgical Journal, 7(1), 47. <https://doi.org/10.1186/s41016-021-00263-z> ; Dziho A 等 (2025). Global prevalence and incidence of chronic subdural hematoma: A systematic review. Brain and Spine, 5, 105893. <https://doi.org/10.1016/j.bas.2025.105893> ; Mathon B, Shotar E (2026). Diagnostic and therapeutic management of chronic subdural hematoma in elderly patients. Gériatrie et Psychologie Neuropsychiatrie du Vieillissement, 24(1), 30-41. <https://doi.org/10.1684/pnv.2026.1274>","note":"撞的时候可以完全没事，老人自己甚至想不起磕过。所以家里发现「最近突然糊涂了、走路发飘、总想睡、一只手没劲」，先倒回去问这两三个月有没有摔过、撞过头，再去做 CT，别直接归到「老年痴呆」或者「上次中风的后遗症」上——那是唯一会耽误的分岔。吃阿司匹林、氯吡格雷、华法林或新型口服抗凝药的老人风险更高，长期大量喝酒也是。防跌倒见第 1 节第 13 条（练平衡和腿部力量）。","money":"少","time":"中","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.10","sec":13,"n":10,"title":"一条腿突然肿起来、发紧、按着疼，尽快就医；再加上突然喘不上气或者胸痛，立刻打 120","cost":"下肢静脉超声一两百元","human":"一条腿突然肿起来、比另一条粗一圈、按着疼，尽快去做腿部静脉超声。再出现突然喘不上气、深吸气时胸痛、心跳快、发晕，血栓可能已经跑到肺里，直接打 120——确诊肺栓塞的人 3 个月内死亡 17.4%。久坐超过 4 小时风险大约翻倍，但绝对概率仍然很低。","gain":"国际肺栓塞协作登记（ICOPER）收 7 个国家 52 家医院 2454 例确诊急性肺栓塞：3 个月全因死亡率 17.4%（426/2454）；世界卫生组织 WRIGHT 项目：连续 4 小时以上的旅行让静脉血栓栓塞的风险「大约翻倍」，但绝对风险仍然低，久坐不动超过 4 小时「约为六千分之一」","grade":"B","src":"Goldhaber SZ, Visani L, De Rosa M (1999). Acute pulmonary embolism: clinical outcomes in the International Cooperative Pulmonary Embolism Registry (ICOPER). Lancet, 353(9162), 1386-1389. <https://doi.org/10.1016/S0140-6736(98)07534-5> ; WHO (2007). Study results released on travel and blood clots. <https://www.who.int/news/item/29-06-2007-study-results-released-on-travel-and-blood-clots>","note":"两条腿一起肿多半是心、肝、肾或静脉功能的问题；一条腿突然肿、比另一条粗一圈才是深静脉血栓的典型样子。高发场景是长途车机久坐、手术或骨折后卧床、打石膏、孕产期、肿瘤、口服避孕药。血栓脱落堵住肺动脉就是肺栓塞：突然气短、深吸气时胸痛加重、心跳快、发晕、咯血，这一步直接打 120。17.4% 是确诊肺栓塞病例的死亡率，不是「腿肿了就有这么大风险」，别对着这个数字吓自己。","money":"少","time":"中","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.11","sec":13,"n":11,"title":"大出血先用手死死压住伤口，四肢压不住就上止血带，同时打 120","cost":"一根旋压式止血带几十到一百多元，放车里和急救包里；学一次「扎在伤口上方、拧到血停、记时间」几分钟","human":"顺序是：先用手或衣物死死压住 → 四肢压不住就上止血带 → 打 120 → 上了就不松开。战地数据里休克出现前上止血带的活了 90%，休克之后才上只剩 10%，该上没上的 5 个人全死了。扎在伤口上方、拧到血停、记下时间。别拿鞋带绳子代替，脖子和躯干只能压不能扎。","gain":"美国得州 11 家一级创伤中心 6 年 1,026 例四肢血管伤，181 例（17.6%）院前上了止血带：粗死亡率止血带组 3.9%、未用组 5.2%，多因素校正后止血带与存活独立相关（校正 OR 5.86，95% CI 1.41 到 24.47）；巴格达战地医院 232 名伤员：休克出现前上止血带存活 90%，休克后才上只有 10%；需要止血带而没上的 5 人全部死亡，上了的存活 87%。顺序：直接压迫（衣物、毛巾都行）→ 压不住的四肢出血上止血带 → 打 120 → 不松开","grade":"A","src":"Teixeira PGR 等 (2018). Civilian Prehospital Tourniquet Use Is Associated with Improved Survival in Patients with Peripheral Vascular Injury. Journal of the American College of Surgeons. <https://doi.org/10.1016/j.jamcollsurg.2018.01.047> ; Kragh JF 等 (2009). Survival with emergency tourniquet use to stop bleeding in major limb trauma. Annals of Surgery. <https://doi.org/10.1097/SLA.0b013e31818842ba>","note":"不要用绳子、鞋带一类细物当止血带，勒不住动脉还割伤皮肤；上了止血带不要隔一会儿松一下「放放血」；躯干、颈部出血只能压，不能扎。Kragh 数据里止血带本身没有导致截肢，短暂神经麻痹 4 例。国家卫健委、中国红十字会的止血教材页本次未能打开，TODO（待核实：中国官方止血带培训原文）。","money":"少","time":"中","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":true,"ratio":"高"},{"id":"13.12","sec":13,"n":12,"title":"被狗、猫咬伤或抓破皮，先用肥皂水和流水交替冲 15 分钟，当天去打疫苗","cost":"冲洗 0 元；狂犬病疫苗全程几百元，三级暴露加打狂犬病被动免疫制剂几百到上千元；最贵的是耽误","human":"狂犬病一旦发病病死率几乎 100%，冲洗加疫苗是唯一的路。先用肥皂水和流动清水交替冲 15 分钟，当天去打疫苗；贯穿性咬伤、破皮处被舔属于三级暴露，还要加打被动免疫制剂。「家养的、打过针的」不改变处置，级别按伤口定，不按狗的来历定。","gain":"国家疾控局、国家卫健委 2023 年版规范原文：「狂犬病病死率几乎达 100%」，处置是「用肥皂水（或者其他弱碱性清洁剂）和一定压力的流动清水交替彻底冲洗所有咬伤和抓伤处约 15 分钟」，裸露皮肤被轻咬、无出血抓伤为 II 级暴露要打疫苗，贯穿性咬伤、破损皮肤被舔为 III 级暴露「应处置伤口并注射狂犬病被动免疫制剂和接种狂犬病疫苗」；WHO：全球每年约 5.9 万人死于狂犬病，99% 由狗传播","grade":"A","src":"国家疾控局综合司、国家卫生健康委办公厅 (2023). 关于印发狂犬病暴露预防处置工作规范（2023 年版）的通知. <https://www.ndcpa.gov.cn/jbkzzx/c100014/common/content/content_1706569159854649344.html> ; WHO. 狂犬病 实况报道. <https://www.who.int/zh/news-room/fact-sheets/detail/rabies>","note":"不要因为「家养的、打过针的」就不处理，规范按暴露级别定处置，不按狗的来历；不要自己包扎伤口；十日观察法只能决定是否停针，不能决定要不要开始打。被野生动物、蝙蝠咬伤同样处理。","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.13","sec":13,"n":13,"title":"烫伤后立刻用凉的流动水冲 20 分钟，别抹牙膏酱油","cost":"0 元；20 分钟","human":"受伤 3 小时内用凉的流动水冲够 20 分钟，最后需要植皮的概率大约只有没冲的六成。是凉水不是冰水，冰敷会加重损伤；衣服粘在伤口上别硬撕，冲完拿干净布盖住去医院。牙膏、酱油、香油、面粉都不要抹。隔了一会儿才想起来，三小时内补冲仍然有用。","gain":"澳大利亚 2495 名烧烫伤儿童的队列：受伤后 3 小时内用凉流动水冲 20 分钟的孩子，需要植皮的比值比 0.6（95% CI 0.4–0.8）；7 项研究的荟萃分析同样发现「伤后三小时内 20 分钟凉流动水显著降低了需要植皮和手术处理创面的可能」","grade":"A","src":"Griffin BR, Frear CC, Babl F, Oakley E, Kimble RM (2020). Cool Running Water First Aid Decreases Skin Grafting Requirements in Pediatric Burns: A Cohort Study of Two Thousand Four Hundred Ninety-five Children. Annals of Emergency Medicine, 75(1), 75-85. <https://doi.org/10.1016/j.annemergmed.2019.06.028>；Griffin B, Cabilan CJ, Ayoub B, et al. (2022). The effect of 20 minutes of cool running water first aid within three hours of thermal burn injury on patient outcomes: A systematic review and meta-analysis. Australasian Emergency Care, 25(4), 367-376. <https://doi.org/10.1016/j.auec.2022.05.004>","note":"是凉水不是冰水，冰敷会加重损伤。衣服粘在伤口上就别硬撕，冲完用干净布盖住去医院。牙膏、酱油、香油、面粉都不要抹，会影响判断深度还容易感染。三小时内补冲仍然有用","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"13.14","sec":13,"n":14,"title":"突然全身起疹、喘不上气或者发晕，按过敏性休克处理，立刻叫 120 并说清楚","cost":"0 元；已知严重过敏的人自备肾上腺素笔要花钱，且是处方药","human":"突然全身起疹，再加上喘不上气或者发晕，就按过敏性休克办：立刻打 120，电话里直接说「怀疑过敏性休克」，让急救带着肾上腺素来。肾上腺素是一线药，抗过敏药和激素起效慢，顶不了这个位置。有过一次的人找医生开自动注射笔，打大腿中外侧，隔着裤子也能打。","gain":"肾上腺素是二级及以上过敏性休克的一线药，指南列为强推荐；抗过敏药和激素起效慢，替代不了它","grade":"B","src":"中国医药教育协会等 (2022). 过敏性休克急救临床实践指南（2020）. Frontiers in Pharmacology：「Epinephrine is the first-line medicine in GRADE II to IV anaphylaxis」「Intramuscular epinephrine should be injected in the mid-anterolateral thigh」，成人肌注上限 0.5 mg、14 岁以下 0.3 mg，无反应可每 5–15 分钟重复一次. <https://doi.org/10.3389/fphar.2022.845689>；Muraro A, et al. (2022). EAACI guidelines: Anaphylaxis (2021 update). Allergy. <https://doi.org/10.1111/all.15032>","note":"EAACI 自己写明这个领域「证据大多停留在很低的等级」，强推荐来自获益远大于风险，不是来自大型试验。肾上腺素在国内是处方药，普通人手上通常没有，能做的是立刻叫 120 并说「怀疑过敏性休克」，让急救带着药来。有过一次严重过敏的人，找医生开自动注射笔，学会打在大腿中外侧，隔着裤子也能打。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"13.15","sec":13,"n":15,"title":"有人抽搐倒地，清开周围、让他侧躺、看表计时，什么都别往嘴里塞","cost":"0 元","human":"把周围的硬东西挪开，让他侧躺、嘴朝下，看表记时间。别按住他、别掰嘴、别往嘴里塞东西，那只会弄伤牙齿和下颌。超过 5 分钟不停、停了很快又发作、发作后叫不醒或呼吸困难、在水里发作、这是头一次发作，都要叫救护车。等人完全清醒再给水。","gain":"避免掰嘴、塞硬物造成的牙齿和下颌损伤，避免强行按住造成的骨折；超过 5 分钟不停是必须叫救护车的红线","grade":"B","src":"美国疾病控制与预防中心. 癫痫发作急救：「Don't hold the person down or stop their movements」「Don't put anything in their mouth. This can hurt their teeth or jaw」「Don't offer water or food until they are fully alert」「Time the seizure to track if it lasts more than 5 minutes. If it does, seek immediate medical attention or call 911」. <https://www.cdc.gov/epilepsy/first-aid-for-seizures/index.html>","note":"同一页还列了另外几种要立刻叫救护车的情况：一次结束后很快又发作、发作后叫不醒或呼吸困难、发作中受了伤、在水里发作、这是第一次发作。发作停了让他侧躺、嘴朝下，等人完全清醒再给水。按受益人口径，这条的主线是自家人——家里有癫痫的人，这套动作就是给他准备的；对陌生人做同样的动作收益档次低一些，但也不会让你担责（民法典第一百八十四条，见本节第 2 条）。","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.16","sec":13,"n":16,"title":"糖尿病人突然发抖、出冷汗、说话不清，先给 15 克糖，15 分钟后复测","cost":"0 元；随身带几块方糖或一小盒果汁","human":"先吃 15 克糖——方糖、一小盒果汁都行，15 分钟后再测一次，还低就再来一次。血糖低于 3.0 就是有临床意义的低血糖，到了要别人帮忙才能处理的程度可以致命。意识不清的人一口都别喂，会呛进气管，直接打 120。","gain":"血糖低于 3.0 mmol/L 属于临床上有意义的低血糖；出现意识或行动改变、需要别人帮忙处理的是重度低血糖，可以致命","grade":"A","src":"美国糖尿病学会 (2025). 糖尿病诊疗标准 2025·第 6 章 血糖目标与低血糖. Diabetes Care：分级「Level 1: Glucose <70 mg/dL (<3.9 mmol/L) and ≥54 mg/dL (≥3.0 mmol/L)」「Level 2: Glucose <54 mg/dL (<3.0 mmol/L)」「Level 3: A severe event characterized by altered mental and/or physical status requiring assistance for treatment of hypoglycemia, irrespective of glucose level」；处理「For most individuals, 15 g carbohydrates should be ingested」「Fifteen minutes after initial treatment, repeat the treatment if hypoglycemia persists」. <https://doi.org/10.2337/dc25-S006>","note":"意识不清的人不要喂东西，会呛进气管，直接叫 120。同一份标准还建议，用胰岛素或低血糖高风险的人都应该配一份胰高血糖素（「All individuals treated with insulin or who are at high risk of hypoglycemia...should be prescribed glucagon」），鼻喷和预填充针剂比需要现配的剂型好用。这条的默认对象是你自己或家里的糖尿病人，随身带糖也是给他们带的。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"13.17","sec":13,"n":17,"title":"有人触电，先断电，再用干燥的木棍之类挑开电源，不要直接上手拉","cost":"0 元","human":"先断电，或者用干燥的木棍之类把电源挑开，再碰人。直接上手拉，一个伤者就变成两个。脱离电源后没有呼吸的，立刻按第 1 条按压，别因为是电伤就不敢碰。高压线落地、变电设备附近不自己处置，退远等电力部门断电。","gain":"避免施救的人一起被电住，把一个伤者变成两个；脱离电源后没有呼吸的，按本节第 1 条做心肺复苏","grade":"C","src":"TODO（待核实：本条是急救培训的普遍共识，本次未找到可逐字核对的权威原文。欧洲复苏委员会《2021 特殊情况下的心脏骤停》含触电章节，但全文付费、本机读不了 PDF）. <https://doi.org/10.1016/j.resuscitation.2021.02.011>","note":"「先断电再碰人」是纯自利规则：直接上手拉，倒下的第二个就是你。高压线落地、变电设备附近不要自己处置，退远等电力部门断电。触电引起的心脏骤停按标准流程按压和除颤，别因为是「电伤」就不敢碰。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":true,"ratio":"极高"},{"id":"13.18","sec":13,"n":18,"title":"一氧化碳报警器响了，或者一屋子人同时头痛恶心，先出门再打电话","cost":"0 元","human":"报警器响了，或者一屋子人同时头痛、恶心、发晕，先把人都带到室外，再打电话。别留在屋里找原因，也别回去关阀门。症状像感冒又像喝多了，「出门就好转」是最强的提示。美国每年 400 多人死于和火灾无关的一氧化碳中毒，10 万人以上进急诊。","gain":"美国每年 400 多人死于与火灾无关的意外一氧化碳中毒，10 万人以上进急诊、1.4 万人以上住院","grade":"B","src":"美国疾病控制与预防中心. 一氧化碳中毒：「More than 400 Americans die from unintentional CO poisoning not linked to fires」「More than 100,000 visit an emergency department」「More than 14,000 are hospitalized」，常见症状「headache, dizziness, weakness, upset stomach, vomiting, chest pain, and confusion」. <https://www.cdc.gov/carbon-monoxide/about/index.html>；美国消费品安全委员会. 一氧化碳信息中心：「If you suspect CO poisoning, get outside to fresh air immediately, and then call 911」. <https://www.cpsc.gov/Safety-Education/Safety-Education-Centers/Carbon-Monoxide-Information-Center>","note":"症状像感冒又像喝多了，一屋子人一起难受、出门就好转是最强的提示。别留在屋里找原因、别回去关阀门，人先出来再打电话。报警器怎么装见第 1 节第 3 条。TODO（待核实：中国全国层面的一氧化碳中毒死亡人数，本次未取得官方统计）。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":true,"ratio":"极高"},{"id":"13.19","sec":13,"n":19,"title":"误服清洁剂、农药、药物先别催吐，带上瓶子立刻就医；溅到眼睛或皮肤用大量清水冲 15 分钟","cost":"0 元；把清洁剂、消毒液、农药和药品放到孩子够不着的高处或者带锁的柜子里，绝不分装进饮料瓶","human":"误服清洁剂、农药、药物不要催吐——腐蚀性液体吐出来会把食管再烧一遍。先喝适量牛奶或蛋清，带上瓶子和说明书立刻就医，医生要靠它认成分。溅到皮肤或眼睛，用大量清水冲够 15 分钟，眼睛要撑开眼皮冲、不要揉。消毒液和洁厕剂混着用会产生氯气，当场就能出事。","gain":"中国疾控中心职业卫生与中毒控制所给的处置口径——消化道摄入：立即饮用适量的牛奶或蛋清，「切记，不要催吐」，尽快就医，同时携带包装或说明书，「以便于医生快速判断成分并制定救治方案」；呼吸道吸入：立即转移至通风良好的区域，解开衣领保持呼吸通畅，出现剧烈咳嗽、气促或呼吸困难的立即就医；皮肤接触：立即用大量清水冲洗接触部位至少 15 分钟，注意别让冲洗液溅到眼睛或其他完好皮肤；眼睛接触：立即用大量清水或生理盐水冲洗眼睛至少 15 分钟，冲洗时撑开眼睑让水流充分接触眼球及眼睑内侧，「切勿揉搓眼睛」，冲洗后立即前往眼科。高危产品按 pH 认：pH<3 的是洁厕剂、除垢剂、地板清洁剂、不锈钢光亮剂，部分强力管道疏通剂还含稀硫酸；pH>11 的是管道疏通剂、厨房强力除污剂、洗碗粉、爆炸盐、去污粉。还有一个当场出事的组合：消毒液和含盐酸的洁厕剂一起用会产生氯气，刺激呼吸道、引起剧烈咳嗽和气促，甚至危及生命","grade":"B","src":"中国疾病预防控制中心职业卫生与中毒控制所 (2025). 暑假安全提示：警惕强酸强碱清洁剂. <https://niohp.chinacdc.cn/kpdw/202507/t20250722_308659.htm>","note":"B 级原因是官方科普给的是处置口径和识别方法，没有「照做能降低多少后果」的效应量。不催吐的道理：腐蚀性液体吐出来会把食管再烧一遍。拿不准误服的是什么，就把瓶子、说明书连同呕吐物一起带去医院。预防比急救便宜得多：分类存放、别和食物饮料混放、用完拧紧盖子扔掉空瓶、绝不倒进矿泉水瓶；使用时戴橡胶手套和护目镜、开窗通风、不同类型不混用。一氧化碳见第 18 条，烧烫伤见第 13 条。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"13.20","sec":13,"n":20,"title":"酸碱等化学品溅到身上，立刻脱掉污染的衣服、用大量流动清水冲，眼睛要掰开眼皮冲，冲够时间再走","cost":"0 元；上岗第一天就把洗眼器和冲淋装置的位置看好，别等出事再找","human":"三步：立刻脱掉沾上的衣服鞋袜（衣服兜住的地方伤得最重）→ 大量流动清水冲，皮肤和眼睛都至少 15 分钟，另一份官方口径给到 20 到 30 分钟，就长的那个 → 眼睛撑开眼皮冲，冲完直接去眼科。用常温或微温水，不用热水；创面上别涂任何东西，也别拿另一种酸碱去中和。工作中发生的按职业病和工伤走，救治和检查费用由单位承担，去医院带上化学品名称或安全数据表。","gain":"现场三步：立即脱去受污染的衣物鞋袜（毒物会继续经皮肤吸收，衣服兜着的部分伤得最重）；用大量流动清水冲洗，中国疾控中心职业卫生与中毒控制所给的下限是皮肤和眼睛各「至少 15 分钟」，湖南省应急管理厅给的口径是创面冲洗 20 至 30 分钟、「强烈的化学品要更长」，就近取长的那个；眼睛要「撑开眼睑，确保水流充分接触眼球及眼睑内侧」，「切勿揉搓眼睛」，冲完立即去眼科。用常温或微温水，禁用热水。新鲜创面上不要涂油膏、红药水或任何东西，也不要用脏布包裹，涂了会影响医生判断深度。法律那一侧：「化学性皮肤灼伤」和「化学性眼部灼伤」都在法定职业病目录里，工作中发生的按职业病和工伤走；发生急性职业病危害事故的，用人单位「应当及时组织救治、进行健康检查和医学观察，所需费用由用人单位承担」（全国）","grade":"B","src":"中国疾病预防控制中心职业卫生与中毒控制所 (2025). 暑假安全提示：警惕强酸强碱清洁剂. <https://niohp.chinacdc.cn/kpdw/202507/t20250722_308659.htm>；湖南省应急管理厅 (2015). 常见化学品中毒事故的应急处理与治疗. <http://yjt.hunan.gov.cn/yjt/tszt/aqzs/201509/t20150919_3113778.html>；国家卫生健康委等四部门 (2024). 职业病分类和目录（2025 年 8 月 1 日起实施）. <https://www.gov.cn/zhengce/zhengceku/202412/content_6992843.htm>；全国人大常委会 (2018). 职业病防治法（第三十七条）. <https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/201711/t20171104_779851.html>（北京市人民政府转载）","note":"B 级原因是冲洗时长在两份官方材料里是 15 分钟和 20 到 30 分钟两个口径，没有统一的国家标准数字。带上化学品名称、包装或安全数据表（SDS）去医院，医生要靠它定方案。不要随手拿另一种酸碱去「中和」：反应放热和剂量都不可控，湖南那份材料里说的「中和液」指单位事先备好的专用冲洗液，不是现场对冲。石灰粉、水泥粉这类干粉先刷掉再冲水（有的地方应急页面据此说浓硫酸也要先擦干，这一点各处口径不一，本书不写）。家里的清洁剂和误服见第 19 条；上岗前的防护和体检见第 19 节第 10、11 条（上岗前看危害告知、防护用品单位必须给）。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"13.21","sec":13,"n":21,"title":"记住七种最常见的网络骗局，凡是让你先转钱、先交费、共享屏幕的直接挂","cost":"0 元；读一遍下面七行，装「国家反诈中心」App，96110 来电必接","human":"七类记住：刷单返利、虚假投资理财、网络贷款、冒充客服、冒充公检法、杀猪盘、色诱刷单。共同点就一个——让你先转钱、先交费、共享屏幕。真贷款不需要交保证金、做流水；公检法没有「安全账户」，凡是在电话、微信里办案做笔录的都是骗子；只见照片视频、从不见面却总有急事要钱的「恋人」不能信。已经转了钱立刻打 110 止付。","gain":"反电信网络诈骗法第八条要求政府「普及相关法律和知识，提高公众对各类电信网络诈骗方式的防骗意识和识骗能力」，福建省公安厅逐类拆解的识别特征：刷单返利 = 「喊你一起赚钱的大概率是想赚你的钱」，任务单做不完就不退本金；虚假投资理财 = 群里「水军」晒收益、先给小额返利再让你加大投入，提现要「缴税」；网络贷款 = 「贷款并不需要交保证金、做银行流水账，一旦遇上了，一定是假的」；冒充客服 = 说你开了会员要自动扣费、影响征信，逼你转账取消；冒充公检法 = 「公检法机关不存在所谓的『安全账户』，凡是通过电话、QQ、微信、网络等办案、做笔录的『公检法机关』，都是诈骗」；杀猪盘 = 「对于从未见过面，只见到照片或者视频的『恋人』，不可轻信」，永远不视频不见面却常有急事要钱；色诱刷单 = 约见面先「做任务」，钱越交越多","grade":"B","src":"全国人大常委会 (2022). 反电信网络诈骗法（第八条）. <https://www.spp.gov.cn/spp/fl/202209/t20220902_575631.shtml> ; 福建省公安厅 (2023 到 2024). 识骗技巧专栏：刷单 <http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202307/t20230703_6196881.htm> ；投资理财 <http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202312/t20231220_6362145.htm> ；贷款 <http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202312/t20231207_6326741.htm> ；冒充客服 <http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202310/t20231020_6279505.htm> ；冒充公检法 <http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202309/t20230913_6255863.htm> ；杀猪盘 <http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202308/t20230818_6232030.htm> ；色诱刷单 <http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202403/t20240307_6410612.htm> ；96110 <http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202303/t20230306_6126156.htm>","note":"B 级原因是公安部关于各类诈骗发案占比的官方通报页（mps.gov.cn）本次全程 521 打不开，TODO（待核实：公安部或国家反诈中心公布的高发类型及占比）。已经转了钱就立刻打 110 申请止付（见第 8 节第 2 条）。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":true,"ratio":"高"},{"id":"13.22","sec":13,"n":22,"title":"被人用隐私照片、视频威胁，一分钱不给、一条记录不删，立刻报警","cost":"0 元；截图对方账号、聊天、收款码，带手机去派出所","human":"一分钱不给、一条记录不删、当场报警。给了钱只会被认定为「肯给」，接着就有第二次、第三次。截图对方账号、聊天和收款码，带手机去派出所。对方真把照片发出去，是他多一条罪：敲诈勒索数额较大的判 3 年以下，数额巨大的 3 到 10 年。自己先删照片、注销账号，证据没了案就难立。","gain":"给钱不会结束，只会被认定为「肯给」；刑法第二百七十四条：敲诈勒索公私财物数额较大或者多次敲诈勒索的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金，数额巨大的三到十年；民法典第一千零三十二条：任何组织或者个人不得以刺探、侵扰、泄露、公开等方式侵害他人的隐私权，第一千零三十三条禁止以电话、短信、即时通讯工具等方式侵扰私人生活安宁；对方真发了照片，是对方多一条罪，不是你的错；福建省公安厅同类案件提示原文：「一定要保存好证据，及时拨打 110，切勿继续转账」","grade":"B","src":"全国人大 (2020 年修正). 刑法（第二百七十四条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>（北京市公安交管局转载整合文本）；全国人大 (2020). 民法典（第一千零三十二、一千零三十三条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml> ；福建省公安厅 (2024). 因为一条「约炮」信息，我背上 23 万的债务. <http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202403/t20240307_6410612.htm>","note":"不要自己删照片、注销账号、拉黑了事，证据没了案就难立；不要试图「谈判分期」。裸聊敲诈多是境外团伙用录屏加木马读通讯录，「群发给家人」是话术，报警后照样能立案。平台通知删除条款（民法典第一千一百九十五条）本次几个官方全文页都截断在该条之前，TODO（待核实：第一千一百九十五条原文）。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":true,"ratio":"高"},{"id":"13.23","sec":13,"n":23,"title":"高温下头晕、恶心、不出汗或意识不清，立刻挪到阴凉处脱衣泼水降温，意识不清的不喂水、打 120","cost":"0 元","human":"皮肤烫红、说话含糊、意识混乱是热射病，从头晕到昏迷可以只有几十分钟，病死率极高。立刻挪到阴凉通风处、脱掉衣服、用凉水和湿毛巾降温，同时打 120；意识不清的一口水都不要喂，会呛。只是大汗、乏力、皮肤湿冷的热衰竭，移到凉处松开衣服小口喝水，呕吐或者一小时不缓解就去医院。","gain":"美国国家气象局：热射病是「严重的医疗急症」，体温高于 103°F（39.4°C）、意识混乱、说话含糊、皮肤发烫发红，处理是立刻叫急救、移到凉处、用凉水和湿布降温、「不要给液体」；热衰竭（大汗、乏力、皮肤湿冷、脉快而弱）移到凉处、松开衣服、小口喝水，呕吐、恶化或超过 1 小时不缓解就就医；云南省疾控局提示：立即转移到阴凉通风处，冷湿毛巾降温，意识清醒者补含盐饮料，症状严重立即拨打急救电话，重症热射病「病死率极高」；荒野医学会 2019 年热病指南是该领域的执业指南","grade":"B","src":"US National Weather Service. Heat Related Illnesses. <https://www.weather.gov/safety/heat-illness> ; 云南省疾控局 (2026). 出现这些症状，你可能是中暑了. <https://ynsjkj.yn.gov.cn/html/2026/jikongkepu_0719/2606.html> ; Lipman GS 等 (2019). Wilderness Medical Society Clinical Practice Guidelines for the Prevention and Treatment of Heat Illness: 2019 Update. Wilderness & Environmental Medicine. <https://doi.org/10.1016/j.wem.2018.10.004>","note":"不要等「缓一缓」，热射病从头晕到昏迷可以只有几十分钟；不要给意识不清的人灌水，会呛。荒野医学会指南全文需订阅，本次只核实了摘要，冷水浸泡等具体推荐写「待核实」；国家卫健委「高温中暑预防知识要点」页面返回 412 未能打开。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":true,"ratio":"极高"},{"id":"13.24","sec":13,"n":24,"title":"中暑的人只要清醒，就少量多次喝凉的淡盐水或运动饮料，别猛灌、别喝酒和高糖饮料","cost":"0 元；一瓶运动饮料几元","human":"只有清醒的人才喝：凉的淡盐水或运动饮料，少量多次，一小时 500 到 1000 毫升。别一次猛灌，吐出来呛进气管比中暑本身更快要命；不喝酒、不喝高糖饮料，那会让人丢更多水。凉水擦身、冰袋敷颈部腋下腹股沟是往身上用的降温手段，降温永远排在补水前面。意识不清、说话含糊的，一口都不喂。","gain":"中国疾控中心《公众高温中暑预防与紧急处理指南（2014 版）》：「至少每小时喝 2~4 杯凉水（500~1000ml），水温不宜过高，饮水应少量多次」「不要饮用含酒精或大量糖分的饮料。这些饮料会导致失去更多的体液。同时，还应避免饮用过凉的冰冻饮料」；对热射病则明确写「不要给病人喝水」。美国 NIOSH：热衰竭要「鼓励小口频繁地喝凉水」，热痉挛每 15 到 20 分钟补一次含糖和电解质的运动饮料，「不要用盐片」","grade":"B","src":"中国疾病预防控制中心职业卫生与中毒控制所 (2014). 公众高温中暑预防与紧急处理指南（2014 版）. <https://niohp.chinacdc.cn/sndt/201405/t20140530_97623.htm> ; US CDC/NIOSH. Heat-Related Illnesses. <https://www.cdc.gov/niosh/heat-stress/about/illnesses.html>","note":"出大汗后只灌白开水会稀释血钠，所以要含一点盐；一次猛灌容易呕吐，呕吐误吸比中暑本身更快要命。「别喝冰镇的」是指南里的建议，理由是怕胃痉挛，没有量化证据，别把它误读成「不能用冷的」——上一条的凉水擦洗、冷水浸泡、冰袋敷颈部腋下腹股沟，正是官方推荐的一线降温手段，那是往身上用不是往嘴里灌，而且降温永远优先于补水。意识不清、说话含糊的，一口都不要喂","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.25","sec":13,"n":25,"title":"火灾时贴地爬、摸门再开门、门烫就别开，走楼梯不坐电梯，出去了别回头","cost":"家里装 1 到 2 个独立烟感几十元；提前看一眼楼道的两条出口","human":"趴到地上，从烟底下爬向出口。开门前先摸门把和门板，烫、或者门缝在冒烟，就别开这扇门，换第二条路；开门要慢，一冒浓烟立刻关上。走楼梯不坐电梯，一断电就困在里面；出去了不为拿东西回头。衣服着火就停下、倒地、打滚，用手护住脸。出不去就关门堵住门缝，打电话报清自己在哪层哪间。","gain":"美国 FEMA 逃生原文：「趴到地上，从烟下面爬向出口」；开门前先摸门把和门板，「如果是热的，或者门缝有烟，别开这扇门，用第二条路」；开门要慢，一有浓烟立刻关上；衣服着火「停下、倒地、打滚」，用手护脸；出不去就关门、用布或胶带堵门缝和通风口，打电话报位置","grade":"B","src":"US FEMA Ready.gov. Home Fires. <https://www.ready.gov/home-fires>","note":"不要坐电梯（断电即困）、不要为拿财物回头、不要往上跑除非确认楼顶门开着、不要跳楼。国家消防救援局（119.gov.cn）页面本次返回 405/412 未能打开，TODO（待核实：国家消防救援局逃生提示原文，含湿毛巾捂口鼻的说法）。","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":true,"ratio":"高"},{"id":"13.26","sec":13,"n":26,"title":"看到有人溺水，先叫人和打 110/120，伸竿、抛漂浮物，自己不下水","cost":"0 元；忍住往下跳的冲动","human":"溺水的人会本能地往下按施救者，下水的人自己也可能淹死——溺水的人会本能地把施救者往水下按。顺序：大喊叫人 → 打 110/120 → 递长杆、绳子 → 抛救生圈、空桶、矿泉水瓶 → 人上岸没呼吸就立刻按压。不结手拉手的链子下水。全球每年约 30 万人溺亡，这是 1 到 4 岁孩子的第四位死因。","gain":"WHO：全球每年约 30 万人溺亡，92% 在中低收入国家，溺水是 1 到 4 岁儿童第四位、5 到 14 岁第三位死因；WHO 推荐的干预是「安全救援和复苏培训」，即先学会不下水的救法。顺序：大喊叫人 → 打电话 → 递长杆、绳子，抛救生圈、空桶、矿泉水瓶 → 人上岸后无呼吸立刻按压","grade":"C","src":"WHO. 溺水 实况报道. <https://www.who.int/zh/news-room/fact-sheets/detail/drowning>","note":"C 级原因是「不下水」这条规则没有找到官方原文，只有 WHO 的死亡数字和「安全救援」的方向。不要手拉手结链下水，不要没受过训练就去拖人，溺水者会把施救者往下按。「不下水」同样是自利规则：下水的人自己淹死，水里那个是谁都一样。真要救的多半是自家孩子，怎么防在第 1 节第 12 条（儿童近水不离视线）。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.27","sec":13,"n":27,"title":"有人噎住说不出话，站到背后做 5 次拍背加 5 次腹部冲击，倒下就做心肺复苏","cost":"0 元；看一遍动作：一手握拳顶在肚脐上方，另一手包住，向内向上快速冲击","human":"先问一句「你噎住了吗，能说话吗」。还能用力咳、能出声的不要动手，咳嗽本身最管用。说不出话就站到背后，5 次拍背接 5 次腹部冲击——一手握拳顶在肚脐上方，另一手包住，向内向上快冲——反复做到东西出来或人倒下；倒下就开始心肺复苏，同时叫人打急救电话。孕妇和很胖的人改冲胸口。别伸手去嘴里掏看不见的东西，会推得更深。","gain":"美国国立医学图书馆原文：先问「你噎住了吗，能说话吗」，「能用力咳嗽、能说话的不要动手」，咳嗽本身多能把异物咳出；说不出话就「反复做 5 次拍背接 5 次腹部冲击，直到异物出来或人失去意识」；「失去意识就开始心肺复苏」，叫人打急救电话；孕妇、肥胖者改做胸部冲击","grade":"B","src":"US National Library of Medicine, MedlinePlus. Choking – adult or child over 1 year. <https://medlineplus.gov/ency/article/000047.htm>","note":"不要往嘴里伸手掏看不见的东西，会推得更深；不要拍还能咳嗽的人。噎住最常发生在自家饭桌上，这条按受益人口径算的是家里人。国家卫健委、中国红十字会关于海姆立克法的官方页面本次未找到，TODO（待核实：中国官方原文）。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":true,"ratio":"极高"},{"id":"13.28","sec":13,"n":28,"title":"在戈壁、沙漠、无人区迷路或车坏了，留在原地或车旁，先报位置，再遮阳保温，省水，不乱走","cost":"进无人区前告诉别人路线、目的地、返回日期、车型车牌；每人每天 4 升水起；卫星通讯器或北斗短报文设备上千元，租一次几百元","human":"留在原地或车旁：车是最大的遮阳物。顺序是有信号先发位置再打电话 → 遮阳保暖 → 省水，白天不动、夜里凉了再动 → 不乱走 → 用反光镜、烟、三声一组发信号。进去之前把路线、目的地、返回日期和车型车牌告诉别人，按每人每天至少 3.8 升带水，徒步和骑行翻倍。不在正午徒步找路，也不为了省水而不喝。","gain":"美国国家公园管理局莫哈韦沙漠原文：「每人每天至少 1 加仑（约 3.8 升）水，徒步和骑行者每人每天 2 加仑」，「告诉别人你的路线、目的地、返回日期、车型和车牌」，「手机信号时有时无」；死亡谷原文：「热的时候不要在谷底和低海拔徒步」，荒野区域「几乎没有手机信号」，推荐卫星电话。优先级：报平安和坐标（有信号时先发位置再打电话）→ 遮阳保暖（车是最大的遮蔽物）→ 水（白天不动、夜里凉了再动）→ 不乱走 → 信号（反光镜、烟、三声一组）","grade":"C","src":"US National Park Service. Mojave National Preserve Safety. <https://www.nps.gov/moja/planyourvisit/safety.htm> ; US National Park Service. Death Valley Safety. <https://www.nps.gov/deva/planyourvisit/safety.htm>","note":"C 级原因是「留在原地」「三声一组」这些没有找到官方原文，只有饮水量、报备、信号覆盖三点是官方原话。不要在正午徒步找路，不要喝尿，不要为了省水而不喝。应急管理部、国家林草局关于无人区的提示页本次未找到，北斗官网短报文页面「Socket is closed」未能打开，TODO（待核实）。","money":"多","time":"少","will":"是","level":"大","lens":"死亡率","dispute":false,"todo":true,"ratio":"一般"},{"id":"13.29","sec":13,"n":29,"title":"发抖、说话含糊、走路打晃是失温，换掉湿衣、包起来，先暖躯干，喝热甜饮不喝酒","cost":"一张铝箔保温毯几元，一件备用干衣；学会看信号 0 元","human":"体温降到 35℃ 以下就是失温，人会发抖、说话含糊、走路打晃、想不清楚事。换掉湿衣服，用保温毯或干衣裹起来，先暖躯干不先暖手脚，给热的甜饮料，不给酒——酒会压住寒战。不搓四肢、不泡热水澡、不粗暴搬动。不抖了不是好转，是加重。没有意识就做心肺复苏。","gain":"美国国家气象局原文：体温 95°F（35°C）以下即失温，「觉得冷、迟钝、想不清楚，立刻看医生」；处理是「立即就医，把人移到有暖气的室内，先从身体中心开始复温」，给热饮，「酒精会减少寒战」所以不喝，「失去意识做心肺复苏」；冻伤用温水或体温回暖，「不要用热水或壁炉一类辐射热」；荒野医学会 2019 年失温指南是该领域的执业指南","grade":"B","src":"US National Weather Service. During Extreme Cold. <https://www.weather.gov/safety/cold-during> ; Dow J 等 (2019). Wilderness Medical Society Clinical Practice Guidelines for the Out-of-Hospital Evaluation and Treatment of Accidental Hypothermia: 2019 Update. Wilderness & Environmental Medicine. <https://doi.org/10.1016/j.wem.2019.10.002>","note":"不要搓四肢、不要泡热水澡、不要粗暴搬动（严重失温者心脏易骤停），不要因为「不抖了」以为好转，停止寒战是加重。荒野医学会指南全文需订阅，本次只核实了摘要。","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.30","sec":13,"n":30,"title":"被蛇咬，坐下别动、摘掉戒指手表、尽快送医院打抗蛇毒血清，不切、不吸、不绑死","cost":"0 元；提前知道附近哪家医院有抗蛇毒血清","human":"坐下别动，把被咬的肢体固定住，先摘掉戒指手表（接下来会肿），尽快送到有抗蛇毒血清的医院——血清是唯一能逆转大部分毒性作用的东西。不切开、不用嘴吸、不冰敷、不用绳子勒到发紫，也别喝酒别跑动。能远远拍张蛇的照片就拍，别去抓。","gain":"WHO 原文：「立即完全固定被咬的身体部位，并迅速送到最近的医疗机构就医」，「避免使用止血带，并避免切割伤口」，「用针对当地蛇种的适当抗蛇毒血清进行治疗」；「高质量抗蛇毒血清是防止或逆转蛇咬伤的大部分毒性作用的最有效治疗方法」；全球每年约 8.1 万到 13.8 万人死于蛇咬伤，截肢和永久残疾约为死亡数的 3 倍","grade":"B","src":"WHO. 动物咬伤 实况报道. <https://www.who.int/zh/news-room/fact-sheets/detail/animal-bites> ; WHO (2023). 蛇咬伤中毒 实况报道. <https://www.who.int/zh/news-room/fact-sheets/detail/snakebite-envenoming>","note":"能拍到蛇的照片就拍，别去抓；不要喝酒、不要跑动、不要用嘴吸、不要冰敷、不要用绳子勒到发紫。中国卫健委或疾控的蛇咬伤诊疗共识原文本次未找到，中国年死亡数写「待核实」。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":true,"ratio":"高"},{"id":"13.31","sec":13,"n":31,"title":"地震时先看自己在什么房子里：符合抗震设防的楼里就地躲，会垮的老房子门在几步外就出去","cost":"0 元；提前看一眼自己家出门要几步、走哪条路、哪张桌子结实","human":"先看自己在什么房子里。2001 年以后按规范建的楼，要下楼梯、穿门厅才能出去的，就地躲：护住头颈钻到结实桌子下抓牢桌腿，没桌子就贴承重墙蹲下，避开外墙、窗户、阳台。平房、老砖房、没抗震设防的自建房，门就在几步外，出去——在预制板楼成片垮塌的那类地震里，待在室内受伤的概率是跑出去的 4.4 倍。任何情况都不跳楼、不坐电梯、不在摇晃中下楼梯。","gain":"中国地震局科普片《地震来了，是躲还是跑？》口诀是「震时就近躲避，震后迅速撤离」，并明确限定「这里指的是在符合抗震设防要求的建筑内」，理由是这类建筑「整体垮塌的可能性较小」「坠落的建筑构件及装饰物品」「才是对生命安全最大的威胁」，而「震时无保护措施的盲目乱跑」「反而容易被坠落的天花板、吊灯（扇）等物品砸伤」；躲的做法是「用手或者其他软物保护好头颈部」「并牢牢地抓住桌腿」，没有桌子就「迅速贴紧承重墙蹲伏」「避开外墙、窗户、阳台」；「如果在户外」则「应该第一时间疏散到空旷的地方避震」。反过来，1988 年亚美尼亚地震（苏联式预制板楼成片垮塌）的病例对照研究里，「第一下震动之后离开建筑是保护性行为」，待在室内相对跑出去的受伤比值比 4.40（95% CI 2.24–8.71），在建筑内相对在室外 12.20（3.62–63.79），在 5 层以上建筑内相对更矮建筑 3.65（2.12–6.33）","grade":"B","src":"中国地震局（安徽省地震局制作）. 地震来了，是躲还是跑？（科普视频，字幕转录）. <https://www.cea.gov.cn/cea/dzpd/dzcs/5537260/index.html>；Armenian HK, Noji EK, Oganesian AP (1992). A case-control study of injuries arising from the earthquake in Armenia, 1988. Bulletin of the World Health Organization, 70(2), 251-257. <https://europepmc.org/article/MED/1600585>；US FEMA Ready.gov. Earthquakes. <https://www.ready.gov/earthquakes>；Mahue-Giangreco M, Mack W, Seligson H, Bourque LB (2001). Risk factors associated with moderate and serious injuries attributable to the 1994 Northridge Earthquake. Annals of Epidemiology, 11(5), 347-357. <https://doi.org/10.1016/s1047-2797(01)00220-4>","note":"争议，两种结论针对的是两种房子，中国地震局自己也把「躲」的前提写成了「符合抗震设防要求的建筑内」，并要求「因地制宜」「因人而异」，综合考虑建筑抗震能力、所处位置和体能。亚美尼亚那批楼整栋垮塌，躲无处可躲，出去才占优；美国 FEMA 对本国住宅给的是「就地趴下、护住头颈、抓牢，不要往外跑」，那里的伤主要来自坠物和摇晃中移动摔倒，Northridge 的研究还提示伸手去接东西、扶住「看起来稳」的东西会加重受伤。所以判断的不是「跑不跑」，是「这栋楼会不会垮、你几秒内能不能到空地」：2001 年以后按规范建的楼房、需要下楼梯或穿门厅的，就地躲；平房、老旧砖房、无抗震设防的自建房，门就在几步外，出去。亚美尼亚这项研究只比了幸存者中受伤与未受伤的，没纳入遇难者，也没说明是否校正楼层，能跑出去的人本身可能就在低层，数字要打折看。任何情况下都不跳楼、不坐电梯、不在摇晃中下楼梯，到室外要远离高大建筑、高架桥、电线杆、玻璃幕墙和广告牌。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"极高"},{"id":"13.32","sec":13,"n":32,"title":"遇到熊、野猪、成群野狗，别跑、别尖叫、别对视，侧身慢慢退开","cost":"0 元；进山带根登山杖，结伴走、出声走，让动物先知道你来了","human":"别跑，熊上下坡都跑得像赛马；也别爬树，黑熊棕熊都会爬。站住，用低沉的声音一直跟它说话，把自己撑得尽量大，等它不动了侧着身慢慢退开，这样既盯得住它又不会绊倒。真被棕熊扑上来就趴下装死，双手扣在颈后、两腿分开；黑熊相反，不装死，往车里或房子里跑，跑不掉就拿手边任何东西反击。被狗抓咬按第 12 条冲洗打针。","gain":"美国国家公园管理局关于熊的原文：「不要跑，熊上下坡都能跑得像赛马一样快」，「保持冷静，大多数熊不想攻击你，只想被放着不管」，「用低沉的声音持续跟熊说话」，「熊不动时，侧着身慢慢退开，这样既能盯着熊又不会绊倒」，「让自己显得尽量大」，「不要爬树，灰熊和黑熊都会爬树」；被棕熊攻击「装死，趴着双手扣在颈后、双腿分开」，被黑熊攻击「不要装死，逃向车或房子，逃不了就用手边任何东西反击」；被狗咬伤按第 12 条处理","grade":"B","src":"US National Park Service. Staying Safe Around Bears. <https://www.nps.gov/subjects/bears/safety.htm> ；国家疾控局综合司、国家卫生健康委办公厅 (2023). 狂犬病暴露预防处置工作规范（2023 年版）. <https://www.ndcpa.gov.cn/jbkzzx/c100014/common/content/content_1706569159854649344.html>","note":"B 级只对应熊；野猪和野狗的「不跑、慢退、找高处或障碍物挡」是经验（C），国家林草局、地方林草官方提示本次未找到。不要拿食物引、不要凑近拍照、不要带狗进有野猪的山。中国的熊多是黑熊和棕熊，装死与否按上面区分。","money":"0","time":"少","will":"些","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"13.33","sec":13,"n":33,"title":"野外遇上雷雨，钻进有硬顶的车或建筑，避开山脊、孤树、水面和金属","cost":"0 元，代价是行程被打断半小时以上","human":"雷暴范围内的户外没有安全的地方。钻进硬顶的车或者建筑，敞篷车和摩托不算，帐篷、凉亭、树下、岩石突出部也不算。避开开阔地、山脊山顶、孤立的大树、水面和铁栏杆铁杆子。一群人走不了就散开站，别挤成一堆。听见雷就开始撤，最后一声雷响过 30 分钟才算安全。","gain":"雷暴范围内的户外没有安全的地方；最后一声雷响过 30 分钟才算安全","grade":"B","src":"美国国家气象局. 户外雷电安全：「There is no safe place outside when thunderstorms are in the area」「Avoid open fields, the top of a hill or a ridge top. Stay away from tall, isolated trees or other tall objects」「Stay away from water, wet items, such as ropes, and metal objects, such as fences and poles」；实在走不了时「If you are in a group, spread out to avoid the current traveling between group members」；恢复活动「Wait 30 minutes until after the last rumble of thunder」. <https://www.weather.gov/safety/lightning-outdoors>","note":"帐篷、凉亭、树下、岩石突出部都不算掩体。硬顶汽车算，敞篷车和摩托不算。听见雷就开始撤，别等雨下下来。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.34","sec":13,"n":34,"title":"上高原按睡眠海拔慢慢升，症状加重就下撤，不要硬扛","cost":"多花一到两天做适应；预防药是处方药，要出发前问医生","human":"算的是睡在多高，不是白天到过多高：睡在 2450 米以上就有高原病风险。过了 3000 米之后，每晚睡觉的高度只往上加 500 米，每升 1000 米多留一天适应。头痛加恶心、走路打晃、意识变化，或者不动也喘不上气，就往下走——下撤排在吸氧和吃药前面，吸着氧继续往上是错的。","gain":"睡在 2450 米以上就有高原病风险；高原脑水肿和肺水肿不及时下撤会死","grade":"A","src":"美国疾病控制与预防中心. 黄皮书·高海拔旅行与高原病：「Any unacclimatized traveler proceeding to a sleeping altitude of ≥2,450 m (≥8,000 ft)—and sometimes lower—is at risk for altitude illness」；上升速度「500 m (1,650 ft) per night in sleeping altitude once above 3,000 m (9,800 ft)」，每上升 1000 米加一天适应日；乙酰唑胺预防「125 mg twice a day; 250 mg twice a day if >100 kg body weight」；「If symptoms become worse despite rest or treatment at the same elevation」必须下撤. <https://www.cdc.gov/yellow-book/hcp/environmental-hazards-risks/high-altitude-travel-and-altitude-illness.html>；荒野医学会 (2024). 急性高原病预防、诊断与治疗临床实践指南（2024 更新）. Wilderness & Environmental Medicine. <https://doi.org/10.1016/j.wem.2023.05.013>","note":"算的是「睡在多高」，不是白天到过多高。头痛加恶心、走路打晃、意识变化，或者静息状态下喘不上气，都是往下走的信号。下撤优先于吸氧和吃药，吸着氧继续往上是错的。","money":"0","time":"中","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.35","sec":13,"n":35,"title":"被蜱虫叮住，用尖头镊子贴着皮肤稳稳拉出来，别涂油别用火烧","cost":"一把尖头镊子","human":"用尖头镊子贴着皮肤夹住蜱的头部，稳稳地朝外拉出来。别涂油、别用火烧、别扭着拽，那会刺激它把带病原体的体液挤进皮肤，还容易把口器留在肉里。拔完记下日期，之后几周里发烧、起疹、乏力，看病时主动说被蜱咬过——不说很容易被当感冒处理。","gain":"涂油、烧、扭拽会刺激蜱虫把带病原体的体液挤进皮肤，也容易把口器留在肉里","grade":"B","src":"美国疾病控制与预防中心. 被蜱叮咬之后：「Grasp the tick as close to the skin's surface as possible using clean fine-tipped tweezers」「Pull tick away from the skin with steady, even pressure」「Do not use petroleum jelly, heat, nail polish, or other substances to try and make the tick detach from the skin. This may agitate the tick and force infected fluid from the tick into the skin」. <https://www.cdc.gov/ticks/after-a-tick-bite/index.html>","note":"拔完把日期记下来。之后几周里发烧、起皮疹、乏力，看病时主动说被蜱咬过——医生不问、你不说，很容易被按感冒处理。TODO（待核实：中国发热伴血小板减少综合征的年发病数与病死率，本次未取得官方数字）。","money":"少","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":true,"ratio":"一般"},{"id":"13.36","sec":13,"n":36,"title":"野外的水一律烧开再喝，滚开一分钟就够，不用因为海拔高多煮","cost":"一套炉具和燃料的重量","human":"所有能靠喝水致病的微生物，在沸点温度下几秒就死了；再滚一分钟只是给「看走眼」留的余量，不用因为海拔高多煮。烧不了就用过滤器或消毒片，这两样各有覆盖不到的病原体，能烧还是烧。看着清澈的溪水、雪水一样可能有寄生虫。","gain":"所有经饮水致病的微生物在沸点温度下几秒内被灭活；「高海拔水烧不到位」是常见误解","grade":"B","src":"美国疾病控制与预防中心. 黄皮书·旅行者的水消毒：「All organisms that may cause illness from drinking water are killed within seconds at boiling temperature」「CDC recommends that travelers boil water for a full minute to account for user variability in identifying boiling points and to add a margin of safety」「Although the boiling point for water decreases with increasing elevation, at common travel elevations the temperature needed to achieve boiling is still well above the temperature required to inactivate enteric pathogens」. <https://www.cdc.gov/yellow-book/hcp/preparing-international-travelers/water-disinfection-for-travelers.html>","note":"同一页也写了不必真的烧开：60 ℃ 保持 30 分钟同样有效，烧开只是不用温度计就能看见的终点。烧不了就用过滤器或化学消毒片，两者各有覆盖不到的病原体，能烧就烧。看起来清澈的溪水、雪水一样可能有寄生虫，别凭外观判断。","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.37","sec":13,"n":37,"title":"荒郊野外被陌生人索财，钱给他，不动手，记特征，脱身后报警","cost":"身上的现金；压住火气","human":"钱给他，不动手，不还嘴。对方为几百块冒的是抢劫罪：三年以上十年以下起步，入户、持枪、致人重伤死亡的十年以上直到死刑。他拿了钱转身走，你追上去打就不再算正当防卫。脱身后立刻记下体貌、口音、车牌和逃跑方向，打 110。不跟去偏僻处「取钱」，不上对方的车，不交手机密码。","gain":"命比钱贵，对方为几百元冒的是重罪：刑法第二百六十三条，以暴力、胁迫或者其他方法抢劫公私财物的，处三年以上十年以下有期徒刑并处罚金，持枪、入户、致人重伤死亡等情形十年以上直至死刑；刑法第二十条正当防卫只保护「制止正在进行的不法侵害」，对方拿了钱转身走，你追上去打就不再是防卫。脱身后立刻记下体貌、口音、车牌、方向，打 110","grade":"C","src":"全国人大 (2020 年修正). 刑法（第二十条、第二百六十三条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>（北京市公安交管局转载整合文本）","note":"C 级原因是「给钱不对抗更安全」没有直接文献，法条只说明对方的风险和你的边界。不要跟去偏僻处「取钱」，不要交手机密码，不要上对方的车；本条不是教人打架，也不是教人不报警。","money":"少","time":"少","will":"是","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"13.38","sec":13,"n":38,"title":"撞见一群人打架，退开走人，别上去拉架、别围观、别捡地上的家伙；要报警就退到安全距离打 110","cost":"0 元；忍住上前拉一把和站着看热闹这两种冲动；报警之后可能被回访做一次笔录，最多搭进半天","human":"你一动手，性质就从劝架变成参加打架——你一动手，性质就从劝架变成参加打架。参加聚众斗殴判 3 年以下，人多规模大、在马路上、拿了家伙的 3 到 10 年，打出重伤或人命按故意伤害、故意杀人算；治安层面结伙斗殴最高拘留 15 日加罚 2000 元。围观也不是白站着，人越多现场越乱，还容易被误伤。动作是退开走人；愿意报警就退到安全距离打 110，说清地点、几个人、有没有拿刀棍、有没有人躺下不动，远远录一段。看到有人被围着单方面挨打，法律上你确实可以制止——正当防卫保护的不只是自己，也包括别人——但徒手上去多半只是再添一个伤员，喊人、录像、报警更管用。","gain":"刑法第二百九十二条：「聚众斗殴的，对首要分子和其他积极参加的，处三年以下有期徒刑、拘役或者管制」；多次聚众斗殴、人数多规模大社会影响恶劣、在公共场所或者交通要道造成社会秩序严重混乱、持械的，「处三年以上十年以下有期徒刑」；「聚众斗殴，致人重伤、死亡的」，按故意伤害罪、故意杀人罪定罪处罚。治安管理处罚法：殴打他人拘留 5 到 10 日并罚 500 到 1000 元，结伙斗殴按寻衅滋事最高拘留 15 日并罚 2000 元。《关于依法适用正当防卫制度的指导意见》第 5 条：不法侵害「既包括针对本人的不法侵害，也包括危害国家、公共利益或者针对他人的不法侵害」；第 9 条：一方先动手且手段明显过激，或者一方先动手、在对方努力避免冲突的情况下仍继续侵害的，还击一方一般应当认定为防卫行为","grade":"B","src":"全国人大 (1997). 刑法（第二百三十二、二百三十四、二百九十二、三百零五、三百一十条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>；全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第三十、五十一条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；最高人民法院、最高人民检察院、公安部 (2020). 关于依法适用正当防卫制度的指导意见（法发〔2020〕31 号，第 5、9 条）. <https://www.court.gov.cn/zixun/xiangqing/251611.html>；全国人大 (2018). 刑事诉讼法（2018 年修订，第六十二、一百一十、一百一十一、一百九十三条）. 宁夏回族自治区人民检察院转载全文 <https://www.nx.jcy.gov.cn/zwsy/qwfb/202011/t20201119_608817.html>","note":"B 级原因是后果的条文是硬的，但「退开报警、不上手拉架」这一步没有官方原文，是从条文和互殴的认定标准推出来的。「我是来劝架的」不是护身符，认定看的是你动没动手、打了谁。对方已经倒地或者跑了还追上去打，就不再算防卫。这条里稳赚的是「不上手、不围观」；打 110 那一下的好处主要落在地上那个人身上，属于受益人里最低的一档，愿不愿意花这个时间你自己权衡——要权衡就得知道：作证义务本来就有（刑诉法第六十二条：凡是知道案件情况的人都有作证的义务），不打这个电话也不会消失，出了重伤或人命，警方调监控照样找到在场的人，站着围观反而最容易被登记；报案人不愿公开姓名的，办案机关「应当为他保守秘密」（第一百一十一条），说清地点、人数、有没有拿家伙就可以挂，不必留在原地。会走到训诫或者十日以下拘留的，是法院通知出庭后无正当理由拒绝作证（第一百九十三条），路人极少到这一步。不报警本身不违法：刑诉法第一百一十条那句「有权利也有义务」没有罚则，刑法里也没有处罚普通人知情不报的罪名，走开是合法选项；走开之后的红线只有两条——事后帮着藏人或者作假证明包庇（刑法第三百一十条，3 年以下，情节严重 3 到 10 年），以及被找去做证时故意作假证（第三百零五条，3 年以下，情节严重 3 到 7 年）。沉默和如实说都没事，编话才有事。自己被卷进冲突见第 8 节第 9 条，被陌生人索财见本节第 37 条，救人受伤之后的钱见本节第 40 条。","money":"0","time":"少","will":"些","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"13.39","sec":13,"n":39,"title":"可能被 HIV 暴露了，72 小时内去拿阻断药，越早越好","cost":"一个 28 天疗程的药费上千元，多数地区自费；当晚就得跑一趟医院","human":"怀疑自己被传染上艾滋病，72 小时是硬线，最好 2 小时内就吃上，药要连吃 28 天。超过 72 小时这条路就没了，所以别等到第二天再决定。","gain":"北京市人民政府防艾科普栏目的口径：暴露后预防（PEP）应「尽可能在 2 小时内进行预防性用药，最好在 24 小时内、不超过 72 小时」，并「连续服用 28 天」。超过 72 小时就不再建议启动，这是一条硬时限——犹豫一晚和当场出发，结果完全不同","grade":"B","src":"北京市人民政府. 事前、事后分不清？六问六答全面了解艾滋病病毒暴露前/暴露后预防. <https://www.beijing.gov.cn/fuwu/bmfw/jhsyfwzdzx/sjazbr/fakp/202311/t20231110_3299397.html>；中国疾病预防控制中心性病艾滋病预防控制中心 (2020). 艾滋病病毒暴露后预防技术指南（试用）. <https://www.chinacdc.cn/jkyj/crb2/yl/azb/jswj_azb/202410/t20241027_302131.html>","note":"去哪里拿：当地疾控中心指定的艾滋病定点医疗机构，通常挂感染科（性病艾滋病门诊）；不少城市已建 24 小时门诊，重庆的公开数据是 26 个区县 29 家门诊、其中 14 家全天候。去之前打当地疾控电话问哪家有药，别在急诊科耗时间。适用的暴露包括无保护性行为、安全套破裂、被针头扎伤、黏膜接触到血液，是否用药由医生评估。药必须吃满 28 天，漏服会显著降低效果；之后按医嘱在第 4 至 6 周、3 个月复查。这是补救不是替代，日常预防和检测见第 1 节第 28、29 条（全程用安全套、有过高危行为就去查）。","money":"多","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"13.40","sec":13,"n":40,"title":"救人受了伤、搭进了钱，先找加害人和医保，再去申报见义勇为确认","cost":"0 元；申报要交材料、等认定，跑几趟，几周到几个月","human":"救人把自己搭进去，不是只能自认倒霉。见义勇为负伤的先救治后收费；医疗费有加害人的由加害人出，人跑了或者赔不起的走基本医保。为保护别人受的损失，先找侵权人赔；没有侵权人、人跑了或者赔不起，被你救下的那个人「应当」给适当补偿——这是法律用词，不是看他良心。同时去申报见义勇为确认：人没了、够条件的评烈士，属于视同工伤情形的有一次性工亡补助金加相当于本人 40 个月工资的遗属特别补助金；伤了的按工伤保险待遇落实，不符合条件的由民政部门评伤残等级；本人和家属还优先纳入就业援助和住房保障。要打官司，见义勇为的民事权益本来就在免费法律援助的范围内。","gain":"民法典第一百八十三条：「因保护他人民事权益使自己受到损害的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任，受害人请求补偿的，受益人应当给予适当补偿」。国办发〔2012〕39 号：对见义勇为负伤人员，医疗机构要建立绿色通道，「坚持『先救治、后收费』的原则」，「因紧急救治发生的医疗费用，有加害人或责任人的，由加害人或责任人承担；无加害人或责任人以及加害人或责任人逃逸或者无力承担的，按规定通过基本医疗保障制度解决」；死亡的「符合烈士评定条件的，依法评定为烈士」，「属于视同工伤情形的，享受一次性工亡补助金以及相当于本人 40 个月工资的遗属特别补助金」；伤残的「符合享受工伤保险待遇条件的，依据《工伤保险条例》落实相应待遇；不符合的，由民政部门评定伤残等级并落实相应待遇」；就业「优先纳入就业援助，予以重点支持」、公益性岗位「优先安排符合条件的见义勇为人员」，住房「优先纳入住房保障体系，优先配租、配售保障性住房或发放住房租赁补贴」","grade":"B","src":"全国人大 (2020). 民法典（第一百八十三条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；国务院办公厅转发民政部等部门 (2012). 关于加强见义勇为人员权益保护的意见（国办发〔2012〕39 号）. <https://www.gov.cn/zwgk/2012-07/26/content_2191928.htm>","note":"B 级原因是待遇口径由全国文件写死，但奖金标准和认定程序各省的见义勇为条例自己定，数字地方不同，本轮未逐省核实；一般向事发地公安机关或见义勇为工作机构（基金会）申报。认定靠证据：报警回执、现场监控、目击者姓名和电话、医院病历，当场就留下。一次性工亡补助金的全国标准和伤残等级怎么换算成钱见第 19 节第 15、16 条，法律援助怎么申请见第 7 节第 3 条。","money":"0","time":"中","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"13.41","sec":13,"n":41,"title":"刀、钢筋、玻璃扎进身体，压住异物周围止血，不要把它拔出来","cost":"0 元；忍住「先拔出来」的本能，守着人等救护车","human":"拔出来可能造成大出血，也会让医生更难判断伤得多深，医生也更难判断到底伤了多深。做法是：打 120，用手或敷料压住异物周围的伤口止血，把异物垫稳别让它晃，人别走动。异物随脉搏一跳一跳的，就松松地稳住，别硬按硬扶正。肚子上的伤口有内脏露出来，不要往回塞，盖一块干净的湿敷料。胸口的伤口在冒泡或者出声的，别用塑料布之类把它封死，封死可能把气憋在胸腔里、把肺压瘪。","gain":"国际红十字与红新月会联合会 2025 年国际急救指南：「First aid providers should apply pressure around an embedded object (e.g. a knife) to stabilize the object. Avoid removing the object.」；「Do not remove any impaled objects from an abdominal or chest wound, as this may cause serious bleeding and make it more difficult for a medical professional to determine the severity of the wound.」；「Impaled objects in the body should be stabilized, and if the object is pulsating, it should be allowed to do so while loosely stabilized.」；「First aid providers should not push internal organs back into the body.」；未在活动性出血的开放性胸壁伤「may be left open, without the application of a dressing, because a sealed wound may allow air to build up in the chest, which may lead to the lung partially or fully collapsing (pneumothorax)」；所有穿透性胸腹部伤口都应立即呼叫急救","grade":"B","src":"International Federation of Red Cross and Red Crescent Societies (2025). International First Aid, Resuscitation and Education Guidelines 2025，第 256–257、267–268 页. <https://www.ifrc.org/sites/default/files/2026-03/IFRC%20International%20First%20Aid,%20Resuscitation%20and%20Education%20Guidelines%202025.pdf>","note":"定 B 是因为这是指南的良好实践推荐，没有随机试验——不可能把「拔」和「不拔」拿去随机分组。唯一的例外是异物堵住气道让人无法呼吸。到了医院直接找急诊入口的预检分诊台报「穿透伤」，这属于要立刻进抢救室的那一级，不要去挂号窗口排队（见第 24 节第 8 条）；真扎穿了就打 120，救护车会提前通知医院备接诊。大出血的压迫止血和止血带见第 11 条。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"13.42","sec":13,"n":42,"title":"怀疑骨折就别再动那个部位，托着不动、冷敷 20 分钟以内，别自己掰正","cost":"0 元；找块硬板、卷起的杂志或衣物当支撑，冷的东西隔层布敷","human":"手脚受了伤一律先当骨折处理，能不能站、能不能动都排除不了，只有 X 光能确定。做法是让受伤的部位保持不动，用手托住或者用三角巾、硬板在它原来的位置上撑住，尽早冷敷但一次不超过 20 分钟、隔层布别直接贴皮肤。城里等得到救护车就别自己掰正，掰正只在野外、指望不上救援、断端以下发凉发白且施救者受过训练时才考虑。大腿骨折光是骨头本身出的血就可能致命，疼得厉害、肿得厉害、肢体位置明显不对或者有休克表现的直接打 120。断骨戳破皮肤的先止血、盖干净敷料，别把骨头按回去。","gain":"国际红十字与红新月会联合会 2025 年国际急救指南：「Any injury to an extremity should be approached as a potential bone fracture.」「The only accurate way to diagnose a fracture is with an X-ray. When in doubt, assume it is a fracture.」；固定的目的是「to minimize any movement and pain」；冷敷「for up to 20 consecutive minutes, as this may decrease the pain. Cooling for longer than this may damage the skin」；「If a long bone is injured, such as the femur, the bleeding from the bone itself can be life-threatening」；疼痛或肿胀明显、有休克表现、股骨骨折或者肢体位置异常时应呼叫急救；成角骨折的现场复位只在「remote environment (or one with limited resources) and the limb below the angulated fracture is cool, pale or the first aid provider is unable to splint for movement」且施救者受过训练时才考虑；开放性骨折的优先事项是止血和防感染","grade":"B","src":"International Federation of Red Cross and Red Crescent Societies (2025). International First Aid, Resuscitation and Education Guidelines 2025，第 301–302 页. <https://www.ifrc.org/sites/default/files/2026-03/IFRC%20International%20First%20Aid,%20Resuscitation%20and%20Education%20Guidelines%202025.pdf>","note":"定 B 是因为这些是良好实践推荐：院前牵引固定股骨骨折只有一项回顾性队列支持（24 小时内输血量更少、住院更短，死亡率和并发症的差异未达显著，证据确定性很低），先复位还是原位固定则根本没找到证据。三个常见误解要改掉：能站能走不等于没骨折；只用冷不用热，也不要冷热交替；扭伤不会「活动开就好了」，先歇着。老人跌倒后怀疑骨折的搬动禁忌见第 2 条；打了石膏或卧床之后一条腿肿起来要警惕血栓，见第 10 条；治完之后要不要做伤残鉴定、要不要办残疾人证，见第 24 节第 10、11 条。","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"}]},{"n":14,"title":"账号与信息安全","intro":"口径：金钱与个人信息。账号被别人拿走，损失的是钱、通讯录里的人和你的身份。","entries":[{"id":"14.1","sec":14,"n":1,"title":"邮箱、支付、社交账号都开二次验证，优先用手机弹窗确认，其次才是短信验证码","cost":"0 元；每个账号设置一次，两三分钟","human":"手机上弹窗确认这类验证，拦下了九成以上源于钓鱼的盗号尝试和全部自动化盗号；靠「上次登录地点」「备用邮箱」这类问答验证，钓鱼盗号只能拦下一成左右。设置一次，几分钟。","gain":"谷歌对 35 万次真实劫持尝试的评估：设备类验证（手机上的弹窗确认、安全密钥）拦下了「超过 94% 源于钓鱼的劫持尝试和 100% 的自动化劫持尝试」；而知识类验证（问上次登录地点、备用邮箱之类）「只拦下了低至 10% 的钓鱼劫持和 73% 的自动化劫持」","grade":"A","src":"Doerfler P, Thomas K, Marincenko M, et al. (2019). Evaluating Login Challenges as a Defense Against Account Takeover. The World Wide Web Conference (WWW '19). <https://doi.org/10.1145/3308558.3313481>","note":"同一研究也发现验证会挡住正常用户：52% 的合法用户第一次登不进去，不过 97% 最终能进。先开邮箱的，因为所有别的账号都能用邮箱找回密码","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"14.2","sec":14,"n":2,"title":"邮箱密码单独一个，不和任何网站重复","cost":"0 元；用密码管理器就不用记","human":"别处网站泄露的密码会被直接拿来登你的邮箱。邮箱一旦被人登进去，凡是能用邮箱找回密码的账号都跟着一起丢。","gain":"撞库是最省事的攻击方式：别处泄露的密码直接拿来登你的邮箱，一旦邮箱失守，所有用它找回密码的账号一起失守","grade":"C","src":"作者经验，无直接文献","note":"记不住就用浏览器自带的密码管理器，比重复用一个密码强得多。别把密码存在微信收藏或备忘录里","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"14.3","sec":14,"n":3,"title":"手机设锁屏密码，SIM 卡设 PIN 码","cost":"0 元；设一次","human":"手机丢了，捡到的人最快的一步是把 SIM 卡插进另一部手机收验证码，再一个个重置你的账号。SIM 卡设了 PIN 码，换机开机就要密码，这条路直接断掉。","gain":"手机丢了以后最快的攻击路径是把 SIM 卡插到别的手机上收短信验证码，再一个个重置账号。SIM 卡有 PIN 码，换机后开机就要密码，这条路直接断掉","grade":"C","src":"作者经验，无直接文献","note":"PIN 码在手机的「SIM 卡锁」里设，默认初始码通常是 1234 或 0000，连错三次要拿 PUK 码解锁，设完先记下来","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"14.4","sec":14,"n":4,"title":"手机丢了按这个顺序做：挂失 SIM 卡、远程锁定、改密码、报警、冻结银行卡","cost":"0 元；十几分钟","human":"顺序比手速重要：先挂失 SIM 卡断掉验证码这条命脉，再远程锁定和抹除手机，然后从电脑上改邮箱和支付密码，接着报警拿回执，最后按需要冻结银行卡。用别人的手机打运营商客服也能挂失。","gain":"顺序比速度重要：先挂失 SIM 是断掉验证码这条命脉，再远程锁定和抹除设备，再从电脑上改邮箱和支付密码，然后报警拿回执，最后按需要冻结银行卡","grade":"C","src":"作者经验，无直接文献；补办身份证见第 7 节，冒名贷款见第 8 节关于征信的一条","note":"提前记住三大运营商的客服号（移动 10086、联通 10010、电信 10000）和自己的手机号归属地。用别人的手机也能打客服挂失","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"14.5","sec":14,"n":5,"title":"卡被盗刷先挂失冻结再报警，然后要求银行赔：证明「是你自己刷的」是银行的责任","cost":"0 元；发现异动立刻挂失或冻结，留下报警记录、挂失记录和交易通知；卡还在身上的，就近做一笔小额查询或存取，把「真卡所在地」固定下来","human":"卡被盗刷，不需要你证明「不是我刷的」；反过来，银行要拿出证据证明这笔是你本人刷的或你授权的，拿不出就得赔——储蓄卡赔存款本息和损失，信用卡扣掉的透支款要退回来、还不能反过来找你要这笔钱，不良征信记录也要撤销。前提是发现异动立刻挂失冻结：拖着不挂失，多出来的那部分损失自己承担；密码和验证码外传的，也要自己担一份责任。","gain":"最高法的规定把举证责任分开了：持卡人主张是伪卡盗刷或者网络盗刷的，可以用生效法律文书、银行卡交易时真卡所在地、交易行为地、账户交易明细、交易通知、报警记录、挂失记录等来证明；**发卡行、非银行支付机构主张这笔是持卡人本人交易或者其授权交易的，应当承担举证责任**。你告知银行之后，银行没及时核实、没及时提供或者保存交易单据、监控录像，导致证据拿不到的，由银行承担举证不能的后果。认定成立后：借记卡持卡人可以请求发卡行支付被盗刷存款本息并赔偿损失；信用卡持卡人可以请求返还扣划的透支款本息、违约金并赔偿损失，银行反过来要你偿还这笔透支的，法院不予支持。还可以请求发卡行及时撤销相应的不良征信记录（全国，2021 年 5 月 25 日起施行）","grade":"A","src":"最高人民法院 (2021). 关于审理银行卡民事纠纷案件若干问题的规定（第四、五、七、十四、十五条）. <https://www.court.gov.cn/fabu/xiangqing/304771.html>","note":"两种情形会让你自己担责：一是对银行卡、密码、验证码等身份识别信息和交易验证信息「未尽妥善保管义务具有过错」的，按过错承担相应责任——所以密码不外传、验证码不转发（见第 1 条）；二是没及时挂失导致损失扩大的，扩大的那部分自己承担，所以第一步永远是挂失冻结而不是先打客服争论。第三方支付机构同样适用这套规则，宣传资料里写了「先行赔付」且允诺具体明确的，可以据此要求先赔。钱是被骗着自己转出去的，那是另一条路，见第 8 节第 2 条。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"14.6","sec":14,"n":6,"title":"每隔一段时间看一次账号的登录设备和已授权应用，不用的清掉","cost":"0 元；每次几分钟","human":"盗号的人常常先潜伏一阵再动手。登录设备里的陌生设备、授权应用里早就不用的第三方，是普通人自己看得见的痕迹，看到就退出全部登录并改密码。","gain":"被盗号往往不是当场发作，攻击者会先潜伏。登录设备列表里的陌生设备、授权应用列表里早就不用的第三方，是最容易发现的痕迹","grade":"C","src":"作者经验，无直接文献","note":"微信、支付宝、邮箱、苹果和安卓账号都有这个入口。发现陌生设备就退出全部登录并改密码","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"14.7","sec":14,"n":7,"title":"别为了用 App 点「全部同意」：不是必需的信息，你不同意也不能拒绝给你服务","cost":"0 元，代价是要忍住不点「全部同意」","human":"不是提供这项服务所必需的信息，你不同意给，对方不能因此不让你用；收集范围也只能限于用得着的最小范围。地图要位置是必需，手电筒要通讯录不是。","gain":"法律明写：不得以个人不同意或者撤回同意为由拒绝提供产品或者服务，处理这些信息属于提供服务所必需的除外；收集应当限于实现处理目的的最小范围","grade":"A","src":"全国人大常委会 (2021). 个人信息保护法. 中国人大网. <http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html>：第六条「收集个人信息，应当限于实现处理目的的最小范围，不得过度收集个人信息」；第十六条「个人信息处理者不得以个人不同意处理其个人信息或者撤回同意为由，拒绝提供产品或者服务；处理个人信息属于提供产品或者服务所必需的除外」；第十五条「基于个人同意处理个人信息的，个人有权撤回其同意。个人信息处理者应当提供便捷的撤回同意的方式」","note":"判断标准是「这项信息是不是提供这个服务所必需」：地图要位置是必需，手电筒要通讯录不是。装完先进系统的应用权限页把不必需的关掉，用到时再单次授权。","money":"0","time":"少","will":"些","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"14.8","sec":14,"n":8,"title":"你有权查看、复制、更正和删除自己的个人信息，被拒绝可以起诉","cost":"0 元；对方拖着不办才需要投诉或起诉，真走到起诉就是几个月起步的事，律师费自理，先走投诉更划算","human":"你有权要求企业让你查看、复制、更正和删除自己的信息；服务停了、保存期限到了、你撤回同意的，企业本来就该主动删。拒绝你的请求必须说明理由，不办可以直接去法院起诉。注销账号和删除信息是两件事，注销之后要另外提删除。","gain":"停止服务、保存期限届满、撤回同意、目的已实现等情形，企业应当主动删除，没删你可以要求删；拒绝行使权利的请求必须说明理由，你可以直接向法院起诉","grade":"A","src":"全国人大常委会 (2021). 个人信息保护法. 中国人大网. <http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html>：第四十五条「个人有权向个人信息处理者查阅、复制其个人信息……个人请求查阅、复制其个人信息的，个人信息处理者应当及时提供」；第四十六条更正、补充权；第四十七条列了五种应当主动删除的情形，含「（一）处理目的已实现、无法实现或者为实现处理目的不再必要」「（二）个人信息处理者停止提供产品或者服务，或者保存期限已届满」「（三）个人撤回同意」，「个人信息处理者未删除的，个人有权请求删除」；第五十条「个人信息处理者应当建立便捷的个人行使权利的申请受理和处理机制。拒绝个人行使权利的请求的，应当说明理由」「个人可以依法向人民法院提起诉讼」","note":"注销账号和删除个人信息是两件事，注销之后要单独要求删除。换手机、卖旧手机之前，先在旧机上退出所有账号并解绑，再恢复出厂设置——法律给的是事后的删除权，不能替你收回已经泄露出去的东西。","money":"0","time":"少","will":"些","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"14.9","sec":14,"n":9,"title":"刷脸不是必须答应的：有别的办法就不能只让你刷脸，你不同意得给你其他方式","cost":"0 元；被要求刷脸时问一句「有没有别的验证方式」，没有就要求提供","human":"只要还有别的办法能达到同样目的，对方就不能把刷脸当成唯一方式；你不同意刷脸，它得给你刷卡、密码或身份证这类替代办法，也不许用「办不了业务」来逼你就范。宾馆客房、公共浴室、更衣室、卫生间这类私密空间里，任何人不得安装人脸识别设备。人脸和密码最大的区别是泄露之后改不掉。","gain":"人脸识别技术应用安全管理办法写明：「实现相同目的或者达到同等业务要求，存在其他非人脸识别技术方式的，不得将人脸识别技术作为唯一验证方式。个人不同意通过人脸信息进行身份验证的，应当提供其他合理、便捷的方式。」「任何组织和个人不得以办理业务、提升服务质量等为由，误导、欺诈、胁迫个人接受人脸识别技术验证个人身份。」基于个人同意处理人脸信息的，应当取得「在充分知情的前提下自愿、明确作出的单独同意」，个人有权撤回同意且处理者要提供便捷的撤回方式；处理不满十四周岁未成年人人脸信息的，应当取得父母或者其他监护人的同意。公共场所安装人脸识别设备「应当为维护公共安全所必需」并设置显著提示标识；宾馆客房、公共浴室、公共更衣室、公共卫生间等公共场所中的私密空间内部，任何组织和个人不得安装。除法律、行政法规另有规定或者取得单独同意外，人脸信息应当存储于人脸识别设备内，不得通过互联网对外传输（全国，2025 年 6 月 1 日起施行）","grade":"A","src":"国家互联网信息办公室、公安部 (2025). 人脸识别技术应用安全管理办法（第 19 号令，第十条、十二条、十三条，2025 年 6 月 1 日起施行）. <https://www.cac.gov.cn/2025-03/21/c_1744174262156096.htm>","note":"最常遇到的是小区门禁、租房平台、健身房、酒店要求录人脸。对方说「系统只支持刷脸」时，把上面那句原文念给它听，并要求提供刷卡、密码或身份证等替代方式；仍不给的，向当地网信部门反映。国家对刷脸验证身份另有规定的（部分金融、政务场景）从其规定。人脸和密码最大的区别是泄露之后改不掉，所以它值得比密码更谨慎。存储量达到 10 万人的处理者要在 30 个工作日内向省级以上网信部门备案，这也是判断对方正不正规的一个问法。查阅、更正、删除自己个人信息的权利见第 8 条。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"}]},{"n":15,"title":"租房与买房","intro":"口径：金钱。租房的钱大头在押金和中介，买房的钱大头在利息和信息不对称。","entries":[{"id":"15.1","sec":15,"n":1,"title":"押金的数额、退还时间和扣减情形，必须写进合同","cost":"0 元；签约时多花十分钟","human":"合同里没写进去的扣款理由，房东退租时不能拿来扣你的押金。押金多少、什么时候退、什么情况下扣，签字前就得写在合同上。","gain":"行政法规明文：「出租人收取押金的，应当在住房租赁合同中约定押金的数额、返还时间以及扣减押金的情形等事项。除住房租赁合同约定的情形以外，出租人无正当理由不得扣减押金。」也就是说，合同里没写的理由，房东不能拿来扣你的钱","grade":"A","src":"国务院 (2025). 住房租赁条例（国令第 812 号，2025 年 9 月 15 日施行）（第十条）. <https://www.gov.cn/zhengce/zhengceku/202507/content_7032956.htm>","note":"退租时和房东一起拍照录像，水电燃气读数、墙面地面都拍。押金被无故扣了，先找房屋租赁管理部门投诉，金额不大的走小额诉讼，见第 8 节","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"15.2","sec":15,"n":2,"title":"被断水断电、换锁、上门威胁赶人，先报警留证：法规禁止用这些方式逼你腾房","cost":"0 元","human":"房东不能靠断水断电、换锁、上门威胁逼你解约或搬走，这是法规明令禁止的。遇上先报警，出警记录是后面主张损失时的证据，不要自己动手对抗。","gain":"行政法规明文：「出租人不得采取暴力、威胁或者其他非法方式迫使承租人解除住房租赁合同或者腾退租赁住房。」遇到这类情况先报警并留证，不要自己动手对抗","grade":"A","src":"国务院 (2025). 住房租赁条例（国令第 812 号，2025 年 9 月 15 日施行）（第十二条）. <https://www.gov.cn/zhengce/zhengceku/202507/content_7032956.htm>","note":"报警的目的是留下出警记录，这是后面主张损失的证据。同时通知房屋租赁管理部门","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"15.3","sec":15,"n":3,"title":"中介不得代收代付租金和押金，钱直接给房东","cost":"0 元","human":"按规定房租和押金不能由中介代收代付，钱直接付给房东。钱在中介手里过一道，就多一次它卷款跑路、你租金白交还被房东赶走的机会。付款前核对收款人是不是产权证上的名字。","gain":"行政法规把「代收、代付住房租金、押金」列为房地产经纪机构的禁止行为。钱在中介手里过一道，就多一次卷款跑路的机会","grade":"A","src":"国务院 (2025). 住房租赁条例（国令第 812 号，2025 年 9 月 15 日施行）（第二十五条）. <https://www.gov.cn/zhengce/zhengceku/202507/content_7032956.htm>","note":"付款前核对收款人是不是产权证上的名字，不是就问清楚并留书面授权。中介只收居间服务费","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"15.4","sec":15,"n":4,"title":"租长租公寓先查它的资金监管账户，别图便宜一次性付一年","cost":"0 元；查一次十几分钟","human":"一次性付一年拿到的那点折扣，抵不上企业暴雷时押金和剩下十几个月房租一起没了。绑了租金贷更糟：公寓跑了，贷款还得你按月继续还完。签约前先查它有没有公示资金监管账户。","gain":"行政法规要求转租经营的住房租赁企业「设立住房租赁资金监管账户并向社会公示」。一次性付一年拿到的那点折扣，抵不上企业暴雷时押金和剩余租金一起没的风险，尤其是同时签了租金贷的","grade":"A","src":"国务院 (2025). 住房租赁条例（国令第 812 号，2025 年 9 月 15 日施行）（第十九条）. <https://www.gov.cn/zhengce/zhengceku/202507/content_7032956.htm>","note":"签约时看清有没有绑定贷款：如果是分期 App 放款给公寓、你按月还贷，那么公寓跑了你还要继续还。这种合同不签","money":"0","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"15.5","sec":15,"n":5,"title":"房子租期内被卖掉，租约继续有效，不用搬","cost":"0 元","human":"租期内房子被卖掉，租约照样有效，新房东要按原合同让你住到期满，不用搬也不用重新谈价。前提是你已经合法住在里面，合同、转账记录、入住时间的证据留好。","gain":"民法典规定的「买卖不破租赁」：租赁物在租赁期限内发生所有权变动的，不影响租赁合同的效力。新房东要按原合同履行到期满","grade":"A","src":"全国人大 (2020). 民法典（第七百二十五条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>","note":"前提是你已经合法占有使用该房屋。所以合同、转账记录、入住时间的证据要留好","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"15.6","sec":15,"n":6,"title":"签约前核对产权证和抵押情况，所有款项走转账并备注用途","cost":"0 元；查一次半小时","human":"最常见的两种血本无归：租金付给了不是产权人的人，以及房子早已抵押给银行、随后被查封。签约前去不动产登记中心查一次产权和抵押，所有钱走转账并备注「某某房屋某月租金」，出纠纷时这就是直接证据。","gain":"把租金付给非产权人、房子早已抵押给银行被查封，是最常见的两种血本无归。转账备注「某某房屋某月租金」在纠纷时就是直接证据","grade":"C","src":"作者经验，无直接文献；证据留存与转账备注同理见第 8 节关于彩礼和借条的两条","note":"产权信息可在当地不动产登记中心查询，房东本人到场或出具授权委托书。二房东转租要有原房东的书面同意","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"15.7","sec":15,"n":7,"title":"二手房让中介代收房款的，必须走中介在银行开的交易资金专用存款账户","cost":"0 元；坚持走专户可能要跟中介多争几句","human":"房款是几十万到几百万，是这本书里单笔金额最大的一件事。中介代收的，按规定必须走它在银行开的交易资金专用存款账户，不能微信转给经纪人个人。另外两处常被多收：两家中介合做一单只能收一份佣金，代办贷款、代办过户是另外的服务，要单独签合同并事先说清收费。","gain":"规章明写：约定由房地产经纪机构代收代付交易资金的，应当通过其在银行开设的客户交易结算资金专用存款账户划转——房款进的是受监管的专户，不是中介或某个经纪人的私人账户","grade":"A","src":"住房城乡建设部、国家发展改革委、人力资源社会保障部 (2011). 房地产经纪管理办法（令第 8 号，2016 年第 29 号令修改）第二十四条：「房地产交易当事人约定由房地产经纪机构代收代付交易资金的，应当通过房地产经纪机构在银行开设的客户交易结算资金专用存款账户划转交易资金。」第十八条「房地产经纪服务实行明码标价制度……在经营场所醒目位置标明房地产经纪服务项目、服务内容、收费标准」；第十九条「两家或者两家以上房地产经纪机构合作开展同一宗房地产经纪业务的，只能按照一宗业务收取佣金，不得向委托人增加收费」；第十七条代办贷款、代办房地产登记等其他服务「应当向委托人说明服务内容、收费标准等情况，经委托人同意后，另行签订合同」. <http://www.gov.cn/gongbao/content/2011/content_1918920.htm>","note":"房款是几十万到几百万，是这本书里单笔金额最大的一件事，别用微信转给经纪人。另外两个常见的多收钱：两家中介联合做一单只能收一份佣金；代办贷款、代办过户属于另外的服务，要单独签合同并事先告知收费。所有款项走转账并备注用途，见本节上一条。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"15.8","sec":15,"n":8,"title":"别租隔断房：最小出租单位是原设计的房间，厨房、卫生间、阳台不得住人","cost":"0 元；代价是同样预算得住得远一点或者小一点","human":"按规定最小的出租单位是原设计的房间，厨房、卫生间、阳台和地下储藏室不能住人。被查处之后可能要搬离；另外，租期内房东也不能单方面随意涨租。","gain":"规章明写最小出租单位是原设计的房间，人均租住建筑面积不得低于当地规定的最低标准，厨房、卫生间、阳台和地下储藏室不得出租供人员居住；租期内出租人也不得单方面随意提高租金","grade":"A","src":"住房和城乡建设部 (2010). 商品房屋租赁管理办法（令第 6 号）第八条：「出租住房的，应当以原设计的房间为最小出租单位，人均租住建筑面积不得低于当地人民政府规定的最低标准。厨房、卫生间、阳台和地下储藏室不得出租供人员居住。」第九条：「出租人应当按照合同约定履行房屋的维修义务并确保房屋和室内设施安全……房屋租赁合同期内，出租人不得单方面随意提高租金水平。」<http://www.gov.cn/gongbao/content/2011/content_1845070.htm>","note":"违规隔断被查处时是租客搬家，押金和已付租金往往拿不回来。安全上也差：隔断墙常常堵掉逃生通道，一屋多人共用一条线路。看房时注意墙是不是后砌的、房间有没有窗、电表能不能承受这么多人。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"}]},{"n":16,"title":"得了慢性病之后怎么活","intro":"口径：总死亡率与金钱。确诊不是终点，之后几十年怎么管才是账。","entries":[{"id":"16.1","sec":16,"n":1,"title":"药按医嘱吃满，别感觉好了就停","cost":"0 元，反而省下并发症的钱","human":"把药按医嘱吃满的人，同期死亡的概率大约只有断断续续吃药的人的一半多一点。这个数要打折看：好好吃安慰剂的人死亡率也低，说明有相当一部分好处来自「肯坚持吃药的人本来就更注意健康」。但停药本身的害处是确定的，降压药、抗凝药和抗排异药尤其如此。","gain":"21 项研究、46847 人的荟萃分析：与依从性差相比，依从性好的人死亡比值比 0.56（95% CI 0.50–0.63）；对确有疗效的治疗依从性好为 0.55（0.49–0.62）","grade":"A","src":"Simpson SH, Eurich DT, Majumdar SR, et al. (2006). A meta-analysis of the association between adherence to drug therapy and mortality. BMJ, 333(7557), 15. <https://doi.org/10.1136/bmj.38875.675486.55>","note":"争议，而且是这本书里最需要打折看的一个数字：同一荟萃分析发现，好好吃安慰剂的人死亡率也低（0.56，0.43–0.74），说明相当一部分好处来自「能坚持吃药的人本来就更注意健康」这个混杂，作者称为健康依从者效应。但停药本身的害处是明确的，尤其是降压药、抗凝药和抗排异药","money":"0","time":"少","will":"是","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"高"},{"id":"16.2","sec":16,"n":2,"title":"先办门诊慢特病认定再办异地备案，高血压、糖尿病、放化疗、透析、抗排异就能异地直接结算","cost":"0 元；提前在医保 App 上做异地就医备案","human":"高血压、糖尿病、恶性肿瘤门诊放化疗、尿毒症透析、器官移植后抗排异这五种，在外地看门诊也能直接刷医保结算，不用先自己垫钱再回参保地报销。要先在参保地办门诊慢特病认定，再办异地就医备案，两件事都办了才管用。","gain":"国家医保局文件写明，已「基本实现高血压、糖尿病、恶性肿瘤门诊放化疗、尿毒症透析、器官移植术后抗排异治疗等 5 种门诊慢特病费用跨省直接结算县域可及」，并在此基础上再新增 5 种","grade":"A","src":"国家医保局办公室、财政部办公厅 (2024). 关于稳妥有序扩大跨省直接结算门诊慢特病病种范围的通知（医保办发〔2024〕19 号）. <https://www.gov.cn/zhengce/zhengceku/202409/content_6974467.htm>","note":"前提是先在参保地办门诊慢特病认定，再做异地就医备案，两件事都要办。新增的 5 个病种和各地开通进度以当地医保部门公布为准","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"16.3","sec":16,"n":3,"title":"复查按医生给的间隔做，把每次的指标记在同一个本子上","cost":"每次几十到几百元","human":"慢性病要看的是一条趋势线，不是某一次的数值。日期、指标、当时吃的药和剂量记在同一处，换医院时也不用把检查重做一遍、重花一遍钱。","gain":"慢性病的价值不在单次数值，在趋势。同一份记录还能避免换医院时重复检查、重复花钱","grade":"C","src":"作者经验，无直接文献","note":"记录至少包含日期、指标值、当时在吃的药和剂量。手机拍化验单也行，关键是集中在一处","money":"少","time":"少","will":"些","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"16.4","sec":16,"n":4,"title":"别为了试偏方、保健品停掉正规治疗","cost":"0 元，还省下买保健品的钱","human":"停药的坏处是确定的，偏方和保健品的好处是不确定的，等于拿确定的损失去换不确定的收益。想试补充剂就先告诉主治医生，有些会影响抗凝药、抗排异药在血里的浓度。","gain":"停药的害处是确定的，偏方的好处是不确定的。这本书第 6 节列了一批常见的无效品类","grade":"C","src":"作者经验，无直接文献；相关证据见第 6 节","note":"想试补充剂就告诉主治医生，有些会和处方药相互作用，比如影响抗凝药和抗排异药的血药浓度","money":"0","time":"少","will":"是","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"16.5","sec":16,"n":5,"title":"病情稳定的慢性病，在社区医院一次可以开到 12 周的药","cost":"0 元，先问一句社区卫生服务中心能不能开长期处方","human":"病情稳定、用药方案不变的，在社区卫生服务中心一次能开够 12 周的药，省掉每月往返大医院排队挂号的半天。同一统筹地区里在基层住院，报销比例通常还比上一级医院高十个百分点左右。","gain":"免掉每月往返大医院排队开药；同一统筹地区内，基层的住院报销比例原则上比上一级高约 10 个百分点","grade":"A","src":"国务院办公厅 (2026). 关于加快建设分级诊疗体系的若干措施. <https://www.gov.cn/zhengce/zhengceku/202604/content_7065031.htm>：「对于符合条件的慢性病患者，基层医疗卫生机构单次可开具不超过12周用药的长期处方。」；同文「原则上统筹地区内医疗卫生机构住院报销比例逐级拉开10个百分点左右的差距」，并要求上级医院在基层开设高血压、糖尿病、慢性阻塞性肺疾病等常见病慢性病门诊","note":"「符合条件」由医生判断，通常是诊断明确、用药方案稳定的。药还是那个药，省的是每月的半天和挂号费。基层缺药的可以问缺药登记配送。","money":"0","time":"少","will":"否","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"16.6","sec":16,"n":6,"title":"在社区签家庭医生之前，问清楚哪些进医保、哪些自费","cost":"0 元，多问一句","human":"签约的基本服务包按规定走医保，个性化服务包的钱全部自己出。被推销「升级包」时先问清楚这是基本包还是个性化包、备没备案、一年多少钱。","gain":"基本服务包按规定纳入医保支付；个性化服务包要向县级卫生健康部门备案，费用由个人支付","grade":"A","src":"国务院办公厅 (2026). 关于加快建设分级诊疗体系的若干措施. <https://www.gov.cn/zhengce/zhengceku/202604/content_7065031.htm>：「加强基层门诊付费与签约服务政策联动，基本服务包按规定纳入医保支付；个性化服务包由签约基层医疗卫生机构按程序向县级卫生健康部门备案，费用由个人支付。」","note":"签约本身的价值在于有人长期跟着你的病，不在于打包了多少项目。被推销「升级包」时，先问这是基本包还是个性化包、备没备案、一年多少钱。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"16.7","sec":16,"n":7,"title":"确诊糖尿病就去查一次眼底，之后按医生给的间隔查；每年查一次脚","cost":"一次散瞳眼底检查几十到几百元；足部检查通常包含在门诊里","human":"糖尿病视网膜病变和糖尿病足在坏到看不见、烂起来之前几乎没有感觉，早查出来还有得干预。2 型糖尿病确诊当时就查一次散瞳眼底，1 型在发病 5 年后开始查；查过一两次没事、血糖也达标的可以放宽到一两年一次，脚每年查一次。","gain":"糖尿病视网膜病变和糖尿病足在出问题之前几乎没有症状，查出来还能干预，等到看不见或者溃烂就晚了","grade":"A","src":"美国糖尿病学会 (2026). 糖尿病诊疗标准 2026·第 12 章 视网膜病变、神经病变与足部护理. Diabetes Care：「People with type 2 diabetes should have an initial dilated and comprehensive eye examination by an ophthalmologist or optometrist at the time of the diabetes diagnosis.」「Adults with type 1 diabetes should have an initial dilated and comprehensive eye examination by an ophthalmologist or optometrist 5 years after the onset of diabetes.」「If there is no evidence of retinopathy from one or more annual eye exams and glycemic indicators are within the goal range, then screening every 1–2 years may be considered.」「Perform a comprehensive foot evaluation at least annually to identify risk factors for ulcers and amputations.」<https://doi.org/10.2337/dc26-S012>","note":"2 型糖尿病确诊时就查，1 型是发病 5 年后开始查——因为 2 型往往已经悄悄高了好几年。查过一两次没事、血糖也达标的，可以放宽到 1 到 2 年一次。有感觉减退的人每天自己看一眼脚底，用镜子也行。","money":"少","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"16.8","sec":16,"n":8,"title":"得过肾结石就把水喝到每天 2.5–3 升，盐降到 6 克以内","cost":"0 元；把随时喝水变成习惯，出汗多的日子还要再加","human":"得过一次结石，五年里再长一次的大约有四分之一。199 个刚犯过第一次钙结石的人随机分成两组，一组只做一件事——把水喝够，五年里复发的是 12%，什么都不做的那组 27%，而且复发来得更晚，平均隔 39 个月对 25 个月。结石患者本来的日尿量就比没结石的人低出一截。英国的诊疗指南把它写成成人每天喝 2.5 到 3 升水、盐每天不超过 6 克。这条一分钱不花，是本节里最便宜的一条。","gain":"5 年随机对照试验：199 名首次特发性钙结石患者随机分为高水摄入组（每天 ≥2 L）与不做任何干预组，5 年复发 12/99（12.1%）对 27/100（27.0%），P=0.008；平均复发间隔 38.7±13.2 个月对 25.1±16.4 个月，P=0.016；基线 24 小时尿量在结石患者中显著低于对照（男性 1,057±238 mL 对 1,401±562 mL，P<0.0001；女性 990±230 mL 对 1,239±440 mL，P<0.001）。NICE 指南 NG118 第 1.8.1 条建议成人每天饮水 2.5 到 3 升、儿童青少年按年龄 1 到 2 升，饮水中加鲜柠檬汁，避免碳酸饮料，成人每天盐不超过 6 克","grade":"A","src":"Borghi L, Meschi T, Amato F, Briganti A, Novarini A, Giannini A (1996). Urinary volume, water and recurrences in idiopathic calcium nephrolithiasis: a 5-year randomized prospective study. The Journal of Urology, 155(3), 839-843. <https://doi.org/10.1016/s0022-5347(01)66321-3>；National Institute for Health and Care Excellence (2019). Renal and ureteric stones: assessment and management. NICE guideline NG118，第 1.8.1 条. <https://www.nice.org.uk/guidance/ng118/chapter/Recommendations>","note":"相对降幅约 55%、成本为零，按本书的排序规则这是本节性价比最高的一条。要盯的终点是 24 小时尿量（目标 2 到 2.5 升以上），不是喝进去多少——出汗多、在高温环境干活的人得喝得更多。那项试验做在首次发作的特发性钙结石患者身上；结石成分不止一种（尿酸结石、感染性结石、胱氨酸结石各有对策），复发过的人值得做一次结石成分分析和 24 小时尿检，再定要不要加药。别为了防结石把钙戒掉，见第 6 节第 21 条。发作时的剧烈腰腹绞痛要就医，不是靠多喝水冲下去的；不疼的血尿另有要查的东西，见第 1 节第 27 条","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"16.9","sec":16,"n":9,"title":"确诊痛风就长期吃降尿酸药，把血尿酸压到 360 µmol/L 以下并一直维持","cost":"别嘌醇每月几元到几十元；起初每几周查一次血尿酸来调量，稳定后每几个月一次；头 3 到 6 个月要同时吃一种预防发作的药","human":"痛风的正确打法是长期把尿酸压到 360 以下，不是疼起来才吃止痛药。英国一项 517 人的试验里，接受这套按指标调药方案的人两年后有 95% 达标，照常规看病的只有 30%；随访问卷里，达标那组过去一年自报发作次数的中位数是 0 次，常规组是 1 次。达标之后也不能停：有一组已经长期稳定、停药后尿酸也没反弹的病人，211 个里只有 27 个在之后五年一次都没发作。忌口有用但量很小——限酒或戒酒的人血尿酸只比不限的低 1.6 mg/dL，一份啤酒推高 0.16 mg/dL，靠改饮食把尿酸降到达标不现实。","gain":"随机对照试验（517 名过去 12 个月内发作过的成人，护士主导的患者教育加达标调药方案对常规全科医生诊疗）：2 年时血尿酸 <360 µmol/L（6 mg/dL）的比例 95% 对 30%，RR 3.18（95% CI 2.42–4.18），P<0.0001，第 2 年发作频率、痛风石、生活质量各项次要终点均优于常规组，每获得一个质量调整生命年的成本 £5,066。同一试验的随访研究（438 人发问卷，82% 回收）：达标组过去 12 个月自报发作次数中位数 0（四分位距 0–0）对常规组 1（0–3），P<0.001；仍在服用降尿酸药的校正后 RR 1.19（1.09–1.30）。美国风湿病学会 2020 年痛风指南强推荐：有皮下痛风石、痛风所致影像学骨破坏或每年发作 ≥2 次者启动降尿酸治疗，采用按血尿酸连续监测调整剂量的达标策略、目标 <6 mg/dL，别嘌醇为一线（含 3 期及以上慢性肾病）、起始剂量 ≤100 mg/日，启动时同时给抗炎预防治疗至少 3 到 6 个月。同一指南引用的病例系列：在长期控制良好后停药、且停药后血尿酸仍保持 <7 mg/dL 的患者中，5 年随访期内一次没发作的只有 13%（27/211）。饮食的效应量：限酒或戒酒者血尿酸比不限的人低 1.6 mg/dL，一份啤酒使血尿酸升高 0.16 mg/dL，健康饮食、地中海饮食、DASH 饮食的效应更小","grade":"A","src":"Doherty M, Jenkins W, Richardson H, et al. (2018). Efficacy and cost-effectiveness of nurse-led care involving education and engagement of patients and a treat-to-target urate-lowering strategy versus usual care for gout: a randomised controlled trial. Lancet, 392(10156), 1403-1412. <https://doi.org/10.1016/S0140-6736(18)32158-5>；Abhishek A, Jenkins W, La-Crette J, Fernandes G, Doherty M (2020). Nurse-led care is preferred over GP-led care of gout and improves gout outcomes: results of Nottingham Gout Treatment Trial follow-up study. Rheumatology, 59(3), 575-579. <https://doi.org/10.1093/rheumatology/kez333>；FitzGerald JD, Dalbeth N, Mikuls T, et al. (2020). 2020 American College of Rheumatology Guideline for the Management of Gout. Arthritis Care & Research, 72(6), 744-760. <https://doi.org/10.1002/acr.24180>","note":"**汉族人用别嘌醇之前值得先查 HLA-B\\*5801**：这个等位基因携带率在汉族、韩国、泰国人中是 7.4%，白人和西班牙裔只有 0.7%，亚裔和非裔用别嘌醇发生别嘌醇超敏综合征（严重时皮肤大面积剥脱，可致命）的风险是白人的 3 倍，上面那份指南对这两类人群有条件推荐用药前检测。**刚开始降尿酸反而更容易诱发发作**，所以指南强推荐头 3 到 6 个月同时吃抗炎预防药——「吃了降尿酸药反而更疼所以停了」是这件事最常见的失败方式，疼起来该做的是按医嘱加抗炎药，不是停降尿酸药。达标值各家写法不同：<6 mg/dL 约合 360 µmol/L，中国化验单多用 µmol/L。体检查出尿酸高但从没发作过是另一回事，见第 6 节第 19 条；含糖饮料和酒见第 2 节第 3、16、24 条（不喝含糖饮料、少喝或不喝酒、不喝甜味饮料）","money":"少","time":"少","will":"是","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"}]},{"n":17,"title":"家里有老人","intro":"口径：金钱与人身自由。多数麻烦不是钱不够，是没提前把话说清、把字签好。末一条（长期卧床的压疮）按死亡率算，不与本节其他条目比较。","entries":[{"id":"17.1","sec":17,"n":1,"title":"趁老人清醒，书面指定将来的监护人","cost":"公证几百元；谈一次话","human":"趁老人还清醒，花几百元公证一份书面文件，定好将来谁当监护人。没有这份文件，等到老人不能自己做决定时，谁替他签字、谁管他的钱要走法院指定，家里意见不一致会拖更久。","gain":"民法典规定，具有完全民事行为能力的成年人，可以与近亲属或其他愿意担任监护人的个人、组织事先协商，「以书面形式确定自己的监护人」，在丧失或者部分丧失民事行为能力时由该监护人履行职责。没有这份文件，将来谁来签字、谁来管钱要走法院指定","grade":"A","src":"全国人大 (2020). 民法典（第三十三条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>","note":"这叫意定监护，效力优先于法定监护顺序。独居、子女在外地、家庭关系复杂的更需要。建议做公证","money":"少","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"17.2","sec":17,"n":2,"title":"把遗嘱立了，记住后立的推翻先立的，公证遗嘱不再优先","cost":"自书遗嘱 0 元；公证几百到上千元","human":"六种遗嘱形式法律都认，但形式错了整份作废，这是最常见的翻车点：自书遗嘱必须本人全文手写、签名、写上年月日；打印的要两个以上见证人，遗嘱人和见证人每页都签名并注明年月日，继承人、受遗赠人及其近亲属不能当见证人。立了几份互相打架的，以最后那份为准，2021 年起公证的那份也不再自动优先。","gain":"民法典认可自书、代书、打印、录音录像、口头、公证六种遗嘱形式，各有形式要件；立有数份内容相抵触的遗嘱的，以最后的遗嘱为准，2021 年起公证遗嘱不再具有优先效力","grade":"A","src":"全国人大 (2020). 民法典（第一千一百三十四条至第一千一百四十二条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>","note":"自书遗嘱必须本人全文手写并签名、注明年月日；打印遗嘱要有两个以上见证人，遗嘱人和见证人在每一页签名并注明年月日。继承人、受遗赠人及其近亲属不能当见证人。形式错了整份无效，这是最常见的翻车点","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"17.3","sec":17,"n":3,"title":"老人的钱单独放一个账户，大额支出定一个双人确认的规矩","cost":"0 元","human":"针对老人的保健品、收藏品、理财骗局，套路都是先花几个月建立信任再一次性收割。事先约好「超过多少钱的支出先跟某个人说一声」，等于把掏钱那一刻拖过冲动期。这件事说成「家里的钱统一记账」比说「怕你被骗」容易被接受。","gain":"针对老人的保健品、收藏品、理财骗局，套路都是拉长战线建立信任后一次性收割。事先约好「超过多少钱的支出要先和某个人说一声」，把决策拖过冲动期","grade":"C","src":"作者经验，无直接文献；防骗通则见第 8 节和第 13 节","note":"别把这件事讲成「怕你被骗」，讲成「家里的钱统一记账」更容易被接受。也别把老人的所有钱都交给子女保管，那会引出另一类纠纷","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"17.4","sec":17,"n":4,"title":"给老人一句可以随时说出口的挡箭牌话术","cost":"0 元","human":"推销和诈骗吃的是现场压力。事先商量好一句「我要回去和家里人商量」，让老人当场有台阶可下，比事后跟他讲道理管用。","gain":"推销和诈骗都靠现场施压。事先商量好一句「我要回去和家里人商量」，让老人有台阶可下，比事后讲道理有效","grade":"C","src":"作者经验，无直接文献","note":"配合上一条使用。同时把家里的防跌倒改造做了，见第 1 节。这句话不是用来防着老人的，是给他一个不用当场硬顶的台阶——被推销围住时最难的从来不是判断真假，而是在一屋子人面前开口拒绝；事先约好这句话，等于替他把这一关接过来","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"17.5","sec":17,"n":5,"title":"凡是让老人先交钱的「投资养老」都别碰：办卡、买床位、买养老公寓、旅居养老、买老年产品是同一套非法集资","cost":"0 元；把下面这几种名目念给老人听一遍，遇到直接拒绝，不去听课、不去参观、不留电话","human":"凡是让老人先交钱、又承诺回报的养老名目——办贵宾卡会员卡、预交养老服务费、买床位、入股养生养老基地、买养老公寓、旅居养老、会销卖老年产品——都是同一套。钱按规定追不回来，参与非法集资的损失由参与人自己承担。看官方通报的量级：有人用预定养老公寓床位的名义收走 1.36 亿元、2100 多名被害人；另一起打投资养老产业旗号的收了 132.07 亿元、涉及 11 万多人。能拦住的只有掏钱那一步。","gain":"民政部列的五种表现形式，认名目比认人可靠：假借养老服务机构之名（没有实体，临时租场地、宣称与养老机构签了合作协议来「碰瓷」）；以提供「养老服务」为名（「贵宾卡」「会员卡」「预付卡」、预交「养老服务费用」，明显超过床位供给能力承诺服务）；以投资「养老项目」为名（入股养生养老基地、销售虚构的养老公寓、长期出租养老床位、「时间银行」互助养老，用返本销售、售后返租、约定回购做幌子）；以销售「老年产品」为名（商品回购、寄存代售、消费返利、免费体检、赠送礼品、会议营销、养生讲座、专家义诊）；以享受「旅居养老」为名（低价或免费旅游、储值返利、积分养老）。钱追不回来是写在制度里的：防范和处置非法集资条例第二十五条「因参与非法集资受到的损失，由集资参与人自行承担」。量级看官方通报的案子：戴某平等人以预定养老公寓床位名义非法集资 1.36 亿元、被害人 2100 余人，戴某平以集资诈骗罪判 15 年并处罚金 40 万元；曹某铭以投资养老产业为名集资诈骗 132.07 亿元、11 万余人，判无期徒刑、剥夺政治权利终身、没收个人全部财产；保健品会销走的是诈骗罪，倪某荣用免费宴请、赠送礼品、专车接送把老年人拉去听课，讲师用「虚假人设、虚假案例、虚高砍价」编造防癌抗癌功效，诱骗以成本价数十倍买「二氢槲皮素」，销售金额 62 万余元，判 10 年 3 个月并处罚金 12 万元（全国，条例 2021 年 5 月 1 日起施行）","grade":"A","src":"民政部 (2023). 关于养老服务领域非法集资的风险提示. <https://www.gov.cn/lianbo/bumen/202306/content_6886556.htm>（中国政府网发布）；民政部、中国银保监会 (2021). 关于养老领域非法集资的风险提示. <https://www.mca.gov.cn/n152/n164/c36171/content.html>；国务院 (2021). 防范和处置非法集资条例（国务院令第 737 号，第二、二十五、三十条）. <https://www.gov.cn/zhengce/zhengceku/2021-02/10/content_5586632.htm>；最高人民检察院 (2022). 检察机关打击整治养老诈骗犯罪典型案例. <https://www.spp.gov.cn/xwfbh/wsfbt/202206/t20220617_560010.shtml>；最高人民法院 (2025). 依法惩治涉民生领域诈骗犯罪典型案例（案例五 倪某荣诈骗案）. <https://www.court.gov.cn/zixun/xiangqing/482861.html>","note":"判断不靠「这家看着正规」，靠「有没有让你先交钱、有没有承诺回报」——养老机构的本质是提供服务，一带投资返利性质的承诺就出局。老人被拉去听课、旅游、义诊本身不违法，也很难拦，能拦的是掏钱那一步，配合第 3 条的双人确认规矩用。已经交了钱就立刻按第 8 节第 2 条打 110 或 96110 要求止付，同时向当地处置非法集资牵头部门举报。以房养老是另一套路径，见下一条。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"17.6","sec":17,"n":6,"title":"除了保险公司的住房反向抵押养老保险，其他「以房养老」都别碰，绝不抵押房子去买理财","cost":"0 元；家里的房产证不交给任何以「以房养老」名义上门的人，任何抵押、担保、借贷协议签字前先给子女看","human":"正规的以房养老只有保险公司的住房反向抵押养老保险一种，目前还在试点、比较小众。上门推销的那种「以房养老」和国家试点完全无关：诱骗老人把房子抵押出去，拿借来的钱买它推荐的理财，本质是拿新钱还旧钱。监管的原话是，有人甚至不知道自己的房产被抵押，最终房子没了还背着贷款。理财承诺收益超过 6% 就要打问号，超过 8% 很危险，10% 以上要准备损失全部本金。","gain":"银保监会消保局把真假两种说清楚了：正规的以房养老只有一种，即「老年人住房反向抵押养老保险」，拥有房屋完全合法产权的老年人把房产抵押给保险公司，继续拥有占有、使用、收益和经抵押权人同意的处置权，按约定条件领取养老金直至身故，目前仍处于试点阶段且比较小众；不法分子说的「以房养老」与国家试行的住房反向抵押养老保险「完全无关」，是「假借国家政策、为非法集资活动造势宣传的手段」，操作是诱骗老人办房产抵押、再把借来的钱去买它推荐的理财产品，「往往是『以新还旧』的庞氏骗局」，后果原文写的是「有的参与人甚至都不知道自己的房产被抵押，最终失去了房子，还背负贷款」；给出的收益率判断线是「理财产品如果承诺收益率超过 6% 就要打问号，超过 8% 就很危险，10% 以上就要准备损失全部本金，『保本高收益』就是金融诈骗」；同一份提示还要求「慎重对待合同签署环节，不在空白合同签字」（全国，2021 年 6 月）","grade":"B","src":"中国银保监会消费者权益保护局 (2021). 关于警惕「投资养老」「以房养老」金融诈骗的风险提示（2021 年第三期）. <https://dfjrjgj.hunan.gov.cn/dfjrjgj/yhlj/202106/t20210608_19450856.html>（湖南省地方金融监督管理局转载）；民政部、中国银保监会 (2021). 关于养老领域非法集资的风险提示（第四种表现形式：以宣称「以房养老」为名非法集资）. <https://www.mca.gov.cn/n152/n164/c36171/content.html>","note":"B 级原因是这是监管部门的风险提示口径和经验阈值，不是研究数据；6%、8%、10% 三条线是监管给消费者的判断参考，不是法定标准。银保监会已并入国家金融监督管理总局，原发布页不可达，引省级金融监管局转载页。这条的要害不在「理财亏了」，在于房子被抵押出去以后老人还欠着贷款，损失远大于本金。签字与空白合同的一般规则见第 8 节第 15 条，被骗后止付见第 8 节第 2 条。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"17.7","sec":17,"n":7,"title":"家里老人长期卧床或重度失能，去参保地医保部门申请长期护理保险","cost":"申请加一次失能等级评估；首次评估通过的评估费由基金支付","human":"老人重度失能、这个状态持续半年以上的，去参保地医保部门申请长期护理保险：符合规定的护理费不设起付线，按职工政策参保的报销七成左右，按城乡居民政策参保的五成左右，一年最多报到当地上年度居民人均可支配收入的一半。首次评估通过的评估费由基金出；床位费、伙食费这类不在报销范围里。","gain":"符合规定的长期护理服务费用不设起付线，按单位职工政策参保的基金支付约 70%，按未就业城乡居民政策参保的约 50%；年度最高支付限额不超过统筹地区上年度城乡居民人均可支配收入的 50%","grade":"A","src":"国家医保局等八部门 (2026). 关于印发《加快建立长期护理保险制度实施方案》的通知. <https://www.gov.cn/zhengce/zhengceku/202603/content_7063915.htm>：保障对象为「按规定参保缴费且失能状态长期持续（一般为6个月以上），经申请通过评估认定的失能人员」，「制度起步阶段保障重度失能人员」；「待遇享受不设起付标准。符合规定的长期护理服务费用，按未就业城乡居民参保政策参保的，基金支付比例为50%左右；按单位职工参保政策参保的，基金支付比例为70%左右，退休人员享受单位职工参保待遇」；「参保人员基金年度最高支付限额不超过统筹地区上年度城乡居民人均可支配收入的50%」；「待遇享受固定等待期原则上按照6个月设置」；另见中共中央办公厅、国务院办公厅《关于加快建立长期护理保险制度的意见》. <https://www.gov.cn/gongbao/2026/issue_12666/202604/content_7065119.html>","note":"失能要「长期持续（一般为6个月以上）」，不是住院几周就能申请。床位费、膳食费这类非护理费用和该由医保付的医疗费，长护险不付；已经在领工伤生活护理费的不重复享受。居家和社区护理在支付比例上有倾斜，不一定非要住机构。制度在各地分批落地，先打参保地医保经办机构问本地有没有启动、评估怎么约。","money":"0","time":"中","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"17.8","sec":17,"n":8,"title":"家里有人长期卧床，把压疮当头号敌人：上电动气垫床、定时翻身、每天看一遍骨头突出的地方","cost":"家用电动交替压力气垫床几百元起；翻身一次只要几分钟，难的是每隔两三小时一次、夜里也不停，一个人扛不下来","human":"压疮不是多一块皮外伤。19520 例髋部骨折手术的病历里，术前就带着压疮的人 30 天内死亡的可能性高约两成，深静脉血栓高约六成、肺炎高约四成、非计划再住院高约四成；324 名住院老人随访一年半，有压疮的人死亡风险高约五成。能做的三件事都有证据：电动气垫床比普通病床床垫的新发压疮低约六成；把翻身真正落实（那项试验用的是可穿戴传感器提醒）比常规护理低约七成；别让人长时间趴着，俯卧位的压疮比仰卧位多。至于「两小时还是四小时翻一次」，11 项试验 4462 人的综述结论是非常不确定——要抓的是有没有真的翻，不是掐钟点。骶尾、足跟、髋部、肩背每天看一遍，发现压不褪的红，当天找护士或医生。","gain":"19520 例髋部骨折手术患者（美国 NSQIP 2016 至 2019 年）：术前存在压疮与 30 天死亡率升高独立相关（OR 1.2，几率增加 21%，P=0.004），并与深静脉血栓（OR 1.59）、肺炎（OR 1.39）、非计划再住院（OR 1.43）及平均住院日延长 0.4 天相关。324 名住院老人（平均 86 岁）中位 18 个月随访：压疮是长期死亡的独立预测因素（HR 1.500，95% CI 1.059 至 2.126，P=0.020）。65 项随机试验的网络荟萃分析：与标准病床支撑面相比，电动主动气流支撑面使压疮发生率下降（RR 0.42，95% CI 0.29 至 0.63，中等确定性），电动混合气流支撑面 RR 0.22（0.07 至 0.66）。11 项试验 4462 人的 Cochrane 综述（2026 年更新）：2 小时与 4 小时翻身间隔的比较 RR 1.05（95% CI 0.79 至 1.39，确定性极低），间隔之间的其他比较同样极不确定；1226 名 ICU 患者的试验中，用可穿戴传感器实时提醒并给出视觉警示以落实 2 小时翻身，压疮发生率低于常规护理（RR 0.28，95% CI 0.10 至 0.75，中等确定性）；116 人的试验中俯卧位组压疮发生率高于仰卧位（RR 4.55，95% CI 2.31 至 8.98）","grade":"B","src":"Porter SB, Pla R, Chow JH, et al. (2022). Preoperative Pressure Ulcers, Mortality, and Complications in Older Hip Fracture Surgery Patients. JAAOS Global Research & Reviews, 6(11). <https://doi.org/10.5435/JAAOSGlobal-D-22-00117>；Ottaviani S, Rondanina E, Longo E, 等 (2026). Impact of pressure ulcers and frailty on long-term mortality: a prospective cohort study of hospitalized older adults. European Geriatric Medicine, 17(2), 665-672. <https://doi.org/10.1007/s41999-025-01331-8>；Shi C, Dumville JC, Cullum N (2018). Support surfaces for pressure ulcer prevention: A network meta-analysis. PLoS ONE, 13(2), e0192707. <https://doi.org/10.1371/journal.pone.0192707>；Latimer SL, Chaboyer WP, Probst S, 等 (2026). Repositioning for pressure injury prevention in adults. Cochrane Database of Systematic Reviews, 6, CD009958. <https://doi.org/10.1002/14651858.CD009958.pub4>","note":"给 B 的原因：死亡率那两项是观察性关联，说明的是「有压疮的人处境更差」，不等于「防住压疮就能把死亡率降下来」；翻身间隔的随机证据确定性极低；气垫床那条是中等确定性，但原文比较的是医院的标准支撑面，用到家用床垫上属于外推。每天查骶尾、足跟、髋部、肩背和「压下去不褪色的红」是常规护理做法，没有单列文献。这条的口径按死亡率算，和本节其他条目的金钱口径不做比较。长期护理保险能报的照护服务见本节第 7 条，突然一条腿肿起来按深静脉血栓处理见第 13 节第 10 条，因坠落或重伤长期卧床的那一段见第 1 节第 32 条","money":"少","time":"多","will":"是","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"}]},{"n":18,"title":"养孩子划不划算","intro":"口径：金钱与时间。和第 10 节一样，这里只拆账，不给结论。已经怀孕、要按流程办事的，见第 27 节。","entries":[{"id":"18.1","sec":18,"n":1,"title":"先把能领的算进来：国家育儿补贴每孩每年 3600 元，发到 3 岁","cost":"0 元；在孩子户籍地申请","human":"孩子 2025 年 1 月 1 日以后出生、不满 3 周岁的，父母一方去孩子户口所在地申请，每个孩子每年能领 3600 元，三年合计 10800 元。这笔钱不用交个税，认定低保等救助时也不算进家庭收入。","gain":"中办、国办印发的方案：对 2025 年 1 月 1 日起出生、3 周岁以下的婴幼儿，按「每孩每年 3600 元」发放，由婴幼儿的父母一方或其他监护人申领；该补贴「免征个人所得税」，且在认定低保等救助时「不计入家庭或个人收入」","grade":"A","src":"中共中央办公厅、国务院办公厅 (2025). 育儿补贴制度实施方案. <https://www.gov.cn/gongbao/2025/issue_12206/202508/content_7035435.html>","note":"这是全国统一的最低线，部分省市另有地方补贴，可以叠加。三年合计 10800 元，只是育儿开支里很小的一块，别当作决策依据","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"18.2","sec":18,"n":2,"title":"产假 98 天，生育津贴由生育保险基金按单位上年度职工月平均工资发","cost":"0 元；由单位申报","human":"生孩子至少能休 98 天产假，产前可以先休 15 天，难产或者每多生一个孩子各再加 15 天。这段时间的工资叫生育津贴，由生育保险基金按单位上年度职工月平均工资发；单位没给你参保的，就由单位按你产假前的工资标准发。加上各省的生育奖励假，各省另有生育奖励假，天数看本省条例。","gain":"国务院规定：「女职工生育享受 98 天产假，其中产前可以休假 15 天；难产的，增加产假 15 天；生育多胞胎的，每多生育 1 个婴儿，增加产假 15 天。」产假期间的生育津贴，已参加生育保险的「按照用人单位上年度职工月平均工资的标准由生育保险基金支付」；未参保的由用人单位按产假前工资标准支付","grade":"A","src":"国务院 (2012). 女职工劳动保护特别规定（国令第 619 号，第七条、第八条）. <https://www.gov.cn/zhengce/zhengceku/2012-05/07/content_6584.htm>","note":"98 天是国家最低标准，各省的人口与计划生育条例普遍再加 60 天以上的生育奖励假，加起来通常 158 天起。奖励假期间的工资由哪一方出，各省规定不同","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"18.3","sec":18,"n":3,"title":"知道这条：不得因怀孕、生育、哺乳降工资或者辞退","cost":"0 元","human":"怀孕、生育、哺乳期间被降工资或者被辞退是违法的，单位会被按每人 1000 到 5000 元罚款。孩子不满周岁的，每天有 1 小时哺乳时间，单位也不能安排你加班和上夜班。调岗降薪的书面通知和聊天记录留着，索赔路径见第 19 节。","gain":"国务院规定：「用人单位不得因女职工怀孕、生育、哺乳降低其工资、予以辞退、与其解除劳动或者聘用合同。」哺乳未满 1 周岁婴儿的，每天有 1 小时哺乳时间，且不得安排延长劳动时间和夜班；违反的，按每人 1000 元以上 5000 元以下罚款","grade":"A","src":"国务院 (2012). 女职工劳动保护特别规定（国令第 619 号，第五条、第九条、第十三条）. <https://www.gov.cn/zhengce/zhengceku/2012-05/07/content_6584.htm>","note":"真被违法解除的，索赔路径见第 19 节。取证重点是调岗降薪的书面通知和聊天记录","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"18.4","sec":18,"n":4,"title":"时间账按「谁的时间被占掉」算，不按「辛不辛苦」算","cost":"3 岁前基本是全天占用","human":"把每天照看孩子的小时数、夜里被吵醒的次数折成时间，再乘上承担这些事的人的时薪，得到的数一般远大于奶粉尿布钱。3 岁前基本是全天占用，所以值得在生之前对着同一张表把分工谈完，而不是生完再吵。","gain":"把每天的照料时间、夜间中断次数折算成小时，再乘以承担方的时薪，得到的数字通常远大于奶粉尿布钱。第 10 节讲的无酬劳动口径同样适用，先谈分工再决定","grade":"C","src":"作者经验，无直接文献；口径见第 10 节","note":"关键不是算出一个准确数字，是让两个人在生之前对着同一张表谈分工，而不是生完再吵","money":"0","time":"多","will":"是","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"18.5","sec":18,"n":5,"title":"钱账分三段算：0 到 3 岁、义务教育、义务教育之后","cost":"视城市和选择差别极大","human":"0 到 3 岁的钱主要花在怎么带（自己带、老人带、还是请人带），义务教育阶段主要花在住房和课外，之后主要花在升学路径上——三段的花法完全不同，混在一起只会算出一个吓人的总数。先把育儿补贴、生育津贴、医保报销这些确定能进的钱算进来，再看缺口有多大。","gain":"0 到 3 岁的大头是照料方式（自己带、老人带、请人带）；义务教育阶段的大头是住房和课外支出；之后的大头是升学路径。三段的成本结构完全不同，混在一起算只会得到一个吓人的总数","grade":"C","src":"作者经验，无直接文献","note":"先把补贴、生育津贴、医保报销这些确定的进项算进来，再算缺口。别用网上流传的「养大一个孩子要多少万」做决策，那类数字口径不明","money":"多","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"18.6","sec":18,"n":6,"title":"为长辈生、为婚姻生、为养老生，各记一笔账","cost":"0 元；一次认真的对话","human":"别人希望你生，这可以是你的一个考虑因素，但时间和钱是记在你自己账上的。「养儿防老」要单独算，因为它赌的是二十年后另一个人的经济能力和意愿。把不生的后果也写下来两边对照，只写一边不叫算账。","gain":"和第 10 节的思路一样：别人的期待可以是你的考虑因素，但成本要记在你自己的账上。「养儿防老」尤其要单独算，因为它假定的是二十年后的另一个人的经济能力和意愿","grade":"C","src":"作者经验，无直接文献；同类分析见第 10 节","note":"把「不生的后果」也写下来，两边对照。只写一边的账不叫算账","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"}]},{"n":19,"title":"在职、离职和工伤","intro":"口径：金钱。这一节只讲钱怎么算、字怎么签、期限怎么算。前三条是在职期间就该拿到的，中间六条是离职，最后七条是职业病与工伤——工伤的钱比裁员大一个量级，期限也更硬，职业病的损伤则根本换不回来。","entries":[{"id":"19.1","sec":19,"n":1,"title":"加班费按 1.5 倍、2 倍、3 倍三档算，不给就投诉劳动监察，逾期不付还要加付 50% 到 100%","cost":"0 元；平时把打卡记录、排班表、加班审批单和工作群里的派活记录自己存一份","human":"平时加班按工资的 1.5 倍算，休息日加班又没安排补休按 2 倍，元旦春节劳动节国庆这类法定假日上班按 3 倍、而且不能拿补休顶掉。加班每天一般不超过 1 小时、有特殊原因最多 3 小时，每月不超过 36 小时。不给钱可以找劳动监察，责令限期支付后仍不给的，单位还要另加付欠款的一半到一倍。","gain":"法定工时是每日不超过 8 小时、平均每周不超过 44 小时；延长工作时间一般每日不得超过 1 小时，因特殊原因需要延长的每日不得超过 3 小时且每月不得超过 36 小时。三档加班费：安排延长工作时间的，支付不低于工资的 150%；休息日安排工作又不能安排补休的，不低于 200%；法定休假日安排工作的，不低于 300%——法定休假日这一档法条里没有「补休替代」的选项。单位安排加班不支付加班费的，由劳动行政部门责令限期支付；逾期不支付的，责令按应付金额 50% 以上 100% 以下的标准向劳动者加付赔偿金（全国）","grade":"A","src":"全国人大常委会 (2018). 劳动法（2018 年第二次修正，第三十六、四十一、四十三、四十四条）. <https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/bgt/art/2023/art_d9aa750028b14b99a776cb93726a360d.html>（国家市场监督管理总局刊登）；全国人大常委会 (2007). 劳动合同法（第八十五条第三项）. <http://www.gov.cn/gongbao/content/2007/content_711013.htm>","note":"休息日和法定休假日不是一回事：法定休假日全年只有元旦、春节、劳动节、国庆节等法定的那几天，调休凑出来的连休日按休息日算 200%。「公司规定加班要审批」「我是自愿留下的」不能一概免除支付义务，但会影响举证，所以派活和审批记录要留。综合计算工时制、不定时工时制要经劳动行政部门批准才能实行，不是公司自己说了算。争议的仲裁时效见第 8 节第 17 条。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"19.2","sec":19,"n":2,"title":"年休假按累计工龄算 5、10、15 天，没休成的按日工资 300% 折钱","cost":"0 元；把自己在所有单位的工作年限理清楚，社保缴费记录就是证明","human":"在所有单位的工龄加起来满 1 年不满 10 年，每年 5 天年休假，满 10 年 10 天，满 20 年 15 天，换过工作也照样累计。单位安排不了、你又同意不休的，那几天按日工资的 3 倍给钱，扣掉本来就有的那一份等于多拿 2 倍；日工资是月工资除以 21.75。「自愿放弃年休假」的表一签，就只剩正常工资了。","gain":"连续工作满 12 个月就享受年休假；天数按**累计**工作时间定，满 1 年不满 10 年 5 天，满 10 年不满 20 年 10 天，满 20 年 15 天，国家法定休假日和休息日不计入年休假假期。单位确因工作需要不能安排、并经本人同意不休的，对应休未休天数「按照该职工日工资收入的 300% 支付年休假工资报酬」，这 300% 里含了正常工作期间那一份，所以实际额外多拿 200%。日工资 = 本人月工资 ÷ 21.75，月工资按支付前 12 个月剔除加班工资后的月平均工资算。当年新入职的按在本单位剩余日历天数折算；离职时按当年已工作时间折算并支付，已经多休的不扣回。单位不安排又不给钱的，责令限期改正，逾期不改的还要按未休年休假工资报酬的数额加付赔偿金（全国，2008 年 1 月 1 日起施行）","grade":"A","src":"国务院 (2007). 职工带薪年休假条例（国务院令第 514 号，第二、三、四、五、七条）. <http://www.gov.cn/gongbao/content/2008/content_859865.htm>；人力资源和社会保障部 (2008). 企业职工带薪年休假实施办法（人社部令第 1 号，第三、四、五、十、十一、十二、十五条）. <http://www.gov.cn/gongbao/content/2009/content_1265995.htm>","note":"累计工作时间跨单位累计，不是「在这家干满多久」，换过工作的别按现单位工龄算。**只有职工「因本人原因且书面提出不休」，单位才可以只支付正常工资**——所以「自愿放弃年休假」的表别签。请事假累计 20 天以上且单位不扣工资的，或者病假超过对应月数（工龄不满 10 年 2 个月、10 到 20 年 3 个月、20 年以上 4 个月）的，当年不享受年休假。探亲假、婚丧假、产假和工伤停工留薪期不计入年休假。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"19.3","sec":19,"n":3,"title":"试用期有法定上限、工资不得低于 80%，而且只能约定一次","cost":"0 元；签字前把合同期限和试用期长度对一遍","human":"合同签 1 年以内的试用期最多 1 个月，1 到 3 年最多 2 个月，3 年以上最多 6 个月；同一家公司只能试用你一次，转正后调岗再来一次是违法的。试用期工资不能低于同岗位最低档或者合同约定工资的 80%，也不能低于当地最低工资。超出法定长度的那段时间，单位要按你试用期满的月工资标准另外赔钱。","gain":"合同期限 3 个月以上不满 1 年的，试用期不得超过 1 个月；1 年以上不满 3 年的不得超过 2 个月；3 年以上固定期限和无固定期限的不得超过 6 个月；以完成一定工作任务为期限的合同或者期限不满 3 个月的合同，不得约定试用期；「同一用人单位与同一劳动者只能约定一次试用期」；只约定试用期的，试用期不成立，该期限就是劳动合同期限。试用期工资「不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准」。违法约定的试用期已经履行的，用人单位要以劳动者试用期满月工资为标准，按已经履行的超过法定试用期的期间支付赔偿金。试用期内单位要解除合同，只能依法定情形，并且应当向劳动者说明理由（全国）","grade":"A","src":"全国人大常委会 (2007). 劳动合同法（第十九、二十、二十一、八十三条）. <http://www.gov.cn/gongbao/content/2007/content_711013.htm>","note":"最常见的三种违法：合同只签 1 年却约定 3 个月试用期；转正之后调岗再来一次试用期；「试用期不交社保」——社保义务从用工之日起算，和试不试用无关，用人一侧的义务见第 12 节第 12 条。试用期被辞退不等于一分钱没有，要看单位援引的是不是法定情形；被违法解除的按第 6 条算 2N。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"19.4","sec":19,"n":4,"title":"被裁先算清 N：每满一年一个月工资，不满六个月按半个月","cost":"0 元；算一次十分钟","human":"被裁的经济补偿是干满一年给一个月工资，满半年不满一年按一年算，不满半年给半个月。这里的月工资是走人前 12 个月的平均数，奖金、津贴、补贴都要算进去，公司最常在这一项上做低。工资高过当地上年度月平均工资 3 倍的按 3 倍封顶，年限最多算 12 年。","gain":"劳动合同法规定的经济补偿标准：「每满一年支付一个月工资……六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资」；月工资高于当地上年度职工月平均工资三倍的，按三倍计，且年限最高不超过十二年","grade":"A","src":"全国人大常委会 (2007). 中华人民共和国劳动合同法（2008 年 1 月 1 日施行）（第四十七条）. <http://www.gov.cn/gongbao/content/2007/content_711013.htm>","note":"月工资指劳动合同解除前十二个月的平均工资，包含奖金、津贴和补贴，不是只算基本工资。这一点最容易被公司做低","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"19.5","sec":19,"n":5,"title":"公司没提前 30 天通知，还要多付一个月工资","cost":"0 元","human":"公司没有提前 30 天书面通知就让你走，要在 N 之外再多给一个月工资，这就是常说的 N+1。谈的时候把这一个月单独列出来，别让公司把它算进 N 里面。","gain":"劳动合同法规定，用人单位依该条解除劳动合同的，应当「提前三十日以书面形式通知劳动者本人或者额外支付劳动者一个月工资后，可以解除劳动合同」。这多出来的一个月俗称代通知金，是 N 之外的钱","grade":"A","src":"全国人大常委会 (2007). 中华人民共和国劳动合同法（2008 年 1 月 1 日施行）（第四十条）. <http://www.gov.cn/gongbao/content/2007/content_711013.htm>","note":"所以合法裁员的常见结果是 N+1。谈判时把 N 和 1 分开算，别让公司把代通知金算进 N 里","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"19.6","sec":19,"n":6,"title":"公司违法解除的，赔偿金是经济补偿标准的二倍","cost":"0 元；走仲裁要几个月","human":"公司属于违法解除的，赔偿金按经济补偿的标准翻倍，也就是常说的 2N。是不是违法解除要看具体情形，先找法律援助或者律师问清楚，再决定是谈还是去仲裁。","gain":"劳动合同法规定，用人单位违反本法规定解除或者终止劳动合同的，「应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金」","grade":"A","src":"全国人大常委会 (2007). 中华人民共和国劳动合同法（2008 年 1 月 1 日施行）（第八十七条）. <http://www.gov.cn/gongbao/content/2007/content_711013.htm>","note":"这就是俗称的 2N。什么算违法解除要看具体情形，先咨询法律援助或律师再决定谈还是仲裁，路径见第 7 节","money":"0","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"19.7","sec":19,"n":7,"title":"不要签「个人原因主动辞职」，那一签就没有 N 了","cost":"0 元；顶住当场签字的压力","human":"签字承认「个人原因主动辞职」，经济补偿和失业保险金通常一起落空——自己提出离职本来就不在给补偿的情形里（公司欠薪、不缴社保这类过错除外）。「先签了好走流程，补偿另外给」这种话要就当场写进协议，不写就不签；不必当天签，冷静一晚再说。","gain":"劳动合同法把支付经济补偿的情形限定在法定几类里，劳动者自己提出解除（除非是因为公司欠薪、不缴社保等法定过错）不在其中。签了「主动辞职」，经济补偿和失业保险金通常一起落空","grade":"B","src":"全国人大常委会 (2007). 中华人民共和国劳动合同法（2008 年 1 月 1 日施行）（第三十八条、第四十六条）. <http://www.gov.cn/gongbao/content/2007/content_711013.htm>","note":"公司常用的话术是「先签了好走流程，补偿另外给」。要就当场写进协议，不写就不签。当天不签不会有任何法律后果，冷静一晚再说","money":"0","time":"少","will":"是","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"19.8","sec":19,"n":8,"title":"离职前把工资条、考勤、劳动合同、社保记录和聊天记录先存下来","cost":"0 元；半小时","human":"电脑和账号一交回去，工资条、考勤、合同、社保记录和聊天记录就再也拿不到了。仲裁时工资标准、加班事实这些还是要靠你自己手上的材料。存的是自己的劳动关系材料，公司的源码和客户名单不要带走，那是另一回事。","gain":"一旦交回电脑和账号，这些材料就再也拿不到了。仲裁时举证责任虽有倾斜，但工资标准、加班事实这些还是要靠你自己的证据","grade":"C","src":"作者经验，无直接文献；维权路径见第 7 节","note":"存的是自己的劳动关系材料，不要顺手带走公司的源码、客户名单和技术文档，那是另一回事，见第 11 节","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"19.9","sec":19,"n":9,"title":"走人之后立刻办两件事：失业登记领失业保险金，看清竞业协议","cost":"0 元","human":"走人之后马上办两件事：去做失业登记领失业保险金，以及把竞业协议看一遍。两件事都有时间窗，拖过去就作废。失业保险金只有非因本人意愿中断就业才能领，这也是上一条不签「主动辞职」的原因之一。","gain":"失业保险金和就业补贴的申领方式见第 7 节；竞业限制的补偿标准、解除条件见第 11 节。这两件事都有时间窗，拖着就作废","grade":"C","src":"作者经验，无直接文献；具体依据见第 7 节和第 11 节","note":"非因本人意愿中断就业才能领失业保险金，这也是上面那条不签「主动辞职」的原因之一","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"19.10","sec":19,"n":10,"title":"进有粉尘、噪声、化学品的岗位之前，先看合同里写没写危害；三次职业健康检查由单位安排并掏钱","cost":"0 元；签合同时把「职业病危害告知」那部分逐条看完，每次体检报告要一份自己留着","human":"签合同时单位必须把这个岗位有什么职业病危害、怎么防护、有什么待遇如实写进合同，不能瞒也不能骗；瞒了你就有权拒绝干这个活，单位不能因此辞退你。上岗前、在岗期间、离岗时三次职业健康检查由单位安排并掏钱，结果要书面告诉你。没做离岗体检，单位不能和你解除或终止合同；离职时可以免费索取本人职业健康监护档案复印件，这是日后申请职业病诊断的关键材料。","gain":"职业病防治法：订立劳动合同时，用人单位应当把工作过程中可能产生的职业病危害及其后果、防护措施和待遇「如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗」；已订合同期间因调岗从事合同里没告知过的有害作业的，要重新如实告知并协商变更条款；单位违反的，「劳动者有权拒绝从事存在职业病危害的作业，用人单位不得因此解除与劳动者所订立的劳动合同」。体检是三次——上岗前、在岗期间、离岗时，「职业健康检查费用由用人单位承担」，结果应当书面告知本人；单位不得安排未经上岗前职业健康检查的人从事接触职业病危害的作业，不得安排有职业禁忌的人从事禁忌作业，查出与所从事职业相关的健康损害的应当调离原岗位并妥善安置；**「对未进行离岗前职业健康检查的劳动者不得解除或者终止与其订立的劳动合同」**。离职时你「有权索取本人职业健康监护档案复印件，用人单位应当如实、无偿提供，并在所提供的复印件上签章」（全国）","grade":"A","src":"全国人大常委会 (2018). 职业病防治法（2018 年修正，第三十三、三十五、三十六条）. <https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/201711/t20171104_779851.html>（北京市人民政府转载）","note":"面试时问三句就能大致判断这家正不正规：这个岗位有没有职业病危害、合同里写不写、上岗前体检谁出钱。答不上来或者「先干着再说」的，风险自己掂量。离岗体检那一条是最容易被忽略的护身符：没做离岗体检，单位不能和你解除或终止劳动合同，而这份体检是日后申请职业病诊断的关键材料，档案复印件同理，走之前一定要拿到手。职业病本身按工伤走，待遇见第 12 条起。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"19.11","sec":19,"n":11,"title":"粉尘、噪声、化学毒物造成的损伤不可逆：防护用品单位必须给，没有防护措施的作业可以拒绝","cost":"0 元；坚持戴防颗粒物口罩、耳塞、护目镜，拒绝没有防护的活，代价是可能被同事说「事多」","human":"尘肺、噪声聋、化学性眼灼伤都写在法定职业病目录里，肺和听力一旦坏了没有能让它恢复的治疗。你有权知道岗位上有哪些危害、要求单位提供防护设施和个人防护用品，也有权拒绝违章指挥和没有防护措施的作业；单位因为你行使这些权利给你降薪或者辞退的，这些做法无效。挡粉尘要用单位按岗位配发的防护用品；噪声岗位单位不发耳塞就自己买，几元一副。","gain":"法定职业病自 2025 年 8 月 1 日起是 12 大类 135 种（含 4 项开放性条款），排在第一类的就是职业性尘肺病：矽肺、煤工尘肺、石墨尘肺、碳黑尘肺、石棉肺、滑石尘肺、水泥尘肺、云母尘肺、陶工尘肺、铝尘肺、电焊工尘肺、铸工尘肺，加一项开放条款；职业性耳鼻喉口腔疾病里有噪声聋和爆震聋；职业性眼病里有化学性眼部灼伤和电光性眼炎。这些损伤都是不可逆的，没有能让肺和听力恢复的治疗。法律给了四条可以当场引用的权利：了解工作场所产生或者可能产生的职业病危害因素、危害后果和应当采取的防护措施；要求用人单位提供符合防治职业病要求的防护设施和个人防护用品、改善工作条件；对违反职业病防治法律法规以及危及生命健康的行为提出批评、检举和控告；「拒绝违章指挥和强令进行没有职业病防护措施的作业」。并且「因劳动者依法行使正当权利而降低其工资、福利等待遇或者解除、终止与其订立的劳动合同的，其行为无效」（全国）","grade":"A","src":"国家卫生健康委、人力资源社会保障部、国家疾控局、全国总工会 (2024). 职业病分类和目录（2025 年 8 月 1 日起实施）. <https://www.gov.cn/zhengce/zhengceku/202412/content_6992843.htm>；新版目录 12 大类 135 种的口径见国家卫生健康委 (2024). 新版目录将职业病调整为 12 大类 135 种. <https://www.gov.cn/lianbo/bumen/202412/content_6992838.htm>；全国人大常委会 (2018). 职业病防治法（第三十九条）. <https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/201711/t20171104_779851.html>（北京市人民政府转载）","note":"口罩要认对，防颗粒物的口罩才挡粉尘，普通纱布口罩和一次性外科口罩不挡；噪声岗位单位不发耳塞就自己买，几元一副，听力掉了补不回来。「干两年攒够钱就走」在尘肺上不成立：矽肺可以在脱离粉尘作业多年之后才发病并继续进展，离岗体检因此格外重要（见第 10 条）。新版目录还新增了职业性肌肉骨骼疾病（腕管综合征，限于长时间腕部重复作业或用力作业的制造业工人）和职业性精神和行为障碍（创伤后应激障碍，限于参与突发事件处置的人民警察、医疗卫生人员、消防救援等应急救援人员）。化学品溅到身上的现场处理见第 13 节第 20 条。","money":"0","time":"少","will":"是","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"19.12","sec":19,"n":12,"title":"上班受伤、上下班路上被撞，第一件事是做工伤认定，单位不报你自己报","cost":"备三样材料跑一趟社保行政部门：工伤认定申请表、劳动关系证明、医疗诊断证明","human":"上班受伤，或者上下班路上被撞且主要责任不在你，都算工伤；但不做工伤认定，医药费、停工留薪期工资、伤残补助金就全部落空。单位应当在 30 天内申报，超时的这段时间的工伤待遇由单位自己掏；单位不报的，你或者家属、工会可以在一年内自己去社保行政部门报，一年过了就没得申请。单位说不是工伤的，举证责任在单位。","gain":"没有认定，医药费、停工留薪期工资、伤残补助金全部落空；单位超过 30 日不报，这期间的工伤待遇费用由单位自己掏","grade":"A","src":"国务院 (2010 修订). 工伤保险条例（国务院令第 586 号）第十四条列了七种「应当认定为工伤」，含「（六）在上下班途中，受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的」；第十七条「所在单位应当自事故伤害发生之日或者被诊断、鉴定为职业病之日起30日内，向统筹地区社会保险行政部门提出工伤认定申请」「用人单位未按前款规定提出工伤认定申请的，工伤职工或者其近亲属、工会组织在事故伤害发生之日或者被诊断、鉴定为职业病之日起1年内，可以直接向用人单位所在地统筹地区社会保险行政部门提出工伤认定申请」「用人单位未在本条第一款规定的时限内提交工伤认定申请，在此期间发生符合本条例规定的工伤待遇等有关费用由该用人单位负担」；第十九条「职工或者其近亲属认为是工伤，用人单位不认为是工伤的，由用人单位承担举证责任」；第二十条「自受理工伤认定申请之日起60日内作出工伤认定的决定」. <https://www.gov.cn/gongbao/content/2011/content_1778064.htm>","note":"1 年是硬期限，过了就没得申请。举证责任在单位不在你，但你自己也要留证：出事当天的照片、同事联系方式、就诊记录、考勤。第十六条列了三种不认的情形——故意犯罪、醉酒或者吸毒、自残或者自杀。第十五条另有「视同工伤」：在工作时间和工作岗位突发疾病死亡，或者 48 小时之内经抢救无效死亡的。","money":"0","time":"中","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"19.13","sec":19,"n":13,"title":"别信「撑到工位就算工伤」：突发不适先打 120，不是先赶去打卡","cost":"0 元","human":"突发不适往公司赶不会让你多拿一笔钱：视同工伤要求人在工作时间、又在工作岗位上发病，路上发病没到岗的本来就不算，抢救超过 48 小时反而也不算。为了凑条件耽误的那几十分钟，换掉的是自己的存活率。","gain":"条款要求「在工作时间和工作岗位」突发疾病死亡，或者在 48 小时之内经抢救无效死亡；为了凑条件耽误就医，是拿存活率去换一笔并不确定的赔偿","grade":"A","src":"工伤保险条例第十五条第一款第（一）项：「在工作时间和工作岗位，突发疾病死亡或者在48小时之内经抢救无效死亡的」视同工伤；第十四条第（六）项只把上下班途中「受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的」列为工伤，途中突发疾病不在其中. <https://www.gov.cn/gongbao/content/2011/content_1778064.htm>","note":"两个条件要同时满足：在工作时间，且在工作岗位。路上发病没到岗的不适用；在岗发病后被送回家或送医、48 小时内经抢救无效死亡的，仍可能适用——决定性的是发病时人在哪，不是最后死在哪。短视频把这条讲成「撑到公司就有钱」，方向正好反了：真正能改变结局的是发病后那几十分钟有没有去医院。另外 48 小时是一条硬线，抢救超过 48 小时反而不算。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"19.14","sec":19,"n":14,"title":"单位没给你交工伤保险，工伤待遇一样有，由单位按同样的标准全额出","cost":"单位不认就要走仲裁甚至诉讼，几个月起步","human":"单位没给你交工伤保险，工伤待遇一样有，只是改成由单位按同样的项目和标准全额支付，一分不少。没参保对单位是加罚——责令补缴、按日加收万分之五滞纳金、逾期还要处欠缴额 1 到 3 倍罚款，对你不是减赔。「公司没买工伤险所以赔不了」是假话。","gain":"条例明写：未参保单位的职工发生工伤，由该单位按条例规定的项目和标准支付费用——项目和标准与参了保的完全一样","grade":"A","src":"工伤保险条例第六十二条第二款：「依照本条例规定应当参加工伤保险而未参加工伤保险的用人单位职工发生工伤的，由该用人单位按照本条例规定的工伤保险待遇项目和标准支付费用。」同条第一款：责令限期参加、补缴，「自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，处欠缴数额1倍以上3倍以下的罚款」. <https://www.gov.cn/gongbao/content/2011/content_1778064.htm>","note":"「公司没给你买工伤险，所以赔不了」是这类事里最常见的一句假话。没参保对单位是加罚，对你不是减赔。","money":"0","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"19.15","sec":19,"n":15,"title":"伤情稳定后去做劳动能力鉴定，伤残等级直接换算成钱","cost":"走一次鉴定流程","human":"伤情稳定之后去做劳动能力鉴定，等级直接换算成钱：一次性伤残补助金按本人工资算，五级 18 个月、六级 16 个月、七级 13 个月、八级 11 个月、九级 9 个月、十级 7 个月。五、六级还保留劳动关系并按月拿伤残津贴。鉴定结果出来之前不要签「一次性了结」的协议。","gain":"一次性伤残补助金按等级折算成月工资：五级 18 个月、六级 16 个月、七级 13 个月、八级 11 个月、九级 9 个月、十级 7 个月的本人工资","grade":"A","src":"工伤保险条例第二十一条「经治疗伤情相对稳定后存在残疾、影响劳动能力的，应当进行劳动能力鉴定」；第二十二条「劳动功能障碍分为十个伤残等级，最重的为一级，最轻的为十级」；第三十六条五、六级待遇（一次性伤残补助金 18/16 个月本人工资，按月伤残津贴为本人工资的 70%/60%）；第三十七条七至十级待遇（13/11/9/7 个月本人工资）. <https://www.gov.cn/gongbao/content/2011/content_1778064.htm>","note":"五、六级保留劳动关系并有按月津贴；七到十级在合同期满或者本人提出解除时，另有一次性工伤医疗补助金（基金出）和一次性伤残就业补助金（单位出），具体标准由省级政府定。鉴定结果出来之前不要签「一次性了结」的协议。","money":"0","time":"中","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"19.16","sec":19,"n":16,"title":"工亡的三笔钱要分清：丧葬补助金、供养亲属抚恤金、一次性工亡补助金","cost":"办手续","human":"因工死亡是三笔钱，别只谈其中一笔：丧葬补助金是 6 个月的当地上年度职工月平均工资；供养亲属抚恤金按死者本人工资按月发，配偶每月 40%、其他亲属每人每月 30%；一次性工亡补助金是上一年度全国城镇居民人均可支配收入的 20 倍，全国就这一个数，不存在「我们这边地方标准低」。","gain":"丧葬补助金为 6 个月的统筹地区上年度职工月平均工资；供养亲属抚恤金按本人工资，配偶每月 40%、其他亲属每人每月 30%；一次性工亡补助金为上一年度全国城镇居民人均可支配收入的 20 倍，全国一个数，不分地区","grade":"A","src":"工伤保险条例第三十九条：「（一）丧葬补助金为6个月的统筹地区上年度职工月平均工资；（二）供养亲属抚恤金按照职工本人工资的一定比例发给由因工死亡职工生前提供主要生活来源、无劳动能力的亲属。标准为：配偶每月40%，其他亲属每人每月30%，孤寡老人或者孤儿每人每月在上述标准的基础上增加10%……（三）一次性工亡补助金标准为上一年度全国城镇居民人均可支配收入的20倍。」. <https://www.gov.cn/gongbao/content/2011/content_1778064.htm>","note":"TODO（待核实：按 2025 年全国城镇居民人均可支配收入折算出的当年具体金额，本次未取得国家统计局原文）。一次性工亡补助金全国统一，谈赔偿时不接受「我们这边地方标准低」的说法。","money":"0","time":"中","will":"否","level":"大","lens":"金钱","dispute":false,"todo":true,"ratio":"高"}]},{"n":20,"title":"刚出生的孩子怎么带","intro":"口径：婴儿死亡率与金钱。这一节只收效应量大、有硬证据的几件事，育儿细节不在本书范围内。出生之前和出院当天要办的事见第 27 节。","entries":[{"id":"20.1","sec":20,"n":1,"title":"让孩子仰着睡，睡硬的平面，同房不同床，床上不放任何软东西","cost":"0 元；床垫要硬的，几百元","human":"让孩子仰着睡、睡硬的平面、和大人同屋不同床，床上不放枕头、被子、床围、毛绒玩具和定型枕，倾斜的摇篮和婴儿椅不能当睡觉的地方。光美国每年就有约 3500 名婴儿死于睡眠相关原因，这是本节里降低风险最多的一条。","gain":"美国每年约 3500 名婴儿死于睡眠相关原因（婴儿猝死综合征、死因不明和床上意外窒息）。美国儿科学会的安全睡眠环境建议是「仰卧位；使用坚实、不倾斜的睡眠表面；同房不同床；避免柔软的寝具和过热」；降低风险的其他措施包括母乳喂养、避免接触尼古丁和酒精、按时接种疫苗、使用安抚奶嘴","grade":"A","src":"Moon RY, Carlin RF, Hand I, Task Force on Sudden Infant Death Syndrome and the Committee on Fetus and Newborn (2022). Sleep-Related Infant Deaths: Updated 2022 Recommendations for Reducing Infant Deaths in the Sleep Environment. Pediatrics, 150(1), e2022057990. <https://doi.org/10.1542/peds.2022-057990>","note":"「床上不放任何软东西」指枕头、被子、床围、毛绒玩具、定型枕全都不放，包括看起来很安全的哺乳枕。倾斜的摇篮和婴儿椅不能当睡觉的地方。这是这一节里效应量最大的一条，也是最需要顶住长辈压力的一条","money":"0","time":"少","will":"是","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"20.2","sec":20,"n":2,"title":"出生后 24 小时内打上乙肝疫苗第一针","cost":"0 元，免疫规划疫苗免费","human":"出生 24 小时内打上第一针乙肝疫苗。婴儿期和幼儿期感染乙肝的人里约有 95% 会转成慢性肝炎，成年后感染则绝大多数能自己好，所以这一针越早越有用。母亲乙肝表面抗原阳性的，孩子还要同时打乙肝免疫球蛋白。","gain":"世界卫生组织：「所有婴儿都应在出生后尽早（24 小时内）接种乙肝疫苗。」原因是「婴儿期和幼儿期感染约有 95% 会发展为慢性肝炎」，而成年后感染绝大多数能自愈","grade":"A","src":"World Health Organization. Hepatitis B fact sheet. <https://www.who.int/news-room/fact-sheets/detail/hepatitis-b>","note":"母亲乙肝表面抗原阳性的，新生儿还要同时打乙肝免疫球蛋白，产检时就要查清楚。母亲自己的筛查见第 1 节","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"20.3","sec":20,"n":3,"title":"按国家免疫规划把该打的疫苗打齐，全程免费，错过了只补没打完的剂次","cost":"0 元，法律写明「接种单位接种免疫规划疫苗不得收取任何费用」；要按月龄跑几趟接种门诊，预防接种证别丢","human":"国家免疫规划的疫苗全程免费，接种单位不能收任何费用；入托、入学都要查预防接种证，漏打的到时候一定会被翻出来补种。错过了只补没打完的那几剂，不用从头再打一遍，同种疫苗换厂家也能接着打。湿疹、荨麻疹、过敏性鼻炎、哮喘病情稳定和新生儿黄疸都不是不能打的理由。","gain":"儿童入托、入学时托幼机构和学校应当查验预防接种证，发现未按规定接种免疫规划疫苗的，要报告接种单位并配合督促监护人补种——漏打不是「以后再说」，是入学时一定会被翻出来。现行程序是 2026 年版：人乳头瘤病毒（HPV）疫苗已纳入国家免疫规划；百白破疫苗起始接种年龄由 3 月龄调整为 2 月龄，共 5 剂，分别在 2 月龄、4 月龄、6 月龄、18 月龄和 6 周岁各 1 剂；西藏、青海、新疆和新疆生产建设兵团的适龄儿童 2026 年 3 月起也常规接种乙脑疫苗。同时接种是允许的：现阶段国家免疫规划疫苗均可按免疫程序或补种原则同时接种，两种及以上注射类疫苗应在不同部位接种，「严禁将两种或多种疫苗混合吸入同一支注射器内接种」；未同时接种的，两种及以上注射类减毒活疫苗间隔不小于 28 天，灭活疫苗和口服类减毒活疫苗与其他疫苗的间隔不作限制。补种原则（小于 18 周岁）：尽早补种、「只需补种未完成的剂次，无需重新开始全程接种」，同种疫苗换厂家可以接着打（全国，2026 年版程序）","grade":"A","src":"全国人大常委会 (2019). 疫苗管理法（第四十八、四十九条）. <http://ynswsjkw.yn.gov.cn/html/2019/faguiguizhangxin_0731/6509.html>（云南省卫生健康委员会转载）；国家疾病预防控制局、国家卫生健康委 (2026). 《国家免疫规划疫苗儿童免疫程序及说明（2026 年版）》解读问答. <https://www.ndcpa.gov.cn/jbkzzx/c100013/common/content/content_2073002930292035584.html>","note":"最常见的误会是「体质不好先别打」。官方口径：「过敏性体质」、有过敏性疾病家族史、食物过敏史、药物过敏史都不是接种禁忌；特应性皮炎（湿疹）、荨麻疹、过敏性鼻炎、支气管哮喘病情稳定的可正常接种，正在口服抗过敏药或吸入糖皮质激素也可以；新生儿生理性黄疸、母乳性黄疸可以正常接种。真正的禁忌是既往接种同种疫苗发生过急性严重过敏反应，或者对已知疫苗成分严重过敏。免疫缺陷、正在化疗放疗或使用免疫抑制剂的要分类评估，去接种门诊说明情况再定。乙肝第一针见第 2 条。自费的非免疫规划疫苗另收疫苗费和接种服务费，和这条无关。","money":"0","time":"中","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"20.4","sec":20,"n":4,"title":"前 6 个月只喂母乳，连水都不用喂，6 个月起加辅食并继续母乳","cost":"0 元，还省下奶粉钱；哺乳占时间","human":"出生第一个小时内就开始喂奶，前 6 个月只喂母乳、连水都不用喂，满 6 个月起加辅食并继续喂到 2 岁或以上，辅食每天要有含铁丰富的动物性食物。母乳不够或者不能喂就用配方奶，这一项的差距远小于安全睡眠那条。","gain":"世界卫生组织建议「在出生后第一个小时内开始母乳喂养」，「前 6 个月纯母乳喂养，即不提供其他任何食物或液体，包括水」，「从 6 月龄起开始添加安全充足的辅食，同时继续母乳喂养到 2 岁或以上」。国家卫健委的服务指南同样提倡 0 至 6 月龄纯母乳喂养，并要求满 6 月龄起「每天的辅食必须包含含铁丰富的动物性食物」","grade":"A","src":"World Health Organization. Breastfeeding. <https://www.who.int/health-topics/breastfeeding>；国家卫生健康委办公厅 (2024). 婴幼儿营养喂养评估服务指南（试行）（国卫办妇幼函〔2024〕452 号）. <https://www.gov.cn/zhengce/zhengceku/202502/content_7002872.htm>","note":"母乳不足或不能哺乳时用配方奶，不必内疚，效应量的差距远小于安全睡眠那条。6 至 8 月龄每天加 1 到 2 次辅食，9 至 12 月龄 2 到 3 次；每天的食物至少覆盖七类中的四类","money":"0","time":"多","will":"是","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"20.5","sec":20,"n":5,"title":"冲奶粉用 70 ℃ 以上的水，冲好放凉再喂，喝剩的倒掉","cost":"0 元；多等几分钟放凉","human":"奶粉不是无菌的，可能带阪崎克罗诺杆菌，新生儿感染后的病死率报告在四成到八成之间。先把热水倒进奶瓶、等水温降到约 73.8 ℃ 再下奶粉，奶液温度还在 70 ℃ 以上，能把这种菌减少到原来的十万分之一以下。冲好放凉再喂，喝剩的倒掉；早产儿、低体重儿和 2 月龄以下的孩子风险最高。","gain":"奶粉不是无菌的，可能带阪崎克罗诺杆菌，新生儿感染后病死率报告为 40% 到 80%。实验研究显示，先把热水倒进奶瓶、等水温降到约 73.8 ℃ 再加奶粉，绝大多数情况下奶液温度仍在 70 ℃ 以上，可使该菌减少 5 个对数级以上","grade":"A","src":"Beary MA, Daly SE, Baker J, Snyder AB (2025). Assessing Hot Water Reconstitution Instructions and Labeling of Powdered Infant Formula to Ensure Cronobacter spp. Reduction. Journal of Food Protection, 88(9), 100571. <https://doi.org/10.1016/j.jfp.2025.100571>；Sima WG, Legesse T, Girma S, et al. (2025). Emerging microbial risks: Cronobacter sakazakii in powdered infant formula for infants under six months of age in Ethiopia. BMC Microbiology, 26, 307. <https://doi.org/10.1186/s12866-025-04380-y>；World Health Organization & FAO (2007). Safe preparation, storage and handling of powdered infant formula: guidelines. <https://www.who.int/publications/i/item/9789241595414>","note":"70 ℃ 这个门槛来自公共卫生指南，Beary 等人的原话是「针对高危婴儿照护者的公共卫生指南建议用加热到至少 70 ℃（158 ℉）的水冲调配方奶粉以灭活微生物」。早产儿、低体重儿和 2 月龄以下的婴儿风险最高。别用保温杯里放了一天的水，也别把冲好的奶放在室温下等着下一顿","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"20.6","sec":20,"n":6,"title":"不满 1 岁不喂蜂蜜","cost":"0 元","human":"不满 1 岁不喂蜂蜜，包括蜂蜜水、拌进辅食的蜂蜜和含蜂蜜的糕点。蜂蜜里可能带有引起肉毒中毒的细菌，成年人的肠道菌群能压住它，婴儿压不住。自家做的腌菜和发酵食品同理。","gain":"美国疾控中心：「不要给 1 岁以下的儿童喂蜂蜜」，因为「蜂蜜可能含有引起肉毒中毒的细菌」。成年人的肠道菌群能压住这种芽孢，婴儿不能","grade":"A","src":"US CDC. Preventing Botulism. <https://www.cdc.gov/botulism/prevention/index.html>","note":"包括蜂蜜水、蜂蜜拌辅食、含蜂蜜的糕点。同理，自家做的腌菜、发酵食品也不要给婴儿吃","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"20.7","sec":20,"n":7,"title":"出生时的维生素 K 针一定要打","cost":"0 元到几十元，通常包含在住院分娩里","human":"新生儿体内的维生素 K 本来就很低，不补充可能出血，晚发的常表现为颅内出血。在没有普遍打这一针的地方，这种出血的发生率是每 10 万名新生儿 478 例，打了估计能降七成八以上。国内正规医院分娩会常规注射，在家或者在不正规机构生的要主动确认；世卫组织给的做法是出生时肌肉注射一次。","gain":"新生儿体内维生素 K 储备很低，不补充可能发生维生素 K 缺乏性出血，晚发型常表现为颅内出血。比利时的共识建议是「出生时肌肉注射 1 或 2 毫克维生素 K 一次」；在未系统提供预防的地区（塔什干 4.2 万名新生儿），维生素 K 缺乏性出血的发生率为每 10 万人 478 例，作者估计通过预防可使发生率下降「高于 78.5%」","grade":"B","src":"Fiesack S, Smits A, Rayyan M, et al. (2021). Nutrients, 13(11), 4109. <https://doi.org/10.3390/nu13114109>；Tursunov D, Yoshida Y, Yrysov K, et al. (2018). Nagoya Journal of Medical Science, 80(1), 11. <https://doi.org/10.18999/nagjms.80.1.11>","note":"在中国正规医院分娩会常规注射，不用自己操心；在家分娩或在不正规机构分娩的要主动确认。口服方案的效果不如肌注","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"20.8","sec":20,"n":8,"title":"不满 3 个月的婴儿体温到 38 ℃ 就直接去医院，不在家观察","cost":"挂号加检查几百元","human":"不满 3 个月的孩子体温到 38 ℃ 就直接去医院，不在家观察，也不要先喂退烧药再等等看。这个月龄的孩子哪怕得的是严重细菌感染，也可能只表现为发热，「看着精神还行」不能当作在家等的理由；不满 8 天的连专门指南都不收，更要立即就医。","gain":"美国儿科学会针对 8 至 60 日龄、看上去状态尚可的足月婴儿制定了专门指南，把发热定义为「体温 ≥38.0 ℃」，并按 8 至 21 日龄、22 至 28 日龄、29 至 60 日龄分三档给出处理路径；不满 8 日龄的婴儿甚至不在该指南范围内，意味着更要立即就医","grade":"A","src":"Pantell RH, Roberts KB, Adams WG, et al. (2021). Evaluation and Management of Well-Appearing Febrile Infants 8 to 60 Days Old. Pediatrics, 148(2), e2021052228. <https://doi.org/10.1542/peds.2021-052228>","note":"这个月龄的孩子得了严重细菌感染也可能只表现为发热，看着「精神还行」不能作为在家观察的理由。别自行喂退烧药后再等等看","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"20.9","sec":20,"n":9,"title":"无论多累多气都不要摇晃婴儿","cost":"0 元","human":"婴儿头部占比大、脖子肌肉弱，剧烈摇晃会造成颅内出血和视网膜出血，可能致死或者留下终身残疾。哄睡时的轻柔摇动不算，危险的是失控的那种晃。快压不住的时候把孩子放回婴儿床，人走开几分钟，让他哭一会儿比抱着晃安全得多。","gain":"婴儿头部占比大、颈部肌肉弱，剧烈摇晃会造成颅内出血和视网膜出血，可致死或留下终身残疾。哄睡时的轻柔摇动与之不同，危险的是失控的剧烈晃动","grade":"C","src":"作者经验与普遍共识，本轮未取得可直接引用的原始文献","note":"真的到了要失控的时候，把孩子放回婴儿床里，人走开几分钟，让他哭一会儿比抱着晃安全得多。这一条对独自带娃、长期睡不够的人最重要，情绪处理见第 3 节","money":"0","time":"少","will":"是","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"20.10","sec":20,"n":10,"title":"尿布不看牌子看三件事：合不合身、换得勤不勤、有没有被抽检通报过","cost":"每月两三百到上千元不等","human":"没有任何官方机构排过「哪个牌子最好」，能查的只有市场监管总局的产品质量抽检通报，和监管部门对具体事件的调查。贵的不等于安全，进口的不等于合格。先买小包装试一周，看有没有红屁股和勒痕，合适再囤；先买小包装试一周，看有没有红屁股和勒痕。","gain":"没有任何官方机构发布过「哪个牌子最好」的排名，所以本书不给品牌推荐。可核查的信息只有两类：一是国家市场监督管理总局的产品质量抽检通报，二是监管部门对具体事件的调查。2026 年 6 月「婴幼儿纸尿裤甲酰胺问题」引发关注后，市场监管总局牵头成立了联合调查组核查","grade":"C","src":"中国政府网 (2026-06-22). 市场监管总局牵头成立联合调查组核查「婴幼儿纸尿裤甲酰胺问题」. <https://www.gov.cn/zhengce/202606/content_7072931.htm>（该页仅有标题，正文未展示，故本条只引用调查这一事实，不引用任何结论）","note":"TODO（待核实：该次调查的结论与市场监管总局的正式通报原文）。实操上：贵的不等于安全，进口的不等于合格；先买小包装试一周，看有没有红屁股和勒痕，合适再囤。红屁股主要由换得不够勤和不透气造成，与品牌关系没有想象中大。查抽检通报的方法见第 5 节","money":"少","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":true,"ratio":"一般"},{"id":"20.11","sec":20,"n":11,"title":"大件按「借、买二手、买新」的顺序考虑，别一次性配齐","cost":"省下的钱通常以千元计","human":"婴儿车、婴儿床、抱被、玩具的使用期都很短，二手市场供给远大于需求，按借、买二手、买新的顺序来通常能省下千元级的钱。安全座椅和床垫不建议买二手——座椅撞击后的结构损伤肉眼看不出来。月子会所、早教课这类属于大额非必需支出，先过 24 小时冷静期。","gain":"婴儿车、婴儿床、抱被、玩具的使用期都很短，二手市场供给远大于需求。真正不能省、也不建议买二手的是安全座椅（撞击后结构损伤肉眼看不出）和床垫","grade":"C","src":"作者经验，无直接文献；安全座椅的证据见第 1 节，冲动消费见第 5 节","note":"月子会所、早教课、婴儿游泳馆这类，本书不做推荐也不做否定，但它们属于大额非必需支出，适用第 5 节的 24 小时冷静期","money":"少","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"}]},{"n":21,"title":"出国、旅行与境外安全","intro":"本节的口径是金钱与人身自由，少数条目关系到人身安全。境外的规则由所在国定，中国的驻外机构能做的事有明确边界，这一节先讲清楚这条边界在哪。","entries":[{"id":"21.1","sec":21,"n":1,"title":"出发前查一次外交部安全提醒，标了「暂勿前往」的地方就别去","cost":"0 元；打开中国领事服务网翻一遍，几分钟","human":"外交部把国外的安全风险分四档，最高一档是「暂勿前往」。2026 年 9 月 15 日起，避开高风险国家和地区已经写进行政法规，办证和出境边检时还会提醒你，去最高风险地区的必要时会被劝阻。出发前翻一遍那一页只要几分钟。","gain":"外交部按级别公开发布国外安全提醒，从低到高大致是「注意安全」「加强安全防范」「谨慎前往」「暂勿前往」。2026 年 9 月 15 日起施行的新规把公民这一侧的义务也写进了行政法规：「中国公民应当关注国外安全提醒和旅游目的地安全风险提示，避免前往及驻留高风险国家或者地区」；同时要求移民管理机构在办证和出境边检时提醒前往高风险地区的公民，「对准备前往风险等级为最高级别或者严重危及人身安全案件突发高发的国家或者地区的中国公民，必要时应当劝阻其前往」","grade":"A","src":"国务院 (2026). 关于出境入境管理的规定（国令第 841 号）. <https://www.gov.cn/zhengce/zhengceku/202607/content_7077173.htm>（第二条）；国务院 (2023). 领事保护与协助条例（国令第 763 号）. <https://www.gov.cn/zhengce/zhengceku/202307/content_6891761.htm>（第十九、二十一条）；外交部领事司. 安全提醒. <https://cs.mfa.gov.cn/zggmzhw/lsbh/aqtx/>","note":"提醒会随局势变动，本书不抄名单，出行前自己查一次那一页。截至 2026 年 9 月 7 日，该栏目仍在列的「暂勿前往」类提醒包括斯威士兰（2026-08-25）、巴勒斯坦（2023-10-10）、苏丹（2023-04-17）、阿富汗（2023-02-17）、叙利亚（2023-01-04）、秘鲁（2022-12-29）、索马里（2022-11-24），另有针对缅北地区、刚果（金）部分省份的专门提醒。旅行社也有告知义务，跟团前可以要求对方书面说明目的地风险","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"21.2","sec":21,"n":2,"title":"把 12308 和当地使领馆的领保电话存进手机，别等出事再找","cost":"0 元；存两个号码","human":"出事时的求助电话就一个，境内打 12308，境外打 +86-10-12308。这条热线开通以来接了 300 多万通电话，同期外交部和驻外机构处理了 50 多万起领事保护案件。号码只存在手机里等于没存，手机丢了两样一起没。","gain":"外交部全球领事保护与服务应急热线 24 小时运转，境内拨 12308，境外拨 +86-10-12308 或 +86-10-65612308。该热线自 2014 年开通以来累计接听 300 多万通来电，同期外交部和驻外机构处置各类领事保护案件 50 多万起","grade":"A","src":"外交部、中国驻缅甸使领馆 (2023). 关于当前缅北地区安全局势的领事提醒. <https://cs.mfa.gov.cn/zggmzhw/lsbh/aqtx/202311/t20231109_11176682.shtml>；国务院新闻办 (2023). 国务院政策例行吹风会介绍领事保护与协助有关情况. <https://www.gov.cn/xinwen/2023zccfh/11/index.htm>","note":"驻当地使领馆自己还有一个领保电话，通常比总台更快，出发前在领事服务网上按国家查到并一起存好。手机丢了这些号码就没了，另抄一份放在钱包或写给家里人","money":"0","time":"少","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"21.3","sec":21,"n":3,"title":"知道领事保护能做什么、不能做什么：能探视，不能捞人，费用还得自己付","cost":"0 元；读一遍边界","human":"被抓时使领馆能做的是向当地核实情况、要求依法公正处理、去探视、开庭旁听，不能替你改判、也不能把人领走。别人先垫的食宿、交通、医疗费，最后仍由你自己付。所以出国前把钱和保险备好，别把「出事了国家会兜底」当成计划。","gain":"被抓时使领馆能做的是：向所在国有关部门核实情况、要求依法公正处理，并「按照驻在国法律和我国与驻在国缔结或者共同参加的国际条约对其进行探视或者与其联络，了解其相关需求，要求驻在国有关部门给予该中国公民人道主义待遇和公正待遇」；开庭时可以旁听并要求保障诉讼权利。受伤或遇灾时能敦促当地紧急救助、协助家属处理善后。但费用这一侧写得同样清楚：「中国公民、法人、非法人组织在领事保护与协助过程中，得到第三方提供的食宿、交通、医疗等物资和服务的，应当支付应由其自身承担的费用」","grade":"A","src":"国务院 (2023). 领事保护与协助条例（国令第 763 号）. <https://www.gov.cn/zhengce/zhengceku/202307/content_6891761.htm>（第九、十、十四、二十六条）","note":"使领馆不替你交罚款、医药费、机票钱，也不能改变所在国的司法结论。它能提供的是当地律师、翻译、医疗、殡葬机构的信息，以及联系亲友和获取救济的协助。理解这条边界的实际用处是：出国前自己把钱和保险准备好，别把「出事了国家会兜底」当成计划","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"21.4","sec":21,"n":4,"title":"买一份含境外医疗和医疗转运的保险，别只买航班延误险","cost":"短期境外旅行险几十到几百元","human":"在国外看病的钱要自己掏，国内医保基本不报，使领馆也不垫付。真正能拖垮一个家的不是门诊费，是重伤后的住院和把人运回国——那要靠专机或医疗护送。买旅行险主要看两个额度：境外医疗费用、紧急医疗转运与送返。","gain":"境外看病的钱要自己出，国内医保在境外基本不报销，领事保护也不垫付（见上一条的条例第二十六条）。真正会把家庭拖垮的不是门诊费，而是重伤后的住院和医疗转运——把人从境外医院转回国需要专机或医疗护送，属于自费项目里最贵的一类。买保险时优先看两项额度：境外医疗费用额度、紧急医疗转运与送返额度","grade":"C","src":"国务院 (2023). 领事保护与协助条例（国令第 763 号）. <https://www.gov.cn/zhengce/zhengceku/202307/content_6891761.htm>（第二十六条）；作者经验，无直接文献","note":"TODO（待核实：境外医疗与医疗转运的典型费用区间，需要官方或行业统计口径的数字）。买之前确认三件事：目的地是否在承保区域、是否除外高风险活动（潜水、滑雪、摩托车）、理赔是垫付还是先自付后报销。免签不等于免责，去哪都一样要买","money":"少","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":true,"ratio":"高"},{"id":"21.5","sec":21,"n":5,"title":"「境外高薪招聘」一律当诈骗看，被骗去做电诈回来还要被限制出境","cost":"0 元；拒绝一份看起来很好的工作","human":"月薪高得离谱、不问学历经验、不签正规合同、让你先到边境城市集合、还替你保管护照的工作，去了人和护照都不在自己手上。出境时材料造假会被拦下不放行；在境外参与了违法犯罪，回国之后还可能 6 个月到 3 年不准出境。","gain":"官方对这类案件的定性很直接：近年出现「上当受骗出境或者虚构事由非法出境从事跨境赌博、电信网络诈骗等违法活动，严重危害人民群众生命和财产安全」。新规针对这一点收紧了两头：出境时「申请出境入境、停留居留的事由应当真实、合法」，提供虚假材料或作虚假陈述的，移民管理机构有权不予签发证件或不准出境；回国后，「中国公民在境外从事违法犯罪活动，危害国家安全和利益的，可以……决定自回国之日起 6 个月至 3 年以内不准其出境」，因骗取证件、非法出境入境被行政拘留的同样是 6 个月至 3 年不准出境","grade":"A","src":"国务院 (2026). 关于出境入境管理的规定（国令第 841 号）. <https://www.gov.cn/zhengce/zhengceku/202607/content_7077173.htm>（第三、四条）；司法部、公安部、国家移民局 (2026). 就《国务院关于出境入境管理的规定》答记者问. <https://www.gov.cn/zhengce/202608/content_7077270.htm>","note":"识别特征基本固定：月薪远高于同岗位、不要求学历经验、不签正规合同、让你先到边境城市集合、代办签证并保管你的护照。缅北地区已有专门的领事提醒。真去了，人身自由和护照都不在自己手上，「想走就能走」不成立","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"21.6","sec":21,"n":6,"title":"护照、签证、身份证都拍照存一份在云端，丢了先报警再补旅行证","cost":"0 元；出发前拍几张照片","human":"护照丢了，使领馆能给你补一张回国用的旅行证件，前提是你能证明自己是谁——有资料页、签证页照片和出入境记录，补办快得多。还得先在当地报警拿回执，出境检查和保险理赔都认这张纸。手机通常和护照一起丢，照片别只存手机里。","gain":"护照丢失时，驻外使领馆能签发回国用的旅行证件，但需要你证明身份；有清晰的护照资料页照片、签证页照片和出入境记录，补办速度差别很大。同时要先在当地报警拿到报案回执，很多国家的出境检查和保险理赔都要这份材料。找使领馆的入口就是上面存的那两个电话","grade":"C","src":"国务院 (2023). 领事保护与协助条例（国令第 763 号）. <https://www.gov.cn/zhengce/zhengceku/202307/content_6891761.htm>（第十六条）；作者经验，无直接文献","note":"存法：拍照后放进两个不同的地方（云盘 + 发给一位家人），另外打印一份纸质复印件与原件分开放。银行卡、常用药处方也一并拍。手机和护照通常一起丢，只存在手机里等于没存","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"21.7","sec":21,"n":7,"title":"境外自驾先确认当地认不认中国驾照，网上卖的「国际驾照」多数是废纸","cost":"0 元；出发前查一次目的地规定","human":"网上代办的「国际驾照」在中国内地不成立：那本证是 1949 年日内瓦公约缔约方之间互认的翻译件，103 个缔约方里没有中国内地，所以国内谁办的都没有法律效力。能不能用中国驾照开车看目的地自己的规定，没确认清楚就别开。","gain":"所谓「国际驾照」（IDP）是 1949 年《道路交通公约》缔约国之间互认的翻译件。该公约 1949 年 9 月 19 日订于日内瓦，1952 年 3 月 26 日生效，目前有 103 个缔约方，中国内地不在缔约方名单内。所以中国不签发这种国际驾照，任何机构在国内「代办国际驾照」都不产生法律效力；能不能用中国驾照开车，取决于目的地国家或地区自己的规定（有的承认中国驾照加公证翻译件，有的要求换领当地驾照，有的完全不认）","grade":"A","src":"United Nations Treaty Collection. Convention on Road Traffic, Geneva, 19 September 1949 — status of treaties. <https://treaties.un.org/pages/ViewDetailsV.aspx?src=TREATY&mtdsg_no=XI-B-1&chapter=11&clang=_en>","note":"无证驾驶在多数国家是刑事或重罚级别的违法，而且出事后保险大概率拒赔，这才是真正的成本。查法：在中国领事服务网上找目的地国家的「中国公民须知」，或直接问租车公司要书面确认。香港、澳门、台湾地区以及部分国家另有单独安排","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"21.8","sec":21,"n":8,"title":"找中介办签证、留学、移民，先问它有没有在移民管理机构备案","cost":"0 元；多问一句并留存书面材料","human":"2026 年 9 月 15 日起，办签证、留学、移民的中介要在设立后 15 日内向移民管理机构备案，已经在做的 90 天内补办。「包过」「保签」「材料我们帮你做」这些话本身就在明令禁止之列。自己填表出错顶多被拒签，用了假材料会被认定弄虚作假，后果落在你往后的出入境记录上。","gain":"2018 年取消因私出入境中介服务机构准入许可后，机构数量快速增长，也出现了「机构底数不清、部分机构违法违规办理业务、损害出境入境人员合法权益」的问题。2026 年 9 月 15 日起，这类中介实行备案管理：机构应当自设立之日起 15 日内向所在地移民管理机构备案，此前已经营的要在施行之日起 90 日内补办；明令禁止的行为包括「发布虚假信息，或者通过夸大宣传、误导性宣传等方式招徕服务对象」「提供或者协助提供虚假材料，协助他人违规办理签证、停留居留证件、护照等出境入境证件或者手续」「泄露、出售、非法提供……个人隐私或者个人信息」「组织或者协助他人从事跨境违法犯罪活动」。境外企业、机构不得在中国境内提供此类中介服务","grade":"A","src":"国务院 (2026). 关于出境入境管理的规定（国令第 841 号）. <https://www.gov.cn/zhengce/zhengceku/202607/content_7077173.htm>（第七、八、十、十二、十三条）","note":"让你「包过」「保签」「材料我们帮你做」的，本身就在禁止清单上，被查出来受损的是你的签证记录。个人自己填表申请出问题只是被拒签，用了假材料则可能被认定弄虚作假，后果重得多。不以营利为目的的政策咨询、查询不算中介服务","money":"0","time":"少","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"21.9","sec":21,"n":9,"title":"别替陌生人出具邀请函，也别让人借你的名义办出入境手续","cost":"0 元；拒绝一次人情","human":"替人出邀请函或申请材料，内容不实罚的是出具人：个人罚 5000 元到 1 万元，有违法所得一并没收；单位罚 1 万到 5 万，经手的人另罚 5000 到 1 万。一次人情换来的是自己掏这笔钱。","gain":"出具邀请函的人要对内容真实性负责：「个人为他人申请出境入境、停留居留出具虚假邀请函件或者其他申请材料的，由移民管理机构处 5000 元以上 1 万元以下罚款；有违法所得的，没收违法所得」；单位的罚 1 万元以上 5 万元以下，并对直接负责的主管人员和其他直接责任人员处 5000 元以上 1 万元以下罚款","grade":"A","src":"国务院 (2026). 关于出境入境管理的规定（国令第 841 号）. <https://www.gov.cn/zhengce/zhengceku/202607/content_7077173.htm>（第三、十一条）","note":"和第 8 节「不帮陌生人带东西」是同一类风险：签的字、盖的章、担的保，后果落在自己身上。公职人员、军队人员委托中介违规办理外国国籍或境外居留资格的，中介不得办理并须向监察机关报告","money":"0","time":"少","will":"些","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"21.10","sec":21,"n":10,"title":"出境前把行程、住处和同行人发给一位家人，约好多久联系一次","cost":"0 元；发一条消息","human":"人在境外失联时，家里人可以找驻外机构求助，对方会给当地报警方式和别的求助渠道，当地立案后使领馆跟进催办。这条链能不能启动，取决于国内有没有人知道你该在哪、该什么时候联系。航班号、住址、同行人电话、约定的联系频率，发给一个人就够。","gain":"中国公民在境外下落不明时，亲属可以向驻外外交机构求助，「驻外外交机构应当提供当地报警方式及其他获取救助的信息」，当地警方立案后使领馆会敦促及时处理。这条链路能不能启动，取决于国内有没有人知道你本该在哪、本该什么时候联系","grade":"C","src":"国务院 (2023). 领事保护与协助条例（国令第 763 号）. <https://www.gov.cn/zhengce/zhengceku/202307/content_6891761.htm>（第十三条）；作者经验，无直接文献","note":"写清四样就够：航班号、住处地址、同行人姓名电话、约定的联系频率。去信号差或治安差的地方，把「多久没消息就报警」这句话也说明白。这条成本接近零，但它是上面所有救助程序能不能开始的前提","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"}]},{"n":22,"title":"怎么放松：娱乐场所和减压","intro":"前半节是娱乐场所的钱坑和安全出口，口径是金钱与人身自由；后半节是减压方法，口径是精力与总死亡率。两半的数字不做换算。第 3 节已经写过情绪低落时先做哪几件事，这里给的是更具体的处方。","entries":[{"id":"22.1","sec":22,"n":1,"title":"进 KTV、酒吧、密室之前先看一眼安全出口在哪，被锁被堵就换一家","cost":"0 元；进门时抬头看 10 秒","human":"按规定，娱乐场所营业时疏散通道和安全出口必须畅通，不许封堵锁闭、摆障碍物、遮挡指示标志，网吧同样不许封门锁窗，做不到就是违法，可以举报。包厢在地下、只有一个出口、走道堆满杂物的换一家——这类场所着火时烟大、道窄、人多且多半喝了酒。","gain":"这是经营者的法定义务，也就意味着不做到就是违法可举报：「营业期间，娱乐场所应当保证疏散通道和安全出口畅通，不得封堵、锁闭疏散通道和安全出口，不得在疏散通道和安全出口设置栅栏等影响疏散的障碍物」，并「应当在疏散通道和安全出口设置明显指示标志，不得遮挡、覆盖指示标志」。网吧同样被要求「营业期间禁止封堵或者锁闭门窗、安全疏散通道和安全出口」并「禁止明火照明和吸烟」","grade":"A","src":"国务院 (2006). 娱乐场所管理条例（国令第 458 号，第二十、二十一条）. <http://www.gov.cn/zhengce/zhengceku/2008-03/28/content_6297.htm>；国务院 (2002). 互联网上网服务营业场所管理条例（国令第 363 号，第二十一条）. <http://www.gov.cn/gongbao/content/2002/content_61788.htm>","note":"包厢在地下、只有一个出口、走道堆满杂物、安全出口指示灯不亮，这几样占了任何一样就换地方。这类场所的火灾特点是烟大、走道窄、人多且多数喝了酒，逃生时间以秒计。举报电话按条例应当写在场所内的警示标志上","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"22.2","sec":22,"n":2,"title":"点单前要价目表，娱乐场所必须明码标价，不接受「先玩后算」","cost":"0 元；开口要一次单子","human":"按规定，娱乐场所卖服务和商品必须明码标价并主动出示价目表，不许强迫或欺骗消费。所谓「天价酒水」几乎都发生在没看过价目表、事后按口头报价结账的场合。进包厢先要单子拍照，点完再要一份确认清单；结账有争议当场打 12315，付了钱再维权举证难得多。","gain":"「娱乐场所提供娱乐服务项目和出售商品，应当明码标价，并向消费者出示价目表；不得强迫、欺骗消费者接受服务、购买商品。」违反价格法律法规的由有关部门依法处罚。所谓「天价酒水」纠纷，绝大多数发生在没有出示价目表、事后按口头报价结账的场合","grade":"A","src":"国务院 (2006). 娱乐场所管理条例（国令第 458 号，第二十九、五十三条）. <http://www.gov.cn/zhengce/zhengceku/2008-03/28/content_6297.htm>","note":"落地做法：进包厢先要纸质或电子价目表并拍照，点单后要一份确认的清单，服务员推荐的「特调」「果盘」一律先问价再点。结账有争议时当场打 12315，别先付款再维权——付了款举证难度立刻变高","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"22.3","sec":22,"n":3,"title":"场子里有人递「东西」就立刻走，容留和提供都不是「帮朋友」","cost":"0 元；走出去","human":"娱乐场所禁止贩卖、提供毒品和容留他人吸食，违反的没收违法所得、停业整顿 3 到 6 个月，重的吊销许可证。个人这一头更重：自己吸要受治安处罚，在自己订的包厢或住处让人「用一下」，就是容留他人吸毒这个刑事犯罪。有人掏出不明粉末、片剂、烟弹请你试，当场走。","gain":"娱乐场所被明令禁止「贩卖、提供毒品，或者组织、强迫、教唆、引诱、欺骗、容留他人吸食、注射毒品」，从业人员也不得吸毒或为顾客实施上述行为提供条件；违反的由公安部门没收违法所得和非法财物，责令停业整顿 3 至 6 个月，情节严重的吊销娱乐经营许可证。条例还要求场所在大厅、包厢、包间的显著位置悬挂禁毒、禁赌、禁止卖淫嫖娼的警示标志，并注明举报电话","grade":"A","src":"国务院 (2006). 娱乐场所管理条例（国令第 458 号，第十四、三十、四十二条）. <http://www.gov.cn/zhengce/zhengceku/2008-03/28/content_6297.htm>","note":"个人这一侧的风险比场所更重：吸毒本身要受治安处罚，而在自己订的包厢或住处「让朋友在这儿用一下」，构成的是容留他人吸毒，属于刑事犯罪。判断很简单——只要有人拿出不明粉末、片剂、电子烟弹并请你「试试」，当场离开，别留下来看热闹","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"22.4","sec":22,"n":4,"title":"不吃陌生人给的糖和零食，不喝离开过视线的饮料，不接别人递的烟弹","cost":"0 元；递过来的一律不接，自己的杯子离开视线就换一杯","human":"现在的毒品不长毒品的样子——掺了合成大麻素的「上头」电子烟能调成各种颜色口味，外观和普通电子烟基本一致，专在酒吧、KTV、宾馆里递给人试。骗人吸食的拘留 10 到 15 日、罚 1000 到 5000 元；被骗吸了的人自己也要拘留 10 到 15 日并可罚 3000 元以下，成瘾还要社区戒毒 3 年。饮料离开过视线就换一杯。","gain":"现在的毒品不长毒品的样子。合成大麻素类物质自 2021 年 7 月 1 日起被整类列管，掺进烟油做成「上头」电子烟，最高检报道的案子里，办案人员的描述是烟油「可以通过添加食用颜料变成各种颜色、各种口味」，「在外观上和普通电子烟基本一致」，卖家在酒吧、KTV、宾馆呼朋引伴推销、诱导他人吸食，报道里当地当年办理的吸食案件中未成年吸食者占比近四成；依托咪酯自 2023 年 10 月 1 日起列入第二类精神药品目录。骗人吸食本身就是一档违法：引诱、教唆、欺骗或者强迫他人吸食、注射毒品的，拘留 10 到 15 日并罚 1000 到 5000 元；构成犯罪的判 3 年以下，情节严重判 3 到 7 年，强迫的判 3 到 10 年，对未成年人下手的从重。而后果落在被骗的人身上：吸食、注射毒品的处 10 到 15 日拘留并可罚 3000 元以下（情节较轻处 5 日以下拘留或者 1000 元以下罚款），还可能被同时责令 6 个月到 1 年内不得进入娱乐场所；成瘾的责令社区戒毒 3 年，拒绝社区戒毒或者戒毒期间再吸的强制隔离戒毒 2 年，最长可再延长 1 年（全国，治安管理处罚法 2026 年 1 月起）","grade":"A","src":"最高人民检察院 (2021). 江苏苏州吴江区：办案检察官揭秘披着潮流外衣的新型毒品. <https://www.spp.gov.cn/spp/zdgz/202110/t20211011_531831.shtml>；国家药监局、公安部、国家卫生健康委 (2023). 关于调整麻醉药品和精神药品目录的公告（2023 年第 120 号）. <https://yjj.sh.gov.cn/qtgzwj/20230911/3b612c94e35b4b63abba314c972a2593.html>（上海市药监局转载，原文页 nmpa.gov.cn 在本机返回 412）；全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第八十四、八十五条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；全国人大 (1997). 刑法（第三百五十三条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>；全国人大常委会 (2007). 禁毒法（第三十三、三十八、四十七条）. <http://www.gd.gov.cn/zwgk/wjk/zcfgk/content/post_2520706.html>（广东省人民政府转载）","note":"这条不只在娱乐场所：学校门口、朋友聚会、长途车上同理，给的是糖果、饮料还是烟弹都一样。被下药之后常跟着抢劫、性侵和敲诈，那部分没有公开的官方统计，属经验判断。饮料只要离开过视线就换一杯，比事后追究省事得多。场子里有人拿出不明粉末、片剂、烟弹的处置见本节第 3 条；替人带东西见第 8 节第 27 条。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"22.5","sec":22,"n":5,"title":"网吧上网用自己的身份证，别借证也别用别人的证","cost":"0 元","human":"按规定，网吧必须核对登记上网人的身份证并记录上网信息，留存不少于 60 天，公安和文化部门随时可以调取，期间不能改也不能删。用谁的证上网，那段时间这台机器上干的事就记在谁头上。","gain":"「互联网上网服务营业场所经营单位应当对上网消费者的身份证等有效证件进行核对、登记，并记录有关上网信息。登记内容和记录备份保存时间不得少于 60 日」，并在文化行政部门、公安机关依法查询时提供，保存期内不得修改或删除。也就是说，用谁的证上网，那段时间内在这台机器上做的事就记在谁头上","grade":"A","src":"国务院 (2002). 互联网上网服务营业场所管理条例（国令第 363 号，第二十三条）. <http://www.gov.cn/gongbao/content/2002/content_61788.htm>","note":"和第 9 节「身份证不借人」是同一条红线的具体场景。经营单位不得接纳未成年人，并应在入口显著位置悬挂未成年人禁入标志；歌舞娱乐场所同样不得接纳未成年人。帮未成年人「刷证进网吧」，被罚的是网吧，但记录留在你的证件上","money":"0","time":"少","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"22.6","sec":22,"n":6,"title":"剧本杀、密室别去开在居民楼里或者地下二层以下的","cost":"0 元；订之前问一句地址在几层","human":"五部门 2022 年的通知写明，剧本娱乐场所不得开在居民楼内、也不得开在地下一层以下。这类场地黑、隔断多、道具易燃，门还常常要解谜才打得开，起火比普通商铺难跑得多。订之前在点评页看一眼地址和楼层，不合规的换一家。","gain":"五部门 2022 年的专门通知写得很具体：「剧本娱乐经营场所不得设在居民楼内、建筑物地下一层以下（不含地下一层）等地」，并要求场所落实安全生产法和消防法的要求，「常态化开展火灾风险自知、自查、自改，提高紧急情况下的组织疏散逃生和初起火灾扑救能力」。同一份通知还要求剧本设置适龄提示，场景不适宜未成年人的不得允许未成年人进入，除法定节假日、休息日及寒暑假外不得向未成年人提供剧本娱乐活动","grade":"A","src":"文化和旅游部、公安部、住房和城乡建设部、应急管理部、市场监管总局 (2022). 关于加强剧本娱乐经营场所管理的通知. <https://www.gov.cn/zhengce/zhengceku/2022-06/27/content_5698021.htm>","note":"这类场所的特点是黑暗、隔断多、道具易燃、门常常需要「解谜」才能打开，一旦起火比普通商铺更难跑。订之前在点评页面上就能看出楼层和是不是居民楼，不合规的直接换一家","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"22.7","sec":22,"n":7,"title":"心情差就去走或者跑，抗抑郁的效应量跟强度成正比","cost":"0 元；每次半小时上下","human":"218 项随机试验、1.4 万多名符合重度抑郁标准的人：和常规照护、安慰剂片相比，改善最明显的是快走或慢跑，其次是瑜伽、力量训练、混合有氧、太极气功，几种差距不算大；强度开得越高效果越好，力量训练和瑜伽最容易坚持。作者自己说证据质量偏低，能用的方向是动比不动好，选自己坚持得下来的那种。","gain":"218 项随机试验、495 个组、14170 名符合重度抑郁临床标准的参与者的贝叶斯网状荟萃分析，与主动对照（常规照护、安慰剂片）相比：快走或慢跑 Hedges' g −0.62（95% 可信区间 −0.80 至 −0.45），瑜伽 −0.55（−0.73 至 −0.36），力量训练 −0.49（−0.69 至 −0.29），混合有氧 −0.43（−0.61 至 −0.24），太极或气功 −0.42（−0.65 至 −0.21）。「运动的效果与所处方的强度成正比」，且力量训练和瑜伽的可接受度最好","grade":"A","src":"Noetel M, Sanders T, Gallardo-Gómez D, et al. (2024). Effect of exercise for depression: systematic review and network meta-analysis of randomised controlled trials. BMJ, 384, e075847. <https://doi.org/10.1136/bmj-2023-075847>","note":"争议。作者自己写明，218 项研究里只有 1 项满足 Cochrane 的低偏倚风险标准，按 CINeMA 评级，快走慢跑为「低」、其余为「极低」置信度；运动试验无法对参与者设盲，期望效应难以排除。结论方向仍然可用：动比不动好，强度别太低，选自己能坚持的那种。这是第 3 节「情绪低落时先动起来」的展开，不能替代确诊后的规范治疗","money":"0","time":"中","will":"是","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"22.8","sec":22,"n":8,"title":"焦虑到影响生活时，正念减压课的效果不劣于常用的抗焦虑药","cost":"8 周课程，每周一次课加每天在家练习","human":"276 名确诊焦虑障碍的成年人随机分两组，一组上 8 周正念减压课，一组吃艾司西酞普兰，结束时症状改善几乎一样。差别在副作用：吃药那组近八成至少出现一次不良反应、10 人因此退出；上课那组约一成半，没人因此退出。用的是标准化的 8 周课程，不等于随便一个冥想 App。","gain":"美国 3 家城市学术医疗中心的非劣效随机对照试验，276 名确诊焦虑障碍的成年人按 1:1 随机分到 8 周正念减压课程或艾司西酞普兰（10 至 20 mg 弹性剂量），208 人完成。终点时临床总体印象严重度量表评分，正念组下降 1.35、药物组下降 1.43，组间差 −0.07（95% CI −0.38 至 0.23，P=0.65），可信区间下限落在预设的非劣效界值 −0.495 之内。不良事件差别很大：药物组 78.6% 至少发生一次研究相关不良事件、10 人因不良事件退出；正念组 15.4%、无人因不良事件退出","grade":"A","src":"Hoge EA, Bui E, Mete M, Dutton MA, Baker AW, Simon NM (2023). Mindfulness-based stress reduction vs escitalopram for the treatment of adults with anxiety disorders: a randomized clinical trial. JAMA Psychiatry, 80(1), 13-21. <https://doi.org/10.1001/jamapsychiatry.2022.3679>","note":"试验用的是标准化的 8 周正念减压课程（MBSR），不是随便一个冥想 App，两者不能划等号。这条针对的是已经达到焦虑障碍诊断标准的人，该看医生还是要看；它的实际用处是：如果你因为顾虑药物副作用而一直拖着不治疗，还有一个证据强度相当的选项","money":"少","time":"多","will":"是","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"22.9","sec":22,"n":9,"title":"当场想缓过来，用 5 分钟「循环叹息」：吸气两段，呼气拉长","cost":"0 元；每天 5 分钟","human":"每天 5 分钟、连做一个月的对照试验里，三种呼吸练习都比同样时长的正念冥想更能改善情绪、把呼吸频率降下来，其中把呼气拉长的「循环叹息」最好。做法是用鼻子吸一口、再补吸一小口把肺撑满，然后用嘴缓慢吐尽。只有这一项试验、结果还是自己报的，但成本是零。","gain":"远程随机对照试验，比较三种每天 5 分钟的呼吸练习与等时长的正念冥想，持续 1 个月。三种呼吸法是循环叹息（强调延长呼气）、箱式呼吸（吸气、屏息、呼气等长）、带屏息的循环过度换气（吸气长、呼气短）。混合效应模型显示呼吸练习、尤其是以呼气为主的循环叹息，在情绪改善（P<0.05）和呼吸频率下降（P<0.05）上优于正念冥想","grade":"B","src":"Balban MY, Neri E, Kogon MM, et al. (2023). Brief structured respiration practices enhance mood and reduce physiological arousal. Cell Reports Medicine, 4(1), 100895. <https://doi.org/10.1016/j.xcrm.2022.100895>","note":"单项试验、远程自报结局、样本量不大，效应也是「比冥想略好」而不是「解决问题」。但成本是零、5 分钟、随时随地能做，性价比高。做法：用鼻子吸一口，短暂再补吸一小口把肺撑满，然后用嘴把气缓慢长长地吐尽，重复 5 分钟","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"22.10","sec":22,"n":10,"title":"把「定期和人见面」当成健康支出，别只在心情差时才找人","cost":"见面的时间和一点钱","human":"70 项研究、340 万人、平均跟踪 7 年：社会隔离的人同期死亡的概率比不隔离的人高约三成，感到孤独的高约四分之一，独居的高约三成，三者量级相当，而且 65 岁以下的人身上更明显。都是观察数据，去不掉「本来身体就差的人更容易独居」这层反向解释。","gain":"70 项前瞻性研究、340 万名参与者、平均随访 7 年的荟萃分析：社会隔离、孤独感、独居都与死亡率升高相关，控制混杂后的加权平均比值比分别是社会隔离 1.29、孤独 1.26、独居 1.32，三者的效应量相当，且在 65 岁以下人群中比在老年人群中更大","grade":"A","src":"Holt-Lunstad J, Smith TB, Baker M, Harris T, Stephenson D (2015). Loneliness and social isolation as risk factors for mortality: a meta-analytic review. Perspectives on Psychological Science, 10(2), 227-237. <https://doi.org/10.1177/1745691614568352>","note":"争议。全部是观察性数据，反向因果去不掉——身体本来就差的人更容易独居、更少社交。作者的解读是把社会关系当作与吸烟、肥胖同量级的公共卫生因素，但没有随机试验证明「增加社交能降低死亡率」。这条与第 3 节「减少让你消耗的人际关系」不冲突：那条说的是砍掉消耗你的关系，这条说的是保住让你回血的那几段","money":"少","time":"中","will":"些","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"22.11","sec":22,"n":11,"title":"住得离绿地近就多用它，散步、遛弯、坐着都算","cost":"0 元；顺路","human":"9 项研究、7 个国家、832 万人：住处 500 米内的绿化程度每提高 0.1 个植被指数，同期死亡的概率低约 4%。测的是住处周边的绿化，不是你去公园的次数，绿化好的地段住的人往往也更有钱、空气更好。所以别读成「去公园就能延寿」，能用的部分是选住处时把周边绿地算进去。","gain":"9 项队列研究、7 个国家、832 万人的荟萃分析：住处 500 米以内的周边绿化程度每增加 0.1 个归一化植被指数（NDVI），总死亡率的合并风险比为 0.96（95% CI 0.94–0.97）。9 项研究中有 7 项发现显著的负相关，2 项无关联","grade":"A","src":"Rojas-Rueda D, Nieuwenhuijsen MJ, Gascon M, Perez-Leon D, Mudu P (2019). Green spaces and mortality: a systematic review and meta-analysis of cohort studies. The Lancet Planetary Health, 3(11), e469-e477. <https://doi.org/10.1016/S2542-5196(19)30215-3>","note":"争议。研究间异质性极高（I²=95%），而且测的是居住地周边的绿化程度，不是「你去公园的次数」——住在绿化好的地方的人往往也更富、空气更好、更爱运动，混杂难以排除。别把它读成「去公园就能延寿」，可用的部分是：选住处时把周边绿地算进去，成本为零","money":"0","time":"少","will":"否","level":"小","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"}]}]
